import time
import logging
import signal
import sys
import spidev
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

PUMP_PIN = 18
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000
DRY_THRESHOLD = 450
PUMP_RUN_SECONDS = 2
SPI_MAX_SPEED_HZ = 1350000


class SmartGardenController:
    def __init__(self, pump_pin=PUMP_PIN, spi_bus=SPI_BUS, spi_device=SPI_DEVICE, spi_speed=SPI_SPEED_HZ):
        self.pump_pin = pump_pin
        self.spi = None
        self._closed = False
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            logging.error(f"GPIO setup failed: {e}")
            raise
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = spi_speed
            self.spi.mode = 0
        except Exception as e:
            logging.error(f"SPI setup failed: {e}")
            self.close()
            raise

    def read_moisture(self):
        if self.spi is None:
            raise RuntimeError("SPI device not initialized")
        try:
            adc = self.spi.xfer2([1, (8 + 0) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"SPI read error: {e}")
            raise

    def run_pump(self, seconds):
        if self._closed:
            raise RuntimeError("Controller is closed")
        try:
            GPIO.output(self.pump_pin, GPIO.HIGH)
            time.sleep(seconds)
            GPIO.output(self.pump_pin, GPIO.LOW)
        except Exception as e:
            logging.error(f"Pump control error: {e}")
            raise

    def irrigation_cycle(self):
        if self._closed:
            raise RuntimeError("Controller is closed")
        try:
            moisture = self.read_moisture()
            if moisture > DRY_THRESHOLD:
                self.run_pump(PUMP_RUN_SECONDS)
                return True
            return False
        except Exception as e:
            logging.error(f"Irrigation cycle error: {e}")
            raise

    def close(self):
        if self._closed:
            return
        self._closed = True
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"SPI close error: {e}")
            self.spi = None
        try:
            GPIO.cleanup()
        except Exception as e:
            logging.error(f"GPIO cleanup error: {e}")


def schedule_cycles(controller, cycle_count, interval_seconds):
    for i in range(cycle_count):
        try:
            watered = controller.irrigation_cycle()
            logging.info(f"Cycle {i+1}/{cycle_count} - Watered: {watered}")
        except Exception as e:
            logging.error(f"Cycle {i+1}/{cycle_count} failed: {e}")
        if i < cycle_count - 1:
            time.sleep(interval_seconds)


def signal_handler(sig, frame):
    logging.info("Interrupt received, shutting down...")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    controller = None
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if controller is not None:
            controller.close()

