import time
import signal
import sys
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn
import RPi.GPIO as GPIO

# --- Configuration -----------------------------------------------------------
DIR_PIN = 20
STEP_PIN = 21
MS0_PIN = 14
MS1_PIN = 15
PWM_FREQ = 500          # Hz
ADC_GAIN = 1            # PGA gain 1 -> +/- 4.096 V full-scale
ADC_MAX = 2047          # 11-bit signed positive full-scale
ADC_VREF = 4.096        # Volts
ADC_SCALE = ADC_VREF / ADC_MAX

# --- Globals for cleanup -----------------------------------------------------
_pwm = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _pwm
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _init_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(DIR_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(STEP_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(MS0_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(MS1_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.output(DIR_PIN, GPIO.LOW)          # Counter-clockwise
    GPIO.output(MS0_PIN, GPIO.LOW)          # Full step
    GPIO.output(MS1_PIN, GPIO.LOW)          # Full step
    global _pwm
    _pwm = GPIO.PWM(STEP_PIN, PWM_FREQ)
    _pwm.start(0)


def _init_sensors(i2c):
    try:
        accel = adafruit_lsm303_accel.LSM303_Accel(i2c)
    except Exception as exc:
        print(f"Failed to initialize LSM303 accelerometer: {exc}")
        sys.exit(1)
    try:
        mag = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
    except Exception as exc:
        print(f"Failed to initialize LSM303DLH magnetometer: {exc}")
        sys.exit(1)
    try:
        ads = ADS.ADS1015(i2c, address=0x48)
        adc = AnalogIn(ads, ADS.P0, gain=ADC_GAIN)
    except Exception as exc:
        print(f"Failed to initialize ADS1015 ADC: {exc}")
        sys.exit(1)
    return accel, mag, adc


def _read_accel(accel):
    try:
        return accel.acceleration
    except Exception as exc:
        print(f"Error reading accelerometer: {exc}")
        return None


def _read_heading(mag):
    try:
        return mag.magnetic_heading
    except Exception as exc:
        print(f"Error reading magnetometer: {exc}")
        return None


def _read_adc(adc):
    try:
        return adc.value
    except Exception as exc:
        print(f"Error reading ADC: {exc}")
        return None


def _adc_to_voltage(raw):
    if raw is None:
        return None
    return raw * ADC_SCALE


def _voltage_to_duty(voltage):
    if voltage is None:
        return 0
    return int(max(0, min(255, voltage * 64)))


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Failed to initialize I2C bus: {exc}")
        sys.exit(1)

    accel, mag, adc = _init_sensors(i2c)
    _init_gpio()

    try:
        while _running:
            raw = _read_adc(adc)
            voltage = _adc_to_voltage(raw)
            duty = _voltage_to_duty(voltage)

            try:
                _pwm.ChangeDutyCycle(duty)
            except Exception as exc:
                print(f"Error setting PWM duty cycle: {exc}")

            print(f"ADC: {raw}  Voltage: {voltage:.3f} V  PWM duty: {duty}")

            acc = _read_accel(accel)
            if acc is not None:
                print(f"Accel: {acc}")

            heading = _read_heading(mag)
            if heading is not None:
                print(f"Heading: {heading:.2f} deg")

            time.sleep(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

