import RPi.GPIO as GPIO
import time
import sys

# Pin definitions (BCM numbering)
GAS_SENSOR_PIN = 16
WARNING_LED_PIN = 12

# Timing constants
SAMPLE_INTERVAL = 0.5      # seconds between samples
LOW_THRESHOLD = 3           # consecutive LOW readings to trigger alarm
FLASH_ON_TIME = 0.2         # seconds LED stays ON per flash
FLASH_OFF_TIME = 0.2        # seconds LED stays OFF per flash
FLASH_COUNT = 3             # number of flashes per alarm

def setup_gpio():
    """Configure GPIO mode and pins. Returns True on success, False on failure."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GAS_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_OFF)
        GPIO.setup(WARNING_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        return False

def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.output(WARNING_LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def flash_led():
    """Flash the warning LED FLASH_COUNT times."""
    for _ in range(FLASH_COUNT):
        GPIO.output(WARNING_LED_PIN, GPIO.HIGH)
        time.sleep(FLASH_ON_TIME)
        GPIO.output(WARNING_LED_PIN, GPIO.LOW)
        time.sleep(FLASH_OFF_TIME)

def main():
    if not setup_gpio():
        sys.exit(1)

    gas_detected_count = 0

    try:
        while True:
            try:
                gas_value = GPIO.input(GAS_SENSOR_PIN)
            except Exception as e:
                print(f"Error reading gas sensor: {e}", file=sys.stderr)
                time.sleep(SAMPLE_INTERVAL)
                continue

            if gas_value == GPIO.LOW:
                gas_detected_count += 1
                print(f"Gas detected! Count: {gas_detected_count}")
                if gas_detected_count >= LOW_THRESHOLD:
                    print("WARNING: Gas leak detected! Flaring warning LED.")
                    flash_led()
                    gas_detected_count = 0
            else:
                gas_detected_count = 0

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

