import cv2
import signal
import sys
import atexit

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera(resolution=(640, 480)):
    """Initializes the Picamera2 with a preview configuration at value 64."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"format": 'BGR888', "size": resolution},
            controls={"FrameRate": 30.0}
        )
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        raise RuntimeError(f"Error initializing camera: {e}")

def load_cascades():
    """Loads Haar cascade classifiers for face and eye detection."""
    try:
        face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        eye_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_eye.xml')

        if face_cascade.empty() or eye_cascade.empty():
            raise RuntimeError("Error loading cascade classifiers. Check OpenCV data files.")
        return face_cascade, eye_cascade
    except Exception as e:
        raise RuntimeError(f"Error loading cascade classifiers: {e}")

def detect_faces_and_eyes(image, face_cascade, eye_cascade):
    """Detects faces and eyes in an image and draws rectangles around them."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))

    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (0, 255, 0), 2)
        roi_gray = gray[y:y+h, x:x+w]
        eyes = eye_cascade.detectMultiScale(roi_gray, scaleFactor=1.1, minNeighbors=3, minSize=(20, 20))
        for (ex, ey, ew, eh) in eyes:
            cv2.rectangle(image, (x+ex, y+ey), (x+ex+ew, y+ey+eh), (255, 0, 0), 2)
    return image

def main():
    """Main function to run face and eye detection."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = None
    try:
        picam2 = initialize_camera()
        face_cascade, eye_cascade = load_cascades()

        while _running:
            image = picam2.capture_array()
            if image is None:
                print("Warning: Captured empty frame, skipping...", file=sys.stderr)
                continue

            processed_image = detect_faces_and_eyes(image, face_cascade, eye_cascade)
            cv2.imshow("Face and Eye Detection", processed_image)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except RuntimeError as e:
        print(f"Runtime Error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected Error: {e}", file=sys.stderr)
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

