        return config
    except FileNotFoundError:
        logger.warning(f"Configuration file not found: {config_file}. Using defaults.")
        return {}
    except json.JSONDecodeError as e:
        logger.error(f"Invalid JSON in configuration file: {e}. Using defaults.")
        return {}


def initialize_camera(resolution=DEFAULT_RESOLUTION):
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"size": resolution, "format": "RGB888"})
        picam2.configure(config)
        picam2.start()
        logger.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logger.error(f"Error initializing camera: {e}")
        return None


def capture_frame(camera):
    try:
        return camera.capture_array()
    except Exception as e:
        logger.error(f"Error capturing frame: {e}")
        return None


