        sys.exit(1)

    try:
        if recording:
            record_video(camera, recording_filename)

        while _running:
            frame = capture_frame(camera)
            if frame is None:
                time.sleep(0.1)
                continue

            if detect_bird(frame):
                indicate_bird(led_pin)
                if config.get('gpio_door_control', False):
                    control_feeder_door(door_pin, door_open, door_closed, "open")
                    time.sleep(2)
                    control_feeder_door(door_pin, door_open, door_closed, "close")

            time.sleep(0.1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        try:
            camera.stop()
        except Exception:
            pass
        logger.info("Camera released. Exiting.")


if __name__ == "__main__":
    main()

