        """Start the capture loop in a daemon thread."""
        if self.running:
            return
        self.running = True
        threading.Thread(target=self._capture_loop, daemon=True).start()

    def stop(self):
        """Signal the capture loop to stop and release the camera."""
        self.running = False
        if self.camera is not None:
            try:
                self.camera.release()
            except Exception as e:
                logging.error(f"Error releasing camera: {e}")
            self.camera = None

    def _capture_loop(self):
        """Continuously capture frames, encode as JPEG, and enqueue."""
        while self.running:
            try:
                ret, frame = self.camera.read()
                if not ret or frame is None:
                    logging.warning("Failed to capture frame from camera.")
                    time.sleep(0.1)
                    continue

                # Encode to JPEG bytes
                success, encoded = cv2.imencode('.jpg', frame)
                if not success:
                    logging.warning("Failed to encode frame to JPEG.")
                    continue

                try:
                    self.queue.put(encoded.tobytes(), timeout=1.0)
                except Full:
                    try:
                        self.queue.get_nowait()
                    except Empty:
                        pass
                    try:
                        self.queue.put(encoded.tobytes(), timeout=1.0)
                    except Full:
                        logging.warning("Frame queue is full; dropping frame.")

                time.sleep(self.frame_interval)
            except Exception as e:
                logging.error(f"Error in capture loop: {e}")
                time.sleep(0.1)

    def get_frame(self) -> bytes | None:
        """Retrieve a frame from the queue (None if empty)."""
        try:
            return self.queue.get_nowait()
        except Empty:
            return None


class AlertSystem:
    """Manages LED alerts via gpiozero."""

    def __init__(self, gpio_pin: int | None, led_duration: float):
        self.gpio_pin = gpio_pin
        self.led_duration = led_duration
        self.led = None
        self._lock = threading.Lock()
        self._timer: threading.Timer | None = None

        if self.gpio_pin is not None and LED is not None:
            try:
                self.led = LED(gpio_pin)
                logging.info(f"LED initialized on GPIO pin {gpio_pin}.")
            except GPIOZeroError as e:
                logging.error(f"Failed to initialize LED on GPIO {gpio_pin}: {e}")
                self.led = None
        elif self.gpio_pin is not None:
            logging.warning("gpiozero not installed; LED alerts disabled.")

    def trigger_alert(self):
        """Activate the LED for the configured duration."""
        with self._lock:
            if self.led is not None:
                try:
                    self.led.on()
                    self._timer = threading.Timer(
                        self.led_duration, self._turn_off
                    )
                    self._timer.daemon = True
                    self._timer.start()
                except DeviceClosed:
                    logging.error("LED device closed; cannot trigger alert.")
                except Exception as e:
                    logging.error(f"Error triggering LED alert: {e}")

    def _turn_off(self):
        """Turn the LED off after the timer expires."""
        with self._lock:
            if self.led is not None:
                try:
                    self.led.off()
                except Exception as e:
                    logging.error(f"Error turning off LED: {e}")
                self._timer = None

    def cleanup(self):
        """Release the LED resource."""
        with self._lock:
            if self.led is not None:
                try:
                    self.led.off()
                    self.led.close()
                except Exception as e:
                    logging.error(f"Error cleaning up LED: {e}")
                self.led = None
            if self._timer is not None:
                self._timer.cancel()
                self._timer = None


def load_config(config_path: str) -> dict:
    """Load and validate configuration from a JSON file."""
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_path}")
        sys.exit(1)
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}")
        sys.exit(1)

    required_keys = [
        'resolution', 'framerate', 'max_queue_size',
        'motion_threshold', 'gpio_pin', 'led_duration'
    ]
    for key in required_keys:
        if key not in config:
            logging.error(f"Missing required config key: '{key}'")
            sys.exit(1)

    if not isinstance(config['resolution'], (list, tuple)) or len(config['resolution']) != 2:
        logging.error("Invalid 'resolution' format; expected [width, height].")
        sys.exit(1)
    if not isinstance(config['framerate'], int) or config['framerate'] <= 0:
        logging.error("Invalid 'framerate'; must be a positive integer.")
        sys.exit(1)
    if not isinstance(config['max_queue_size'], int) or config['max_queue_size'] <= 0:
        logging.error("Invalid 'max_queue_size'; must be a positive integer.")
        sys.exit(1)
    if not isinstance(config['motion_threshold'], (int, float)) or not (0.0 <= config['motion_threshold'] <= 1.0):
        logging.error("Invalid 'motion_threshold'; must be 0.0-1.0.")
        sys.exit(1)
    if config['gpio_pin'] is not None and not isinstance(config['gpio_pin'], int):
        logging.error("Invalid 'gpio_pin'; must be an integer or null.")
        sys.exit(1)
    if not isinstance(config['led_duration'], (int, float)) or config['led_duration'] < 0:
        logging.error("Invalid 'led_duration'; must be a non-negative number.")
        sys.exit(1)

    return config


def main():
    config = load_config('config.json')

    camera_handler = CameraHandler(
        resolution=tuple(config['resolution']),
        framerate=config['framerate'],
        max_queue_size=config['max_queue_size']
    )
    if not camera_handler.initialize():
        sys.exit(1)

    alert_system = AlertSystem(
        gpio_pin=config['gpio_pin'],
        led_duration=config['led_duration']
    )
    motion_detector = MotionDetector(threshold=config['motion_threshold'])

    running = True

    def signal_handler(signum, frame):
        nonlocal running
        logging.info(f"Signal {signum} received; shutting down.")
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        logging.info("Warming up camera for 2 seconds...")
        time.sleep(2)
        camera_handler.start()
        logging.info("Camera capture started.")

        while running:
            frame = camera_handler.get_frame()
            if frame is None:
                time.sleep(0.1)
                continue

            try:
                decoded = cv2.imdecode(
                    np.frombuffer(frame, dtype=np.uint8),
                    cv2.IMREAD_COLOR
                )
                if decoded is None:
                    logging.warning("Failed to decode JPEG frame.")
                    continue

                if motion_detector.detect(decoded):
                    logging.info("Motion detected!")
                    alert_system.trigger_alert()
            except Exception as e:
                logging.error(f"Error processing frame: {e}")

            time.sleep(0.1)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Cleaning up resources...")
        camera_handler.stop()
        alert_system.cleanup()
        logging.info("Shutdown complete.")


if __name__ == '__main__':
    main()

