import configparser
import signal
import sys
import os

try:
    from gpiozero import Servo, InputDevice
    from gpiozero.pins.pigpio import PiGPIOFactory
except ImportError:
    print("Error: gpiozero and pigpio are required. Install with: pip install gpiozero pigpio", file=sys.stderr)
    sys.exit(1)

try:
    import hydroponics_api as api
except ImportError:
    print("Error: hydroponics_api module not found.", file=sys.stderr)
    sys.exit(1)

CONFIG_FILE = 'config.ini'
LOG_FILE = 'hydroponics.log'
SERVO_PIN = 17
POT_PIN = 18
SERVO_FREQUENCY = 50
MIN_PULSE_WIDTH = 1.0 / 1000
MAX_PULSE_WIDTH = 2.0 / 1000
MIN_ANGLE = 0
MAX_ANGLE = 90
MIN_POT_VALUE = 0.1
MAX_POT_VALUE = 0.9
LOOP_INTERVAL = 5

logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _create_default_config():
    cfg = configparser.ConfigParser()
    cfg['CALIBRATION'] = {
        'min_angle': str(MIN_ANGLE),
        'max_angle': str(MAX_ANGLE),
        'min_pot_value': str(MIN_POT_VALUE),
        'max_pot_value': str(MAX_POT_VALUE),
    }
    try:
        with open(CONFIG_FILE, 'w') as f:
            cfg.write(f)
        logging.info(f"Created default config file: {CONFIG_FILE}")
    except OSError as e:
        logging.error(f"Failed to create default config file: {e}")

def _load_calibration():
    cfg = configparser.ConfigParser()
    if not cfg.read(CONFIG_FILE):
        _create_default_config()
        if not cfg.read(CONFIG_FILE):
            logging.error("Config file still missing after creation.")
            return None
    try:
        return {
            'min_angle': cfg.getint('CALIBRATION', 'min_angle'),
            'max_angle': cfg.getint('CALIBRATION', 'max_angle'),
            'min_pot_value': cfg.getfloat('CALIBRATION', 'min_pot_value'),
            'max_pot_value': cfg.getfloat('CALIBRATION', 'max_pot_value'),
        }
    except (configparser.Error, ValueError) as e:
        logging.error(f"Error reading calibration data: {e}")
        return None

def _map_pot_to_angle(pot_value, cal):
    if cal is None:
        return 0.0
    min_a, max_a = cal['min_angle'], cal['max_angle']
    min_p, max_p = cal['min_pot_value'], cal['max_pot_value']
    if max_p == min_p:
        return (min_a + max_a) / 2.0
    return (pot_value - min_p) * (max_a - min_a) / (max_p - min_p) + min_a

def _read_simulated_pot():
    return random.uniform(0.1, 0.9)

def _read_simulated_temperature():
    return random.uniform(20, 30)

def _read_simulated_greenness():
    return random.randint(0, 100)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cal = _load_calibration()
    if cal is None:
        logging.error("Failed to load calibration. Exiting.")
        sys.exit(1)

    factory = None
    try:
        factory = PiGPIOFactory()
    except Exception as e:
        logging.error(f"Failed to initialize PiGPIOFactory: {e}")
        sys.exit(1)

    servo = None
    pot = None
    try:
        servo = Servo(
            SERVO_PIN,
            initial_value=0.0,
            min_pulse_width=MIN_PULSE_WIDTH,
            max_pulse_width=MAX_PULSE_WIDTH,
            frame_width=1.0 / SERVO_FREQUENCY,
            pin_factory=factory,
        )
        pot = InputDevice(POT_PIN, pin_factory=factory)
    except Exception as e:
        logging.error(f"Failed to initialize GPIO devices: {e}")
        if factory:
            factory.close()
        sys.exit(1)

    try:
        api.init()
    except Exception as e:
        logging.error(f"Failed to initialize API: {e}")
        if servo:
            servo.close()
        if pot:
            pot.close()
        if factory:
            factory.close()
        sys.exit(1)

    try:
        while _running:
            try:
                pot_value = _read_simulated_pot()
                temperature = _read_simulated_temperature()
                greenness = _read_simulated_greenness()
                angle = _map_pot_to_angle(pot_value, cal)

                api.set_vent_angle(angle)
                logging.info(
                    f"Temp: {temperature:.2f}C, Greenness: {greenness}, "
                    f"Pot: {pot_value:.2f}, Vent Angle: {angle:.2f}"
                )
            except Exception as e:
                logging.error(f"Error during control loop: {e}")

            for _ in range(LOOP_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        try:
            api.close()
        except Exception:
            pass
        if servo:
            servo.close()
        if pot:
            pot.close()
        if factory:
            factory.close()
        logging.info("Program terminated gracefully.")

if __name__ == '__main__':
    main()

