import time
import datetime
import sqlite3
import logging
import signal
import sys
import smbus2
import bme280
import ms8607

# Configuration
CONFIG_FILE = "config.txt"
DATABASE_FILE = "wildlife_data.db"
ERROR_LOG_FILE = "error.log"

# Sensor validation ranges
MIN_PRESSURE = 70000
MAX_PRESSURE = 110000
MIN_TEMPERATURE = -20
MAX_TEMPERATURE = 50
MIN_HUMIDITY = 0
MAX_HUMIDITY = 100

# Global state
running = True
db_connection = None
db_cursor = None


def log_error(message):
    """Logs an error message to the error log file with a timestamp."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}")


def load_configuration(config_file):
    """Loads configuration parameters from the specified file."""
    config = {}
    try:
        with open(config_file, "r") as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#"):
                    if "=" not in line:
                        log_error(f"Invalid config line (missing '='): {line}")
                        continue
                    key, value = line.split("=", 1)
                    config[key.strip()] = value.strip()
    except FileNotFoundError:
        log_error(f"Configuration file not found: {config_file}")
    except Exception as e:
        log_error(f"Error loading configuration: {e}")
    return config


def initialize_database():
    """Initializes the SQLite database and creates the sensor_data table if it doesn't exist."""
    global db_connection, db_cursor
    try:
        db_connection = sqlite3.connect(DATABASE_FILE)
        db_cursor = db_connection.cursor()
        db_cursor.execute("""
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        """)
        db_connection.commit()
    except sqlite3.Error as e:
        log_error(f"Database initialization error: {e}")
        raise


def read_bmp280_data(i2c_bus, address):
    """Reads pressure and temperature data from a BMP280 sensor."""
    try:
        calibration_params = bme280.load_calibration_params(i2c_bus, address)
        data = bme280.read_adc(i2c_bus, address)
        pressure = bme280.sea_level_pressure(data, calibration_params)
        temperature = bme280.temperature(data, calibration_params)
        return pressure, temperature
    except Exception as e:
        log_error(f"Error reading BMP280 data at address {address}: {e}")
        return None, None


def read_bme280_data(i2c_bus, address):
    """Reads pressure, temperature, and humidity data from a BME280 sensor."""
    try:
        calibration_params = bme280.load_calibration_params(i2c_bus, address)
        data = bme280.read_adc(i2c_bus, address)
        pressure = bme280.sea_level_pressure(data, calibration_params)
        temperature = bme280.temperature(data, calibration_params)
        humidity = bme280.humidity(data, calibration_params)
        return pressure, temperature, humidity
    except Exception as e:
        log_error(f"Error reading BME280 data at address {address}: {e}")
        return None, None, None


def read_ms8607_data(i2c_bus, address):
    """Reads pressure, temperature, and humidity data from an MS8607 sensor."""
    try:
        sensor = ms8607.MS8607(i2c_bus, address=address)
        pressure = sensor.pressure()
        temperature = sensor.temperature()
        humidity = sensor.humidity()
        return pressure, temperature, humidity
    except Exception as e:
        log_error(f"Error reading MS8607 data at address {address}: {e}")
        return None, None, None


def validate_data(pressure, temperature, humidity=None):
    """Validates sensor readings against predefined ranges."""
    if pressure is not None and not (MIN_PRESSURE <= pressure <= MAX_PRESSURE):
        log_error(f"Invalid pressure reading: {pressure}")
        return False
    if temperature is not None and not (MIN_TEMPERATURE <= temperature <= MAX_TEMPERATURE):
        log_error(f"Invalid temperature reading: {temperature}")
        return False
    if humidity is not None and not (MIN_HUMIDITY <= humidity <= MAX_HUMIDITY):
        log_error(f"Invalid humidity reading: {humidity}")
        return False
    return True


def store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity):
    """Stores sensor data in the SQLite database."""
    try:
        db_cursor.execute("""
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        db_connection.commit()
    except sqlite3.Error as e:
        log_error(f"Database insertion error: {e}")


def signal_handler(sig, frame):
    """Handles SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    print("\nSIGINT received. Shutting down gracefully...")
    running = False


def cleanup():
    """Closes the database connection and performs any required cleanup."""
    global db_connection
    if db_connection:
        try:
            db_connection.close()
            print("Database connection closed.")
        except sqlite3.Error as e:
            print(f"Error closing database connection: {e}")


def main():
    """Main function to read sensor data, validate it, and store it in the database."""
    global running

    signal.signal(signal.SIGINT, signal_handler)

    config = load_configuration(CONFIG_FILE)
    if not config:
        print("No configuration loaded. Exiting.")
        sys.exit(0)

    try:
        initialize_database()
    except sqlite3.Error:
        print("Failed to initialize database. Exiting.")
        sys.exit(0)

    sampling_interval = int(config.get("Sampling_Interval_Seconds", 60))

    sensors = []
    for i in range(1, 4):
        sensor_type = config.get(f"Sensor{i}_Type")
        sensor_address = config.get(f"Sensor{i}_Address")
        sensor_id = config.get(f"Sensor{i}_ID")

        if sensor_type and sensor_address and sensor_id:
            try:
                sensor_address = int(sensor_address, 16)
                sensors.append({
                    "type": sensor_type,
                    "address": sensor_address,
                    "id": sensor_id
                })
            except ValueError:
                log_error(f"Invalid sensor address for Sensor{i}: {sensor_address}")

    if not sensors:
        print("No sensors configured. Exiting.")
        cleanup()
        sys.exit(0)

    try:
        i2c_bus = smbus2.SMBus(1)
    except Exception as e:
        log_error(f"Failed to initialize I2C bus 1: {e}")
        cleanup()
        sys.exit(0)

    try:
        while running:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

            for sensor in sensors:
                if not running:
                    break

                sensor_type = sensor["type"]
                sensor_address = sensor["address"]
                sensor_id = sensor["id"]

                if sensor_type == "BMP280":
                    pressure, temperature = read_bmp280_data(i2c_bus, sensor_address)
                    humidity = None
                elif sensor_type == "BME280":
                    pressure, temperature, humidity = read_bme280_data(i2c_bus, sensor_address)
                elif sensor_type == "MS8607":
                    pressure, temperature, humidity = read_ms8607_data(i2c_bus, sensor_address)
                else:
                    log_error(f"Unknown sensor type: {sensor_type}")
                    continue

                if pressure is not None and temperature is not None:
                    if validate_data(pressure, temperature, humidity):
                        store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity)
                    else:
                        log_error(f"Invalid data from sensor {sensor_id} at address {sensor_address}")
                else:
                    log_error(f"Failed to read data from sensor {sensor_id} at address {sensor_address}")

            if running:
                time.sleep(sampling_interval)

    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

