import asyncio
import datetime
import json
import os
import signal
import sqlite3
import threading
import time

import board
import busio
import adafruit_bme280

try:
    import flask
except ImportError:
    flask = None

DATABASE_FILE = 'weather_data.db'
I2C_BUS = board.I2C()
BME280_SENSOR = None
WEB_APP = None
DB_CONNECTION = None
DB_LOCK = threading.Lock()
SHUTDOWN_EVENT = threading.Event()
SYNC_INTERVAL = 300
PING_TIMEOUT = 3
PING_TARGET = '8.8.8.8'
SENSOR_INTERVAL = 60
MAX_RETRIES = 3
RETRY_DELAY = 1
REINIT_DELAY = 2

HTML_TEMPLATE = '''<!DOCTYPE html>
<html>
<head><title>Weather Station</title></head>
<body>
<h1>Weather Station</h1>
<p>Last Updated: {timestamp}</p>
<p>Temperature: {temperature:.2f} &deg;C</p>
<p>Humidity: {humidity:.2f} %</p>
<p>Pressure: {pressure:.2f} hPa</p>
</body>
</html>'''


def init_sensor():
    global BME280_SENSOR
    try:
        BME280_SENSOR = adafruit_bme280.Adafruit_BME280_I2C(I2C_BUS, address=0x76)
        BME280_SENSOR.sea_level_pressure = 1013.25
        return True
    except Exception as e:
        print(f"Sensor init failed: {e}")
        BME280_SENSOR = None
        return False


def read_sensor_data():
    if BME280_SENSOR is None:
        return None, None, None
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return BME280_SENSOR.temperature, BME280_SENSOR.humidity, BME280_SENSOR.pressure
        except Exception as e:
            print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    return None, None, None


def store_data(temperature, humidity, pressure):
    if temperature is None or humidity is None or pressure is None:
        return
    timestamp = datetime.datetime.utcnow().isoformat()
    with DB_LOCK:
        try:
            cursor = DB_CONNECTION.cursor()
            cursor.execute(
                "INSERT OR REPLACE INTO readings (timestamp, temperature, humidity, pressure) VALUES (?, ?, ?, ?)",
                (timestamp, temperature, humidity, pressure),
            )
            DB_CONNECTION.commit()
        except sqlite3.Error as e:
            print(f"DB error: {e}")


def get_latest_data():
    with DB_LOCK:
        try:
            cursor = DB_CONNECTION.cursor()
            cursor.execute(
                "SELECT timestamp, temperature, humidity, pressure FROM readings ORDER BY timestamp DESC LIMIT 1"
            )
            row = cursor.fetchone()
            if row:
                return row[0], row[1], row[2], row[3]
        except sqlite3.Error as e:
            print(f"DB error: {e}")
    return None, None, None, None


def get_last_24_hours():
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(hours=24)
    with DB_LOCK:
        try:
            cursor = DB_CONNECTION.cursor()
            cursor.execute(
                "SELECT timestamp, temperature, humidity, pressure FROM readings WHERE timestamp >= ? ORDER BY timestamp DESC",
                (cutoff.isoformat(),),
            )
            return cursor.fetchall()
        except sqlite3.Error as e:
            print(f"DB error: {e}")
            return []


def create_database():
    global DB_CONNECTION
    try:
        DB_CONNECTION = sqlite3.connect(DATABASE_FILE, check_same_thread=False)
        cursor = DB_CONNECTION.cursor()
        cursor.execute(
            "CREATE TABLE IF NOT EXISTS readings (timestamp TEXT PRIMARY KEY, temperature REAL, humidity REAL, pressure REAL)"
        )
        DB_CONNECTION.commit()
    except sqlite3.Error as e:
        print(f"DB init error: {e}")
        raise


def init_web_app():
    global WEB_APP
    if flask is None:
        print("Flask not installed; web app disabled.")
        return None
    WEB_APP = flask.Flask(__name__)

    @WEB_APP.route('/')
    def index():
        ts, t, h, p = get_latest_data()
        if ts:
            return HTML_TEMPLATE.format(timestamp=ts, temperature=t, humidity=h, pressure=p)
        return 'No data available'

    @WEB_APP.route('/history')
    def history():
        data = get_last_24_hours()
        return flask.Response(
            json.dumps(data),
            mimetype='application/json',
        )

    return WEB_APP


def run_web_server(app):
    if app is None:
        return
    try:
        app.run(host='0.0.0.0', port=5000, debug=False, use_reloader=False)
    except Exception as e:
        print(f"Web server error: {e}")


def check_internet_connectivity():
    try:
        import subprocess
        result = subprocess.run(
            ['ping', '-c', '1', '-W', str(PING_TIMEOUT), PING_TARGET],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        return result.returncode == 0
    except Exception as e:
        print(f"Connectivity check error: {e}")
        return False


async def synchronize_data():
    while not SHUTDOWN_EVENT.is_set():
        if check_internet_connectivity():
            print("Internet connected. Simulating data synchronization...")
        else:
            print("No internet connection. Skipping synchronization.")
        await asyncio.sleep(SYNC_INTERVAL)


def sensor_collection_loop():
    while not SHUTDOWN_EVENT.is_set():
        t, h, p = read_sensor_data()
        if t is not None and h is not None and p is not None:
            store_data(t, h, p)
        else:
            print("Sensor read failed after retries. Re-initializing sensor.")
            if not init_sensor():
                print("Sensor re-initialization failed.")
            time.sleep(REINIT_DELAY)
        SHUTDOWN_EVENT.wait(SENSOR_INTERVAL)


def signal_handler(signum, frame):
    print(f"Signal {signum} received. Shutting down...")
    SHUTDOWN_EVENT.set()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        create_database()
    except Exception:
        print("Failed to initialize database. Exiting.")
        return

    if not init_sensor():
        print("Failed to initialize BME280 sensor. Exiting.")
        if DB_CONNECTION:
            DB_CONNECTION.close()
        return

    web_app = init_web_app()
    web_thread = threading.Thread(target=run_web_server, args=(web_app,), daemon=True)
    web_thread.start()

    sensor_thread = threading.Thread(target=sensor_collection_loop, daemon=True)
    sensor_thread.start()

    try:
        asyncio.run(synchronize_data())
    except asyncio.CancelledError:
        pass
    finally:
        SHUTDOWN_EVENT.set()
        sensor_thread.join(timeout=5)
        web_thread.join(timeout=5)
        if DB_CONNECTION:
            DB_CONNECTION.close()
        print("Shutdown complete.")


if __name__ == '__main__':
    main()

