import time
import logging
import signal
import sys
import numpy as np
import cv2

try:
    from picamera2 import Picamera2
except ImportError:
    logging.error("picamera2 library is not installed. Install with: pip install picamera2")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CAMERA_WIDTH = 640
CAMERA_HEIGHT = 480
FRAME_RATE = 30
FRAME_DURATION_LIMIT = int(1e6 / FRAME_RATE)  # microseconds
DISPLAY_WINDOW_NAME = "Dual CSI Cameras"
EXIT_KEY = 27  # ESC

running = True

def signal_handler(sig, frame):
    global running
    logging.info(f"Signal {sig} received, shutting down gracefully...")
    running = False

def initialize_camera(camera_num):
    try:
        cam = Picamera2(camera_num=camera_num)
        config = cam.create_preview_configuration(
            main={"size": (CAMERA_WIDTH, CAMERA_HEIGHT), "format": "RGB888"}
        )
        cam.configure(config)
        cam.set_controls({"FrameDurationLimits": (FRAME_DURATION_LIMIT, FRAME_DURATION_LIMIT)})
        cam.start()
        logging.info(f"Camera {camera_num} initialized successfully.")
        return cam
    except Exception as e:
        logging.error(f"Error initializing camera {camera_num}: {e}")
        return None

def capture_frame(cam):
    try:
        return cam.capture_array()
    except Exception as e:
        logging.error(f"Error capturing frame: {e}")
        return None

def display_frames(frame1, frame2):
    try:
        combined = np.hstack((frame1, frame2))
        cv2.imshow(DISPLAY_WINDOW_NAME, combined)
        return cv2.waitKey(30) & 0xFF
    except Exception as e:
        logging.error(f"Error displaying frames: {e}")
        return -1

def is_window_open(window_name):
    try:
        return cv2.getWindowProperty(window_name, cv2.WND_PROP_AUTOSIZE) >= 0
    except Exception:
        return False

def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cam1 = initialize_camera(0)
    cam2 = initialize_camera(1)

    if cam1 is None or cam2 is None:
        logging.error("One or both cameras failed to initialize. Exiting.")
        if cam1:
            cam1.stop()
        if cam2:
            cam2.stop()
        cv2.destroyAllWindows()
        return

    try:
        while running:
            frame1 = capture_frame(cam1)
            frame2 = capture_frame(cam2)

            if frame1 is None or frame2 is None:
                logging.warning("Failed to capture frame from one or both cameras.")
                time.sleep(0.1)
                continue

            key = display_frames(frame1, frame2)

            if key == EXIT_KEY or not is_window_open(DISPLAY_WINDOW_NAME):
