import logging
import configparser
import signal
import sys
import threading

try:
    from picamera2 import Picamera2
    from picamera2.encoders import H264Encoder
    from picamera2.outputs import FileOutput
    PICAMERA2_AVAILABLE = True
except ImportError:
    PICAMERA2_AVAILABLE = False

try:
    import RPi.GPIO as GPIO
    GPIO_AVAILABLE = True
except ImportError:
    GPIO_AVAILABLE = False

DEFAULT_CONFIG = {
    'storage_directory': '/home/pi/security_camera',
    'pir_pin': '4',
    'image_quality': '85',
    'image_bitrate': '64',
    'video_bitrate': '1700000',
    'video_fps': '20',
    'video_duration': '5',
    'image_interval': '0.5',
    'disk_space_threshold_mb': '1000',
    'log_file': '/home/pi/security_camera/logs/security_camera.log',
}

_running = True
_lock = threading.Lock()


def _signal_handler(signum, frame):
    global _running
    logging.info(f"Received signal {signum}, shutting down...")
    _running = False


def _setup_logging(log_file):
    log_dir = os.path.dirname(log_file)
    if log_dir and not os.path.isdir(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except OSError as e:
            print(f"Cannot create log directory {log_dir}: {e}", file=sys.stderr)
            log_dir = os.path.join(os.getcwd(), 'logs')
            log_file = os.path.join(log_dir, 'security_camera.log')
            try:
                os.makedirs(log_dir, exist_ok=True)
            except OSError:
                log_file = 'security_camera.log'
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )
    console = logging.StreamHandler()
    console.setLevel(logging.INFO)
    console.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
    logging.getLogger().addHandler(console)


def _load_config(config_file):
    config = configparser.ConfigParser()
    if not os.path.isfile(config_file):
        try:
            with open(config_file, 'w') as f:
                for section, key, value in [
                    ('DEFAULT', 'storage_directory', DEFAULT_CONFIG['storage_directory']),
                    ('DEFAULT', 'pir_pin', DEFAULT_CONFIG['pir_pin']),
                    ('DEFAULT', 'image_quality', DEFAULT_CONFIG['image_quality']),
                    ('DEFAULT', 'image_bitrate', DEFAULT_CONFIG['image_bitrate']),
                    ('DEFAULT', 'video_bitrate', DEFAULT_CONFIG['video_bitrate']),
                    ('DEFAULT', 'video_fps', DEFAULT_CONFIG['video_fps']),
                    ('DEFAULT', 'video_duration', DEFAULT_CONFIG['video_duration']),
                    ('DEFAULT', 'image_interval', DEFAULT_CONFIG['image_interval']),
                    ('DEFAULT', 'disk_space_threshold_mb', DEFAULT_CONFIG['disk_space_threshold_mb']),
                    ('DEFAULT', 'log_file', DEFAULT_CONFIG['log_file']),
                ]:
                    config[section] = {key: value}
                config.write(f)
        except OSError as e:
            logging.error(f"Could not create default config file {config_file}: {e}")
    config.read(config_file)
    return config


def _ensure_storage(storage_directory):
    try:
        os.makedirs(storage_directory, exist_ok=True)
    except OSError as e:
        logging.error(f"Cannot create storage directory {storage_directory}: {e}")
        return False
    return True


def _check_disk_space(storage_directory, disk_space_threshold_mb):
    try:
        statvfs = os.statvfs(storage_directory)
        available_bytes = statvfs.f_bavail * statvfs.f_frsize
        available_mb = available_bytes / (1024 * 1024)
        return available_mb > float(disk_space_threshold_mb)
    except OSError as e:
        logging.error(f"Error checking disk space: {e}")
        return False


def _manage_disk_space(storage_directory, disk_space_threshold_mb):
    if _check_disk_space(storage_directory, disk_space_threshold_mb):
        return
    logging.warning("Disk space low, deleting old files...")
    try:
        files = []
        for root, _, filenames in os.walk(storage_directory):
            for filename in filenames:
                filepath = os.path.join(root, filename)
                try:
                    mtime = os.path.getmtime(filepath)
                    files.append((filepath, mtime))
                except OSError:
                    continue
        files.sort(key=lambda x: x[1])
        total_deleted = 0
        for filepath, _ in files:
            if _check_disk_space(storage_directory, disk_space_threshold_mb):
                break
            try:
                size = os.path.getsize(filepath)
                os.remove(filepath)
                total_deleted += size
                logging.info(f"Deleted old file: {filepath}")
            except OSError as e:
                logging.error(f"Error deleting file {filepath}: {e}")
        if total_deleted > 0:
            logging.info(f"Deleted {total_deleted / (1024 * 1024):.2f} MB of data")
        else:
            logging.warning("No files could be deleted to free up space.")
    except OSError as e:
        logging.error(f"Error managing disk space: {e}")


def _capture_images(picam2, storage_directory, image_quality, image_bitrate, image_interval):
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    image_dir = os.path.join(storage_directory, datetime.datetime.now().strftime("%Y/%m/%d"))
    try:
        os.makedirs(image_dir, exist_ok=True)
    except OSError as e:
        logging.error(f"Cannot create image directory {image_dir}: {e}")
        return
    for i in range(3):
        if not _running:
            return
        image_path = os.path.join(image_dir, f"{timestamp}_{i+1}.jpg")
        try:
            picam2.capture_file(image_path, format='jpeg', quality=int(image_quality))
            logging.info(f"Captured image: {image_path}")
        except Exception as e:
            logging.error(f"Error capturing image {image_path}: {e}")
            return
        time.sleep(float(image_interval))


