    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    video_dir = os.path.join(storage_directory, datetime.datetime.now().strftime("%Y/%m/%d"))
    try:
        os.makedirs(video_dir, exist_ok=True)
    except OSError as e:
        logging.error(f"Cannot create video directory {video_dir}: {e}")
        return
    video_path = os.path.join(video_dir, f"{timestamp}.h264")
    try:
        encoder = H264Encoder(bitrate=int(video_bitrate), framerate=int(video_fps))
        output = FileOutput(video_path)
        picam2.start_recording(encoder, output)
        logging.info(f"Started recording video: {video_path}")
        time.sleep(float(video_duration))
        picam2.stop_recording()
        logging.info(f"Stopped recording video: {video_path}")
    except Exception as e:
        logging.error(f"Error capturing video {video_path}: {e}")
        try:
            picam2.stop_recording()
        except Exception:
            pass


def _motion_detected_callback(channel, picam2, storage_directory, image_quality, image_bitrate, image_interval, video_bitrate, video_fps, video_duration):
    logging.info("Motion detected!")
    _capture_images(picam2, storage_directory, image_quality, image_bitrate, image_interval)
    _capture_video(picam2, storage_directory, video_bitrate, video_fps, video_duration)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config_file = 'config.ini'
    config = _load_config(config_file)

    storage_directory = config.get('DEFAULT', 'storage_directory', fallback=DEFAULT_CONFIG['storage_directory'])
    pir_pin = config.getint('DEFAULT', 'pir_pin', fallback=int(DEFAULT_CONFIG['pir_pin']))
    image_quality = config.getint('DEFAULT', 'image_quality', fallback=int(DEFAULT_CONFIG['image_quality']))
    image_bitrate = config.getint('DEFAULT', 'image_bitrate', fallback=int(DEFAULT_CONFIG['image_bitrate']))
    video_bitrate = config.getint('DEFAULT', 'video_bitrate', fallback=int(DEFAULT_CONFIG['video_bitrate']))
    video_fps = config.getint('DEFAULT', 'video_fps', fallback=int(DEFAULT_CONFIG['video_fps']))
    video_duration = config.getint('DEFAULT', 'video_duration', fallback=int(DEFAULT_CONFIG['video_duration']))
    image_interval = config.getfloat('DEFAULT', 'image_interval', fallback=float(DEFAULT_CONFIG['image_interval']))
    disk_space_threshold_mb = config.getint('DEFAULT', 'disk_space_threshold_mb', fallback=int(DEFAULT_CONFIG['disk_space_threshold_mb']))
    log_file = config.get('DEFAULT', 'log_file', fallback=DEFAULT_CONFIG['log_file'])

    _setup_logging(log_file)
    logging.info("Starting security camera system...")

    if not _ensure_storage(storage_directory):
        logging.error("Failed to initialize storage. Exiting.")
        return

    picam2 = None
    if PICAMERA2_AVAILABLE:
        try:
            picam2 = Picamera2()
            picam2.configure(picam2.create_still_configuration())
            picam2.start()
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize camera: {e}")
            picam2 = None
    else:
        logging.warning("picamera2 library not found. Running in degraded mode without camera.")

    if GPIO_AVAILABLE:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(pir_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info(f"PIR sensor initialized on GPIO {pir_pin}.")
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            if picam2:
                try:
                    picam2.stop()
                except Exception:
                    pass
            return
    else:
        logging.warning("RPi.GPIO library not found. Running in degraded mode without PIR sensor.")

    try:
        while _running:
            if picam2 is None:
                time.sleep(1)
                continue
            if GPIO_AVAILABLE:
                try:
                    if GPIO.input(pir_pin):
                        _motion_detected_callback(
                            pir_pin, picam2, storage_directory, image_quality, image_bitrate, image_interval,
                            video_bitrate, video_fps, video_duration,
                        )
                        time.sleep(2)
                except Exception as e:
                    logging.error(f"Error reading PIR sensor: {e}")
            else:
                time.sleep(1)
            _manage_disk_space(storage_directory, disk_space_threshold_mb)
    finally:
        logging.info("Shutting down security camera system...")
        if picam2:
            try:
                picam2.stop()
            except Exception:
                pass
        if GPIO_AVAILABLE:
            try:
                GPIO.cleanup()
            except Exception:
                pass
        logging.info("Security camera system stopped.")


if __name__ == "__main__":
    main()

