    "sensor2": {"trigger": 22, "echo": 23, "offset": 0.0, "max_distance": 200.0},
    "sensor3": {"trigger": 24, "echo": 25, "offset": 0.0, "max_distance": 200.0},
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
        if not isinstance(cfg, dict):
            raise ValueError("config.json must be a JSON object")
        return cfg
    except FileNotFoundError:
        logging.warning("config.json not found; using defaults.")
    except (json.JSONDecodeError, ValueError) as e:
        logging.error(f"Error parsing config.json: {e}; using defaults.")
    return DEFAULT_CONFIG.copy()


def initialize_gpio(gpio, config):
    if gpio is None:
        logging.error("RPi.GPIO not available; cannot initialize GPIO.")
        return False
    try:
        gpio.setmode(gpio.BCM)
        gpio.setwarnings(False)
        for sid in ("sensor1", "sensor2", "sensor3"):
            trig = config.get(sid, {}).get("trigger")
            echo = config.get(sid, {}).get("echo")
            if trig is None or echo is None:
                logging.error(f"Missing trigger/echo for {sid} in config.")
                return False
            gpio.setup(trig, gpio.OUT, initial=gpio.LOW)
            gpio.setup(echo, gpio.IN)
        return True
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        return False


def measure_distance(gpio, trigger_pin, echo_pin, max_distance, timeout=0.05):
    if gpio is None:
        return None
    try:
        gpio.output(trigger_pin, gpio.LOW)
        time.sleep(0.000002)
        gpio.output(trigger_pin, gpio.HIGH)
        time.sleep(0.00001)
        gpio.output(trigger_pin, gpio.LOW)

        deadline = time.time() + timeout
        while gpio.input(echo_pin) == 0:
            if time.time() > deadline:
                logging.warning(f"Timeout waiting for echo rising edge on pin {echo_pin}.")
                return None

        pulse_start = time.time()
        deadline = time.time() + timeout
        while gpio.input(echo_pin) == 1:
            if time.time() > deadline:
                logging.warning(f"Timeout waiting for echo falling edge on pin {echo_pin}.")
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150.0
        distance = round(distance, 2)

        if distance > max_distance:
            logging.warning(f"Distance {distance} cm exceeds max_distance {max_distance} cm.")
            return None
        return distance
    except Exception as e:
        logging.error(f"Error measuring distance on trigger {trigger_pin}, echo {echo_pin}: {e}")
        return None


def calculate_water_level(sensor_data):
    distances = [d for d in sensor_data if d is not None]
    if not distances:
        logging.warning("No valid sensor readings available.")
        return None
    return median(distances)


def check_alerts(water_level, config, last_alert_time):
    low = config.get("alert_threshold_low", DEFAULT_CONFIG["alert_threshold_low"])
    high = config.get("alert_threshold_high", DEFAULT_CONFIG["alert_threshold_high"])
    delay = config.get("alert_repeat_delay", DEFAULT_CONFIG["alert_repeat_delay"])
    now = datetime.now()
    if water_level is not None:
        if water_level < low and (last_alert_time is None or (now - last_alert_time).total_seconds() > delay):
            logging.warning(f"ALERT: Water level too low! Level: {water_level:.2f} cm")
            return now
        if water_level > high and (last_alert_time is None or (now - last_alert_time).total_seconds() > delay):
            logging.warning(f"ALERT: Water level too high! Level: {water_level:.2f} cm")
            return now
    return last_alert_time


def cleanup_gpio(gpio):
    if gpio is not None:
        try:
            gpio.cleanup()
        except Exception:
            pass


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config()
    log_file = config.get("log_file", DEFAULT_CONFIG["log_file"])
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Starting water level monitoring system...")

    gpio = GPIO
    if not initialize_gpio(gpio, config):
        logging.error("GPIO initialization failed. Exiting.")
        cleanup_gpio(gpio)
        sys.exit(0)

    sensor_errors = {sid: 0 for sid in ("sensor1", "sensor2", "sensor3")}
    last_alert_time = None

    try:
        while _running:
            sensor_data = []
            for sid in ("sensor1", "sensor2", "sensor3"):
                trig = config.get(sid, {}).get("trigger")
                echo = config.get(sid, {}).get("echo")
                offset = config.get(sid, {}).get("offset", 0.0)
                max_dist = config.get(sid, {}).get("max_distance", 200.0)
                if trig is None or echo is None:
                    logging.error(f"Missing trigger/echo for {sid}; skipping.")
                    sensor_data.append(None)
                    continue
                dist = measure_distance(gpio, trig, echo, max_dist)
                if dist is None:
                    sensor_errors[sid] += 1
                    if sensor_errors[sid] >= 5:
                        logging.error(f"Sensor {sid} failed 5 times consecutively. Excluding.")
                    sensor_data.append(None)
                else:
                    sensor_errors[sid] = 0
                    sensor_data.append(dist + offset)

            water_level = calculate_water_level(sensor_data)
            if water_level is not None:
                logging.info(f"Water level: {water_level:.2f} cm")
            else:
                logging.warning("Could not calculate water level.")

            last_alert_time = check_alerts(water_level, config, last_alert_time)

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Exiting water level monitoring system.")
        cleanup_gpio(gpio)
        sys.exit(0)


if __name__ == "__main__":
    main()

