import random
import os
import logging
from typing import Optional, Tuple

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

try:
    import RPi.GPIO as GPIO
except ImportError:
    logging.warning("RPi.GPIO not found; using mock GPIO.")
    GPIO = None

try:
    import adafruit_dht
    import board
    DHT_LIB_AVAILABLE = True
except ImportError:
    logging.warning("adafruit-circuitpython-dht or board not found; simulating DHT11.")
    DHT_LIB_AVAILABLE = False

try:
    from picamera2 import Picamera2
    CAMERA_AVAILABLE = True
except ImportError:
    logging.warning("picamera2 not found; simulating camera.")
    CAMERA_AVAILABLE = False

try:
    import speech_recognition as sr
except ImportError:
    logging.error("speech_recognition not found. Please install it.")
    sys.exit(1)

DHT_PIN = 4
LIGHT_PIN = 17
WAKE_WORD = "Greenhouse"
TEMPERATURE_RANGE = (15, 35)
LISTENING_TIMEOUT = 5

_running = True

def signal_handler(sig, frame):
    global _running
    _running = False
    logging.info("Termination signal received. Cleaning up...")

def setup_gpio():
    if GPIO is None:
        logging.info("Mock GPIO setup complete.")
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO setup complete.")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        raise

def cleanup_gpio():
    if GPIO is not None:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleanup complete.")
        except Exception as e:
            logging.error(f"GPIO cleanup failed: {e}")

def read_temperature() -> Tuple[Optional[float], Optional[str]]:
    if not DHT_LIB_AVAILABLE:
        return random.uniform(*TEMPERATURE_RANGE), "Simulated"
    try:
        dht_device = adafruit_dht.DHT11(board.D4)
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("DHT11 returned None for temperature or humidity.")
        return temperature, "Real"
    except Exception as e:
        logging.error(f"DHT11 read failed: {e}. Using simulated temperature.")
        return random.uniform(*TEMPERATURE_RANGE), "Simulated"

def control_lights(action: str) -> str:
    if action == "on":
        if GPIO is not None:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
        return "Lights turned on."
    elif action == "off":
        if GPIO is not None:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
        return "Lights turned off."
    else:
        return "Invalid light action."

def take_picture() -> str:
    if not CAMERA_AVAILABLE:
        return "Camera unavailable. Picture not taken."
    try:
        picam2 = Picamera2()
        timestamp = time.strftime("%Y%m%d-%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        picam2.start()
        time.sleep(2)
        picam2.capture_file(filename)
        picam2.stop()
        picam2.close()
        return f"Picture saved as {filename}"
    except Exception as e:
        logging.error(f"Camera error: {e}")
        return "Failed to take picture."

def process_command(command: str) -> str:
    command = command.lower()
    if "turn on the lights" in command:
        return control_lights("on")
    elif "turn off the lights" in command:
        return control_lights("off")
    elif "what is the temperature" in command:
        temperature, source = read_temperature()
        return f"Temperature is {temperature:.1f}°C ({source})."
    elif "take a picture" in command:
        return take_picture()
    else:
        return "Unknown command."

def listen_for_command() -> Optional[str]:
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            print("Adjusting for ambient noise...")
            recognizer.adjust_for_ambient_noise(source, duration=1)
            print("Say something!")
            audio = recognizer.listen(source, timeout=LISTENING_TIMEOUT)
    except sr.WaitTimeoutError:
        return None
    except Exception as e:
        logging.error(f"Microphone error: {e}")
        return None

    try:
        text = recognizer.recognize_google(audio)
        logging.info(f"Recognized: {text}")
        return text
    except sr.UnknownValueError:
        logging.warning("Could not understand audio")
        return None
    except sr.RequestError as e:
        logging.error(f"Could not request results from Google Web Speech API; {e}")
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        setup_gpio()
    except Exception:
        logging.warning("Continuing without GPIO control.")

    try:
        while _running:
            print("Listening for wake word...")
            command = listen_for_command()
            if command and WAKE_WORD.lower() in command.lower():
                print("Wake word detected!")
                print("Listening for command...")
                command = listen_for_command()
                if command:
                    response = process_command(command)
                    print(response)
            time.sleep(0.1)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

