        self.setup_logging()
        self.camera = None
        self.light_sensor = None
        self.gpio_pin = None
        self.running = True
        self.motion_detected = False
        self.last_motion_time = 0
        self.frame_queue = queue.Queue(maxsize=10)
        self.circular_buffer = []
        self.lock = threading.Lock()
        self.light_sensor_data = []
        self.light_sensor_thread = None
        self.light_sensor_interval = 5
        self.disk_space_limit = 1000
        self.setup_camera()
        self.setup_light_sensor()
        self.setup_gpio()
        self.setup_signal_handlers()

    def load_config(self):
        for key, default_value in DEFAULT_CONFIG.items():
            try:
                if key in self.config["DEFAULT"]:
                    value = self.config["DEFAULT"][key]
                    if isinstance(default_value, int):
                        self.settings[key] = int(value)
                    elif isinstance(default_value, float):
                        self.settings[key] = float(value)
                    else:
                        self.settings[key] = value
                else:
                    self.settings[key] = default_value
            except (KeyError, ValueError, TypeError) as e:
                logging.warning(f"Error loading config parameter '{key}': {e}. Using default value: {default_value}")
                self.settings[key] = default_value

    def setup_logging(self):
        log_level = self.settings.get("log_level", "INFO").upper()
        numeric_level = getattr(logging, log_level, None)
        if not isinstance(numeric_level, int):
            logging.warning(f"Invalid log level: {log_level}. Defaulting to INFO.")
            numeric_level = logging.INFO
        logging.basicConfig(filename=self.log_file, level=numeric_level,
                            format='%(asctime)s - %(levelname)s - %(message)s')

    def setup_camera(self):
        try:
            self.camera = picamera2.Picamera2()
            config = self.camera.create_video_configuration(
                main={"size": (640, 480), "format": "YUV420"},
                lores={"size": (320, 240), "format": "YUV420"}
            )
            self.camera.configure(config)
            self.camera.start()
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            self.camera = None

    def setup_light_sensor(self):
        try:
            light_sensor_address = int(self.settings["light_sensor_address"], 16)
            self.light_sensor = smbus.SMBus(1)
            self.light_sensor.read_byte(light_sensor_address)
            logging.info("Light sensor initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing light sensor: {e}")
            self.light_sensor = None

    def setup_gpio(self):
        try:
            self.gpio_pin = int(self.settings["gpio_pin"])
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info(f"GPIO pin {self.gpio_pin} initialized as input with pull-down.")
        except Exception as e:
            logging.error(f"Error initializing GPIO pin: {e}")
            self.gpio_pin = None

    def setup_signal_handlers(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received. Shutting down...")
        self.running = False

    def capture_frame(self):
        if not self.camera:
            return None
        try:
            frame = self.camera.capture_array("lores")
            return frame
        except Exception as e:
            logging.error(f"Error capturing frame: {e}")
            return None

    def detect_motion(self, frame1, frame2):
        if frame1 is None or frame2 is None:
            return False
        try:
            y1 = frame1[:320*240].reshape(240, 320)
            y2 = frame2[:320*240].reshape(240, 320)
            diff = np.abs(y1.astype(np.int16) - y2.astype(np.int16))
            avg_diff = np.mean(diff)
            changed_pixels = np.sum(diff > self.settings["motion_threshold"])
            total_pixels = 320 * 240
            changed_percentage = changed_pixels / total_pixels
            if avg_diff > self.settings["motion_threshold"] and changed_percentage > self.settings["motion_sensitivity"]:
                return True
            return False
        except Exception as e:
            logging.error(f"Error detecting motion: {e}")
            return False

    def record_video(self, filename):
        if not self.camera:
            logging.error("Camera not available. Cannot record video.")
            return
        try:
            output = picamera2.PiCamera2EncoderOutput(filename)
            self.camera.start_recording(output, format='h264')
            logging.info(f"Started recording to {filename}")
            time.sleep(self.settings["recording_duration"])
            self.camera.stop_recording()
            logging.info(f"Stopped recording to {filename}")
            self.delete_oldest_files()
        except Exception as e:
            logging.error(f"Error recording video: {e}")

    def delete_oldest_files(self):
        try:
            footage_dir = "/home/pi/security_footage"
            if not os.path.exists(footage_dir):
                return
            files = [f for f in os.listdir(footage_dir) if f.endswith(".h264")]
            if not files:
                return
            files.sort(key=lambda x: os.path.getmtime(os.path.join(footage_dir, x)))
            total_size = sum(os.path.getsize(os.path.join(footage_dir, f)) for f in files)
            total_size_mb = total_size / (1024 * 1024)
            while total_size_mb > self.settings["disk_space_limit"] and files:
                file_to_delete = files.pop(0)
                file_path = os.path.join(footage_dir, file_to_delete)
                file_size_mb = os.path.getsize(file_path) / (1024 * 1024)
                try:
                    os.remove(file_path)
                    total_size_mb -= file_size_mb
                    logging.info(f"Deleted oldest file: {file_to_delete}")
                except Exception as e:
                    logging.error(f"Error deleting file {file_to_delete}: {e}")
        except Exception as e:
            logging.error(f"Error managing disk space: {e}")

    def read_light_sensor(self):
        if not self.light_sensor:
            return None
        try:
            light_sensor_address = int(self.settings["light_sensor_address"], 16)
            data = self.light_sensor.read_i2c_block_data(light_sensor_address, 0x10, 2)
            light_level = (data[1] + (256 * data[0])) / 1.2
            return light_level
        except Exception as e:
            logging.error(f"Error reading light sensor: {e}")
            return None

    def log_light_sensor_data(self):
        while self.running:
            light_level = self.read_light_sensor()
            if light_level is not None:
                timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                with self.lock:
                    self.light_sensor_data.append((timestamp, light_level))
                logging.info(f"Light sensor reading: {light_level} lux")
            time.sleep(self.settings["light_sensor_interval"])

    def run(self):
        if not self.camera:
            logging.error("Camera not available. Exiting.")
            return
        if self.light_sensor:
            self.light_sensor_thread = threading.Thread(target=self.log_light_sensor_data, daemon=True)
            self.light_sensor_thread.start()
        try:
            while self.running:
                frame = self.capture_frame()
                if frame is not None:
                    if self.frame_queue.full():
                        try:
                            self.frame_queue.get_nowait()
                        except queue.Empty:
                            pass
                    self.frame_queue.put(frame)
                    if len(self.circular_buffer) > 72:
                        self.circular_buffer.pop(0)
                    self.circular_buffer.append(frame)
                    if self.frame_queue.qsize() > 1:
                        try:
                            frame1 = self.frame_queue.get_nowait()
                            frame2 = self.frame_queue.get_nowait()
                            self.frame_queue.task_done()
                            self.frame_queue.task_done()
                            if self.detect_motion(frame1, frame2):
                                current_time = time.time()
                                if not self.motion_detected:
                                    self.motion_detected = True
                                    self.last_motion_time = current_time
                                    logging.info("Motion detected!")
                                    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                                    filename = f"/home/pi/security_footage/camera1_{timestamp}.h264"
                                    threading.Thread(target=self.record_video, args=(filename,), daemon=True).start()
                                elif current_time - self.last_motion_time > self.settings["debounce_time"]:
                                    self.motion_detected = True
                                    self.last_motion_time = current_time
                                    logging.info("Motion detected (debounced)!")
                                    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                                    filename = f"/home/pi/security_footage/camera1_{timestamp}.h264"
                                    threading.Thread(target=self.record_video, args=(filename,), daemon=True).start()
                            else:
                                if self.motion_detected and (current_time - self.last_motion_time > self.settings["recording_duration"]):
                                    self.motion_detected = False
                                    logging.info("Motion stopped.")
                        except queue.Empty:
                            pass
                time.sleep(0.041666666666666664)
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
        finally:
            if self.camera:
                self.camera.stop()
                self.camera.close()
            if self.light_sensor:
                self.light_sensor.close()
            if self.gpio_pin is not None:
                GPIO.cleanup()
            logging.info("Security system stopped.")

if __name__ == "__main__":
    system = SecuritySystem()
    system.run()

