import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library is not installed. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)

# BCM pin definitions
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        for pin in INPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        for pin in OUTPUT_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

        output_23_state = False
        output_24_state = False

        while _running:
            try:
                if GPIO.input(4) == GPIO.LOW:
                    GPIO.output(23, GPIO.HIGH)
                    output_23_state = True
                elif GPIO.input(5) == GPIO.LOW:
                    GPIO.output(23, GPIO.LOW)
                    output_23_state = False

                if GPIO.input(6) == GPIO.LOW:
                    output_24_state = not output_24_state
                    GPIO.output(24, GPIO.HIGH if output_24_state else GPIO.LOW)

                time.sleep(0.05)
            except Exception as e:
                print(f"GPIO read/write error: {e}", file=sys.stderr)
                break
    except Exception as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    _cleanup()

if __name__ == "__main__":
    main()

