import cv2
import pyzbar.pyzbar as pyzbar
import time
import logging
import configparser
import threading
import queue
import os
import signal
import sys
import random

# Configuration
CONFIG_FILE = 'config.ini'
LOG_FILE = 'inventory.log'
BACKUP_LOG_FILE = 'backup_inventory.log'
DEFAULT_REINIT_DELAY = 5.0
DEFAULT_CLOUD_UPLOAD_INTERVAL = 60
DEFAULT_FRAME_BUFFER_SIZE = 10
DEFAULT_MOTION_THRESHOLD = 25
DEFAULT_REDUNDANCY_TIME_WINDOW = 60.0

# Global variables
inventory_data = {}
inventory_lock = threading.Lock()
frame_queues = {}
frame_buffers = {}
last_scan_times = {}
running = True
watchdog_timer = None
watchdog_timeout = 30

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def signal_handler(sig, frame):
    global running
    logging.info("Signal received, shutting down gracefully...")
    running = False

def load_config():
    config = configparser.ConfigParser()
    try:
        config.read(CONFIG_FILE)
        if not config.has_section('DEFAULT'):
            config['DEFAULT'] = {}
        reinit_delay = config.getfloat('DEFAULT', 'reinit_delay', fallback=DEFAULT_REINIT_DELAY)
        cloud_upload_interval = config.getint('DEFAULT', 'cloud_upload_interval', fallback=DEFAULT_CLOUD_UPLOAD_INTERVAL)
        frame_buffer_size = config.getint('DEFAULT', 'frame_buffer_size', fallback=DEFAULT_FRAME_BUFFER_SIZE)
        motion_threshold = config.getint('DEFAULT', 'motion_threshold', fallback=DEFAULT_MOTION_THRESHOLD)
        redundancy_time_window = config.getfloat('DEFAULT', 'redundancy_time_window', fallback=DEFAULT_REDUNDANCY_TIME_WINDOW)
        return reinit_delay, cloud_upload_interval, frame_buffer_size, motion_threshold, redundancy_time_window
    except (configparser.Error, ValueError) as e:
        logging.error(f"Error loading configuration: {e}. Using default values.")
        return DEFAULT_REINIT_DELAY, DEFAULT_CLOUD_UPLOAD_INTERVAL, DEFAULT_FRAME_BUFFER_SIZE, DEFAULT_MOTION_THRESHOLD, DEFAULT_REDUNDANCY_TIME_WINDOW

def initialize_camera(device_id):
    try:
        cap = cv2.VideoCapture(device_id)
        if not cap.isOpened():
            raise IOError(f"Cannot open USB camera at device {device_id}")
        logging.info(f"Camera {device_id} initialized successfully.")
        return cap
    except Exception as e:
        logging.error(f"Error initializing camera {device_id}: {e}")
        return None

def detect_motion(frame1, frame2, threshold):
    try:
        diff = cv2.absdiff(frame1, frame2)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        blur = cv2.GaussianBlur(gray, (5, 5), 0)
        _, thresh = cv2.threshold(blur, threshold, 255, cv2.THRESH_BINARY)
        dilated = cv2.dilate(thresh, None, iterations=3)
        contours, _ = cv2.findContours(dilated, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)
        return len(contours) > 0
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return False

def decode_qr_code(frame):
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = pyzbar.decode(gray)
        if decoded_objects:
            return decoded_objects[0].data.decode('utf-8')
        return None
    except Exception as e:
        logging.error(f"Error decoding QR code: {e}")
        return None

def update_inventory(qr_code_data):
    global inventory_data
    with inventory_lock:
        if qr_code_data in inventory_data:
            inventory_data[qr_code_data] += 1
        else:
            inventory_data[qr_code_data] = 1
        logging.info(f"Inventory updated: {qr_code_data} - Quantity: {inventory_data[qr_code_data]}")

def log_inventory_data():
    try:
        with inventory_lock:
            inventory_copy = inventory_data.copy()
        with open(LOG_FILE, 'a') as f:
            for item, quantity in inventory_copy.items():
                f.write(f"{item},{quantity}\n")
        logging.info("Inventory data logged to file.")
    except Exception as e:
        logging.error(f"Error logging inventory data: {e}")

def simulate_cloud_upload():
    global inventory_data
    with inventory_lock:
        inventory_copy = inventory_data.copy()
        inventory_data.clear()
    logging.info(f"Simulating cloud upload: {inventory_copy}")

def camera_thread(device_id, reinit_delay, frame_buffer_size, motion_threshold, redundancy_time_window):
    global running, frame_queues, frame_buffers, last_scan_times
    cap = None
    frame_queue = queue.Queue(maxsize=frame_buffer_size)
    frame_queues[device_id] = frame_queue
    frame_buffers[device_id] = []
    last_scan_times[device_id] = 0.0

    while running:
        if cap is None:
            cap = initialize_camera(device_id)
            if cap is None:
                logging.error(f"Failed to initialize camera {device_id}. Retrying in {reinit_delay} seconds.")
                time.sleep(reinit_delay)
                continue

        ret, frame = cap.read()
        if not ret:
            logging.error(f"Failed to read frame from camera {device_id}. Reinitializing.")
            cap.release()
            cap = None
            time.sleep(reinit_delay)
            continue

        if frame_queue.full():
            try:
                frame_queue.get_nowait()
            except queue.Empty:
                pass

        frame_queue.put(frame)

        if len(frame_buffers[device_id]) < frame_buffer_size:
            frame_buffers[device_id].append(frame)
        else:
            frame_buffers[device_id].pop(0)
            frame_buffers[device_id].append(frame)

        if len(frame_buffers[device_id]) > 1:
            if detect_motion(frame_buffers[device_id][-2], frame_buffers[device_id][-1], motion_threshold):
                qr_code_data = decode_qr_code(frame)
                if qr_code_data:
                    current_time = time.time()
                    if current_time - last_scan_times[device_id] > redundancy_time_window:
                        update_inventory(qr_code_data)
                        last_scan_times[device_id] = current_time
                    else:
                        logging.warning(f"Redundant scan detected for {qr_code_data}. Ignoring.")
                else:
                    logging.debug("No QR code detected in the frame.")
            else:
                logging.debug("No motion detected in the frame.")

        time.sleep(0.1)

    if cap is not None:
        cap.release()
    logging.info(f"Camera thread {device_id} stopped.")

def cloud_upload_thread(cloud_upload_interval):
    global running
    while running:
        simulate_cloud_upload()
        time.sleep(cloud_upload_interval)

def watchdog():
    global watchdog_timer, running
    if watchdog_timer is not None:
        watchdog_timer.cancel()
    if not running:
        return
    watchdog_timer = threading.Timer(watchdog_timeout, restart_program)
    watchdog_timer.start()

def restart_program():
    logging.critical("Watchdog timeout! Restarting program...")
    os.execv(sys.executable, [sys.executable] + sys.argv)

def main():
    global running, watchdog_timer
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    reinit_delay, cloud_upload_interval, frame_buffer_size, motion_threshold, redundancy_time_window = load_config()

    camera_threads = []
    for device_id in [0, 2]:
        thread = threading.Thread(target=camera_thread, args=(device_id, reinit_delay, frame_buffer_size, motion_threshold, redundancy_time_window))
        thread.daemon = True
        camera_threads.append(thread)
        thread.start()

    cloud_thread = threading.Thread(target=cloud_upload_thread, args=(cloud_upload_interval,))
    cloud_thread.daemon = True
    cloud_thread.start()

    watchdog()

    try:
        while running:
            time.sleep(1)
            watchdog()
    except KeyboardInterrupt:
        logging.info("Keyboard interrupt received. Shutting down...")
    finally:
        running = False
        if watchdog_timer is not None:
            watchdog_timer.cancel()
        for thread in camera_threads:
            thread.join(timeout=2)
        cloud_thread.join(timeout=2)
        log_inventory_data()
        logging.info("Program stopped.")

if __name__ == "__main__":
    main()

