import datetime
import threading
import os
import sys
import numpy as np
from PIL import Image
import picamera2
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logger.info("Shutdown signal received.")

def load_config(config_file="config.txt"):
    defaults = {
        "snapshot_dir": "/home/pi/snapshots",
        "roi_x1": 0, "roi_y1": 0, "roi_x2": 640, "roi_y2": 480,
        "motion_threshold": 10, "temperature_threshold": 70.0,
        "confirmation_delay": 5, "simulated_temperature": True
    }
    try:
        with open(config_file, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    logger.warning(f"Skipping malformed line: {line}")
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                if key in defaults:
                    try:
                        if isinstance(defaults[key], bool):
                            defaults[key] = value.lower() in ("true", "1", "yes")
                        elif isinstance(defaults[key], int):
                            defaults[key] = int(value)
                        elif isinstance(defaults[key], float):
                            defaults[key] = float(value)
                        else:
                            defaults[key] = value
                    except ValueError:
                        logger.error(f"Invalid value for {key}: {value}")
    except FileNotFoundError:
        logger.warning(f"Config file not found: {config_file}. Using defaults.")
    except Exception as e:
        logger.error(f"Error reading config file: {e}. Using defaults.")
    return defaults

def capture_frame(camera):
    try:
        frame = camera.capture_array("main")
        return frame
    except Exception as e:
        logger.error(f"Error capturing frame: {e}")
        return None

def detect_motion(frame1, frame2, roi, threshold):
    try:
        x1, y1, x2, y2 = roi
        roi1 = frame1[y1:y2, x1:x2]
        roi2 = frame2[y1:y2, x1:x2]
        diff = np.abs(roi1.astype(np.int16) - roi2.astype(np.int16))
        avg_diff = np.mean(diff)
        motion_pixels = np.sum(diff > threshold)
        total_pixels = roi1.shape[0] * roi1.shape[1]
        motion_percentage = (motion_pixels / total_pixels) * 100 if total_pixels > 0 else 0
        return avg_diff, motion_percentage
    except Exception as e:
        logger.error(f"Error detecting motion: {e}")
        return 0, 0

def save_snapshot(camera, snapshot_dir, timestamp):
    try:
        frame = capture_frame(camera)
        if frame is None:
            logger.error("Failed to capture frame for snapshot.")
            return
        image = Image.fromarray(frame)
        filename = os.path.join(snapshot_dir, f"snapshot_{timestamp}.jpg")
        image.save(filename)
        logger.info(f"Snapshot saved: {filename}")
    except Exception as e:
        logger.error(f"Error saving snapshot: {e}")

def get_cpu_temperature():
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            temp = float(f.read().strip()) / 1000.0
        return temp
    except Exception as e:
        logger.error(f"Error reading CPU temperature: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    config = load_config()
    snapshot_dir = config["snapshot_dir"]
    roi = (config["roi_x1"], config["roi_y1"], config["roi_x2"], config["roi_y2"])
    motion_threshold = config["motion_threshold"]
    temperature_threshold = config["temperature_threshold"]
    confirmation_delay = config["confirmation_delay"]
    simulated_temperature = config["simulated_temperature"]
    try:
        os.makedirs(snapshot_dir, exist_ok=True)
    except Exception as e:
        logger.error(f"Error creating snapshot directory: {e}")
        return
    camera = None
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": "RGB888", "size": (640, 480)}))
        camera.start()
        logger.info("Camera initialized successfully.")
    except Exception as e:
        logger.error(f"Error initializing camera: {e}")
        return
    last_frame = None
    motion_detected = False
    try:
        while running:
            frame = capture_frame(camera)
            if frame is None:
                time.sleep(0.1)
                continue
            if last_frame is not None:
                avg_diff, motion_percentage = detect_motion(last_frame, frame, roi, motion_threshold)
                if motion_percentage > 1.0:
                    if not motion_detected:
                        logger.info(f"Motion detected! Avg Diff: {avg_diff:.2f}, Percentage: {motion_percentage:.2f}%")
                        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                        save_snapshot(camera, snapshot_dir, timestamp)
                        motion_detected = True
                        time.sleep(confirmation_delay)
                else:
                    motion_detected = False
            last_frame = frame
            if simulated_temperature:
                temperature = np.random.uniform(60, 80)
            else:
                temperature = get_cpu_temperature()
            if temperature is not None and temperature > temperature_threshold:
                logger.warning(f"Temperature alert! CPU Temperature: {temperature:.2f}°C")
            time.sleep(0.1)
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        if camera is not None:
            try:
                camera.stop()
                logger.info("Camera stopped.")
            except Exception as e:
                logger.error(f"Error stopping camera: {e}")
        logger.info("Exiting program.")

if __name__ == "__main__":
    main()

