import sys
import select
import time
import signal
import cv2
import RPi.GPIO as GPIO
import pygame.mixer as mix

import config
import face

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_camera = None
_lock = None
_button = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global _running
    _running = False


def _cleanup():
    """Release every hardware resource exactly once."""
    global _camera, _lock, _button
    if _camera is not None:
        try:
            _camera.release()
        except Exception:
            pass
        _camera = None
    if _lock is not None:
        try:
            _lock.close()
        except Exception:
            pass
        _lock = None
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
        _button = None
    try:
        mix.quit()
    except Exception:
        pass


def _init_audio():
    """Initialise the Pygame mixer with the required audio parameters."""
    try:
        mix.init(frequency=config.SOUND_FREQUENCY, size=-16,
                 channels=1, buffer=1024)
    except Exception as exc:
        print(f"Error initialising audio: {exc}", file=sys.stderr)
        sys.exit(1)


def _load_model():
    """Load the face-recognition model, exiting if the file is missing."""
    if not hasattr(config, "TRAINING_FILE") or not config.TRAINING_FILE:
        print("Error: config.TRAINING_FILE is not set.", file=sys.stderr)
        sys.exit(1)
    if not hasattr(config, "POSITIVE_LABEL") or not config.POSITIVE_LABEL:
        print("Error: config.POSITIVE_LABEL is not set.", file=sys.stderr)
        sys.exit(1)
    if not hasattr(config, "POSITIVE_THRESHOLD"):
        print("Error: config.POSITIVE_THRESHOLD is not set.", file=sys.stderr)
        sys.exit(1)
    try:
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
        print("Loaded training data from", config.TRAINING_FILE)
        return model
    except Exception as exc:
        print(f"Error loading training data: {exc}", file=sys.stderr)
        sys.exit(1)


def _capture_gray_frame(camera):
    """Capture a frame and return it as grayscale, or None on failure."""
    try:
        frame = camera.read()[1]
    except Exception as exc:
        print(f"Error reading from camera: {exc}", file=sys.stderr)
        return None
    if frame is None or frame.size == 0:
        print("Error: empty frame from camera.", file=sys.stderr)
        return None
    try:
        return cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
    except Exception as exc:
        print(f"Error converting frame to grayscale: {exc}", file=sys.stderr)
        return None


def _detect_single_face(gray):
    """Detect a single face; return (x, y, w, h) or None."""
    try:
        faces = face.detect_single(gray)
    except Exception as exc:
        print(f"Error detecting faces: {exc}", file=sys.stderr)
        return None
    if faces is None or len(faces) == 0:
        return None
    return faces[0]


def _play_sound(channel):
    """Play the sound assigned to *channel* (0, 1, or 2)."""
    try:
        config.SOUNDS[channel].play()
    except Exception as exc:
        print(f"Error playing sound on channel {channel}: {exc}",
              file=sys.stderr)


def _process_face(model, gray, face_rect):
    """Run recognition on the detected face; return (match, confidence)."""
    x, y, w, h = face_rect
    try:
        cropped = face.crop(gray, x, y, w, h)
        resized = face.resize(cropped)
    except Exception as exc:
        print(f"Error cropping/resizing face: {exc}", file=sys.stderr)
        return False, None
    try:
        label, confidence = model.predict(resized)
    except Exception as exc:
        print(f"Error during recognition: {exc}", file=sys.stderr)
        return False, None
    return (label == config.POSITIVE_LABEL and
            confidence < config.POSITIVE_THRESHOLD), confidence


def _unlock_door(lock):
    """Unlock the door and play the welcome sound."""
    try:
        lock.output(True)
        print("Door unlocked.")
        _play_sound(0)
    except Exception as exc:
        print(f"Error unlocking door: {exc}", file=sys.stderr)


def _lock_door(lock):
    """Lock the door and play the denied sound, then the wait sound."""
    try:
        lock.output(False)
        print("Door locked.")
        _play_sound(2)
        _play_sound(1)
    except Exception as exc:
        print(f"Error locking door: {exc}", file=sys.stderr)


def main():
    global _running, _camera, _lock, _button

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- Audio ----------------------------------------------------------
    _init_audio()

    # --- Model ----------------------------------------------------------
    model = _load_model()

    # --- Camera ---------------------------------------------------------
    try:
        _camera = config.get_camera()
    except Exception as exc:
        print(f"Error initialising camera: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- GPIO: lock (BCM 17) + button (BCM 5, pull-up) ------------------
    try:
        _lock = gpiozero.OutputDevice(17, active_high=True, initial_value=False)
        _button = gpiozero.Button(5, pull_up=True, bounce_time=0.05)
    except Exception as exc:
        print(f"Error initialising GPIO: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("Running Door Controller...")
    print("Press button to trigger face recognition.")
    print("Enter 'l' + Enter to lock the door.")
    print("Press Ctrl-C to quit.")

    try:
        while _running:
            # --- Button polling -----------------------------------------
            try:
                if _button.is_pressed:
                    print("Button pressed, looking for face...")
                    gray = _capture_gray_frame(_camera)
                    if gray is None:
                        time.sleep(0.1)
                        continue
                    face_rect = _detect_single_face(gray)
                    if face_rect is None:
                        print("No face detected.")
                        time.sleep(0.1)
                        continue
                    match, confidence = _process_face(model, gray, face_rect)
                    if match and confidence is not None:
                        print("Recognized face! Unlocking Door...")
                        _unlock_door(_lock)
                    else:
                        print("Face not recognized.")
                        _lock_door(_lock)
            except Exception as exc:
                print(f"Error during button handling: {exc}", file=sys.stderr)

            # --- Manual 'l' lock ----------------------------------------
            try:
                rlist, _, _ = select.select([sys.stdin], [], [], 0.1)
                if rlist:
                    line = sys.stdin.readline().strip().lower()
                    if line == "l":
                        print("Manual lock requested.")
                        _lock_door(_lock)
            except Exception as exc:
                print(f"Error reading stdin: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("Door controller stopped.")


if __name__ == "__main__":
    main()

