import cv2
import os
import time
import signal
import sys

# Constants
IMAGE_DIR = "images"
MAX_PICTURES = 5
CAMERA_INDEX = 0
MAX_RETRIES = 3
RETRY_DELAY = 1.0

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def create_directory(dir_name):
    """Creates a directory if it doesn't exist."""
    try:
        os.makedirs(dir_name, exist_ok=True)
        return True
    except OSError as e:
        print(f"Error creating directory '{dir_name}': {e}")
        return False

def get_existing_pictures_count(directory, person_name):
    """Counts existing pictures for a person."""
    try:
        count = 0
        for filename in os.listdir(directory):
            if filename.startswith(person_name) and filename.lower().endswith(('.jpg', '.png')):
                try:
                    int(filename[len(person_name):].split('.')[0])
                    count += 1
                except ValueError:
                    pass
        return count
    except FileNotFoundError:
        return 0
    except OSError as e:
        print(f"Error counting existing pictures: {e}")
        return 0

def take_pictures(camera, person_name, num_pictures):
    """Captures and saves pictures for a person."""
    picture_count = get_existing_pictures_count(IMAGE_DIR, person_name)
    target_count = num_pictures + picture_count
    print(f"Taking pictures for {person_name}. Need {num_pictures} more. Press 'y' to capture, 'q' to quit.")

    while picture_count < target_count and _running:
        ret, frame = camera.read()
        if not ret:
            print("Failed to grab frame from camera.")
            break

        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))

        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)

        cv2.imshow('Camera Feed', frame)
        key = cv2.waitKey(1) & 0xFF

        if key == ord('y') and len(faces) > 0:
            for (x, y, w, h) in faces:
                face_image = frame[y:y + h, x:x + w]
                filename = os.path.join(IMAGE_DIR, f"{person_name}{picture_count + 1}.jpg")
                if cv2.imwrite(filename, face_image):
                    print(f"Saved picture {picture_count + 1}")
                    picture_count += 1
                else:
                    print(f"Error: Failed to save image to {filename}")
            cv2.destroyWindow('Face')

        elif key == ord('q'):
            print("Exiting...")
            break

def main():
    """Main function to run the face capture program."""
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not create_directory(IMAGE_DIR):
        return

    camera = None
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            camera = cv2.VideoCapture(CAMERA_INDEX)
            if camera.isOpened():
                print(f"Camera initialized successfully (attempt {attempt}).")
                break
            camera.release()
            camera = None
        except Exception as e:
            print(f"Error initializing camera (attempt {attempt}): {e}")
        if attempt < MAX_RETRIES:
            print(f"Retrying in {RETRY_DELAY} seconds...")
            time.sleep(RETRY_DELAY)

    if camera is None:
        print("Failed to initialize camera after multiple attempts. Exiting.")
        return

    try:
        person_name = input("Enter person's name: ").strip()
        if not person_name:
            print("Name cannot be empty. Exiting.")
            return

        take_pictures(camera, person_name, MAX_PICTURES)

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        if camera is not None:
            camera.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    # Load the Haar cascade classifier for face detection
    cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
    face_cascade = cv2.CascadeClassifier(cascade_path)
    if face_cascade.empty():
        print(f"Error: Could not load Haar cascade from {cascade_path}")
        sys.exit(1)

    main()

