import argparse
import json
import logging
import signal
import sys
import time
from pathlib import Path

import cv2
import face_recognition
import numpy as np

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    OutputDevice = None
    GPIOZeroError = Exception

DEFAULT_CONFIDENCE_THRESHOLD = 0.6
DEFAULT_MOTION_THRESHOLD = 500
DEFAULT_DEBOUNCE_INTERVAL = 2.0
DEFAULT_DOOR_OPEN_DURATION = 5.0
DEFAULT_LOG_LEVEL = "INFO"
DEFAULT_ENCODINGS_FILE = "encodings.json"
DEFAULT_RELAY_PIN = 17
DEFAULT_PIXEL_DIFF_THRESHOLD = 10
FRAME_RATE = 10
FRAME_INTERVAL = 1.0 / FRAME_RATE


class DoorController:
    def __init__(self, args):
        self.args = args
        self.logger = logging.getLogger(__name__)
        self.running = True
        self.last_trigger_time = 0.0
        self.relay = None
        self.cap = None
        self.encodings = {}
        self.previous_frame = None
        self._load_encodings()
        self._init_camera()
        self._init_relay()
        self._setup_signal_handlers()

    def _setup_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame):
        self.logger.info("Received signal %s, shutting down...", signum)
        self.running = False

    def _load_encodings(self):
        enc_path = Path(self.args.encodings_file)
        try:
            if enc_path.exists():
                with enc_path.open("r") as f:
                    self.encodings = json.load(f)
                self.logger.info("Loaded %d encodings from %s", len(self.encodings), enc_path)
            else:
                self.logger.warning("Encodings file %s not found; starting with empty set", enc_path)
        except (json.JSONDecodeError, OSError) as e:
            self.logger.error("Error loading encodings: %s", e)
            self.encodings = {}

    def _init_camera(self):
        try:
            self.cap = cv2.VideoCapture(0)
            if not self.cap.isOpened():
                raise RuntimeError("Could not open camera index 0")
            self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
            self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
            self.cap.set(cv2.CAP_PROP_FPS, FRAME_RATE)
            self.logger.info("Camera initialized at 640x480 @ %d fps", FRAME_RATE)
        except Exception as e:
            self.logger.error("Camera initialization failed: %s", e)
            self.cap = None

    def _init_relay(self):
        if OutputDevice is None:
            self.logger.warning("gpiozero not installed; relay control disabled")
            return
        try:
            self.relay = OutputDevice(self.args.relay_pin, active_high=True, initial_value=False)
            self.logger.info("Relay initialized on GPIO%d (active-high)", self.args.relay_pin)
        except GPIOZeroError as e:
            self.logger.error("Relay initialization failed: %s", e)
            self.relay = None

    def _capture_frame(self):
        if self.cap is None:
            return None
        ret, frame = self.cap.read()
        if not ret or frame is None:
            self.logger.warning("Frame capture failed or returned None")
            return None
        return frame

    def _detect_motion(self, frame):
        if self.previous_frame is None:
            self.previous_frame = frame
            return False
        diff = cv2.absdiff(self.previous_frame, frame)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray, self.args.pixel_diff_threshold, 255, cv2.THRESH_BINARY)
        motion_pixels = int(np.count_nonzero(thresh > 0))
        self.previous_frame = frame
        return motion_pixels > self.args.motion_threshold

    def _recognize_face(self, frame):
        rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        face_locations = face_recognition.face_locations(rgb_frame)
        if not face_locations:
            return None, None
        face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)
        if not face_encodings:
            return None, None
        face_encoding = face_encodings[0]
        best_name = None
        best_distance = None
        for name, known_encs in self.encodings.items():
            for known_enc in known_encs:
                dist = face_recognition.face_distance([known_enc], face_encoding)[0]
                if best_distance is None or dist < best_distance:
                    best_distance = dist
                    best_name = name
        if best_name and best_distance <= self.args.confidence_threshold:
            return best_name, best_distance
        return None, None

    def _open_door(self):
        if self.relay is None:
            self.logger.warning("Relay not available; skipping door open")
            return
        try:
            self.relay.on()
            self.logger.info("Relay ON - door opening for %.1f s", self.args.door_open_duration)
            time.sleep(self.args.door_open_duration)
            self.relay.off()
            self.logger.info("Relay OFF - door closed")
        except GPIOZeroError as e:
            self.logger.error("Relay control error: %s", e)
            try:
                self.relay.off()
            except Exception:
                pass

    def run(self):
        if self.cap is None:
            self.logger.error("Cannot start: camera not initialized")
            return
        self.logger.info("Entering main loop (frame rate: %d fps)", FRAME_RATE)
        while self.running:
            loop_start = time.monotonic()
            frame = self._capture_frame()
            if frame is None:
                time.sleep(max(0.01, FRAME_INTERVAL))
                continue
            if self._detect_motion(frame):
                now = time.monotonic()
                if now - self.last_trigger_time >= self.args.debounce_interval:
                    self.last_trigger_time = now
                    name, dist = self._recognize_face(frame)
                    if name:
                        self.logger.info("Face recognized: %s (dist=%.4f)", name, dist)
                        self._open_door()
                    else:
                        self.logger.info("Motion detected but face not recognized")
                else:
                    self.logger.info("Debounce active, skipping trigger")
            elapsed = time.monotonic() - loop_start
            remaining = FRAME_INTERVAL - elapsed
            if remaining > 0:
                time.sleep(remaining)
        self._cleanup()

    def _cleanup(self):
        self.logger.info("Cleaning up resources...")
        if self.cap is not None:
            self.cap.release()
            self.cap = None
        if self.relay is not None:
            try:
                self.relay.off()
                self.relay.close()
            except Exception:
                pass
            self.relay = None
        cv2.destroyAllWindows()
        self.logger.info("Cleanup complete")


def parse_args():
    p = argparse.ArgumentParser(description="Raspberry Pi door controller with face recognition")
    p.add_argument("--confidence-threshold", type=float, default=DEFAULT_CONFIDENCE_THRESHOLD)
    p.add_argument("--motion-threshold", type=int, default=DEFAULT_MOTION_THRESHOLD)
    p.add_argument("--debounce-interval", type=float, default=DEFAULT_DEBOUNCE_INTERVAL)
    p.add_argument("--door-open-duration", type=float, default=DEFAULT_DOOR_OPEN_DURATION)
    p.add_argument("--log-level", type=str, default=DEFAULT_LOG_LEVEL, choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"])
    p.add_argument("--encodings-file", type=str, default=DEFAULT_ENCODINGS_FILE)
    p.add_argument("--relay-pin", type=int, default=DEFAULT_RELAY_PIN)
    p.add_argument("--pixel-diff-threshold", type=int, default=DEFAULT_PIXEL_DIFF_THRESHOLD)
    return p.parse_args()


def main():
    args = parse_args()
    logging.basicConfig(level=args.log_level, format="%(asctime)s - %(levelname)s - %(message)s")
    try:
        controller = DoorController(args)
        controller.run()
    except Exception as e:
        logging.getLogger(__name__).exception("Fatal error: %s", e)
        sys.exit(1)


if __name__ == "__main__":
    main()

