import threading
import time
import logging
import asyncio
import numpy as np
import cv2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

try:
    from general import WebSocketHandler
except ImportError:
    logging.error("WebSocketHandler not found. Please ensure 'general.py' is in the same directory.")
    raise

try:
    from camera import Camera
except ImportError:
    logging.error("Camera not found. Please ensure 'camera.py' is in the same directory.")
    raise

FRAME_RATE = 30
RESOLUTION = (640, 480)
MOTION_DETECT_RESOLUTION = (320, 240)


class CameraServer:
    def __init__(self, frame_rate=FRAME_RATE, resolution=RESOLUTION, motion_resolution=MOTION_DETECT_RESOLUTION):
        self.frame_rate = frame_rate
        self.resolution = resolution
        self.motion_resolution = motion_resolution
        self.camera = None
        self.prev_frame = None
        self.curr_frame = None
        self.frame_lock = threading.Lock()
        self.loop = None
        self.websocket_handler = None
        self.running = False
        self._lock = threading.Lock()

    def initialize(self):
        try:
            self.camera = Camera(framerate=self.frame_rate, resolution=self.resolution)
            if self.camera is None:
                raise RuntimeError("Camera initialization failed: camera object is None.")
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            raise

    def start(self):
        self.initialize()
        self.loop = asyncio.new_event_loop()
        asyncio.set_event_loop(self.loop)
        self.websocket_handler = WebSocketHandler()
        self.loop.run_until_complete(self.websocket_handler.start_server())
        self.running = True
        logging.info("Starting camera thread.")
        camera_thread = threading.Thread(target=self._camera_loop, daemon=True)
        camera_thread.start()
        try:
            self.loop.run_forever()
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received, shutting down.")
        finally:
            self.stop()

    def stop(self):
        logging.info("Stopping camera server.")
        self.running = False
        if self.camera:
            try:
                self.camera.stop()
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
        if self.loop and self.loop.is_running():
            self.loop.call_soon_threadsafe(self.loop.stop)
        if self.websocket_handler:
            try:
                self.loop.run_until_complete(self.websocket_handler.stop_server())
            except Exception as e:
                logging.error(f"Error stopping WebSocket server: {e}")

    def _camera_loop(self):
        try:
            while self.running:
                start_time = time.time()
                try:
                    frame = self.camera.get_frame()
                    if frame is None:
                        logging.warning("Received empty frame from camera.")
                        time.sleep(1.0 / self.frame_rate)
                        continue

                    with self._lock:
                        self._process_frame(frame)

                    elapsed_time = time.time() - start_time
                    sleep_time = max(0, (1.0 / self.frame_rate) - elapsed_time)
                    time.sleep(sleep_time)

                except Exception as e:
                    logging.error(f"Error in camera loop: {e}")
                    time.sleep(1)

        except Exception as e:
            logging.error(f"Fatal error in camera loop: {e}")
        finally:
            logging.info("Camera thread stopped.")

    def _process_frame(self, frame):
        try:
            if self.websocket_handler.has_connections():
                self._send_frame_to_clients(frame)
            self._detect_motion(frame)
        except Exception as e:
            logging.error(f"Error processing frame: {e}")

    def _send_frame_to_clients(self, frame):
        try:
            _, jpeg_frame = cv2.imencode('.jpg', frame)
            if not self.loop or not self.websocket_handler:
                return
            self.loop.call_soon_threadsafe(self.websocket_handler.broadcast, jpeg_frame.tobytes())
        except Exception as e:
            logging.error(f"Error sending frame to clients: {e}")

    def _detect_motion(self, frame):
        try:
            resized_frame = cv2.resize(frame, self.motion_resolution)
            gray_frame = cv2.cvtColor(resized_frame, cv2.COLOR_BGR2GRAY)
            gray_frame = cv2.GaussianBlur(gray_frame, (21, 21), 0)

            with self.frame_lock:
                if self.prev_frame is None:
                    self.prev_frame = gray_frame
                    return
                self.curr_frame = gray_frame

            frame_delta = cv2.absdiff(self.prev_frame, self.curr_frame)
            thresh = cv2.threshold(frame_delta, 25, 255, cv2.THRESH_BINARY)[1]
            thresh = cv2.dilate(thresh, None, iterations=2)
            contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

            for contour in contours:
                if cv2.contourArea(contour) < 500:
                    continue
                (x, y, w, h) = cv2.boundingRect(contour)
                cv2.rectangle(resized_frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
                logging.info("Motion detected!")

            self.prev_frame = self.curr_frame
        except Exception as e:
            logging.error(f"Error detecting motion: {e}")


def main():
    server = CameraServer()

    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        server.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    server.start()


if __name__ == "__main__":
    main()

