import os
import sys
import signal
import time
import traceback
from typing import Tuple, List, Optional

import numpy as np
import torch
import torchvision.transforms as T
from torchvision.models import resnet50, ResNet50_Weights
from PIL import Image

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)


MODEL_URL = "https://download.pytorch.org/models/resnet50-0c010c49.pth"
LABEL_URL = "https://raw.githubusercontent.com/pytorch/hub/master/imagenet_classes.txt"
IMAGE_DIR = "images"
MEAN = [0.485, 0.456, 0.406]
STD = [0.229, 0.224, 0.225]
TARGET_SIZE = 224
SHORT_SIZE = 256
TOP_K = 3

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def download_file(url: str, dest: str) -> str:
    import urllib.request
    import urllib.error
    if not os.path.exists(dest):
        print(f"Downloading {url} ...")
        try:
            urllib.request.urlretrieve(url, dest)
        except urllib.error.URLError as e:
            raise RuntimeError(f"Failed to download {url}: {e}")
        except Exception as e:
            raise RuntimeError(f"Unexpected error downloading {url}: {e}")
    return dest


def load_labels(path: str) -> List[str]:
    try:
        with open(path, "r") as f:
            return [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        raise RuntimeError(f"Label file not found: {path}")
    except OSError as e:
        raise RuntimeError(f"Error reading label file: {e}")


def preprocess_image(image: Image.Image) -> torch.Tensor:
    transform = T.Compose([
        T.Resize(SHORT_SIZE),
        T.CenterCrop(TARGET_SIZE),
        T.ToTensor(),
        T.Normalize(mean=MEAN, std=STD),
    ])
    return transform(image).unsqueeze(0)


def capture_image(cam: Picamera2) -> Optional[str]:
    timestamp = time.strftime("%Y%m%d_%H%M%S")
    image_path = os.path.join(IMAGE_DIR, f"{timestamp}.jpg")
    try:
        cam.capture_file(image_path)
        if not os.path.exists(image_path) or os.path.getsize(image_path) == 0:
            raise RuntimeError(f"Image file is empty or missing: {image_path}")
        return image_path
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        return None


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    os.makedirs(IMAGE_DIR, exist_ok=True)

    try:
        label_path = download_file(LABEL_URL, "imagenet_classes.txt")
        labels = load_labels(label_path)
    except RuntimeError as e:
        print(f"Error loading labels: {e}", file=sys.stderr)
        return 1

    try:
        model = resnet50(weights=ResNet50_Weights.DEFAULT)
        model.eval()
    except Exception as e:
        print(f"Error loading model: {e}", file=sys.stderr)
        return 1

    cam: Optional[Picamera2] = None
    try:
        cam = Picamera2(camera_num=0)
        cam.start()
        time.sleep(1)
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        if cam is not None:
            try:
                cam.close()
            except Exception:
                pass
        return 1

    image_path = None
    try:
        image_path = capture_image(cam)
        if image_path is None:
            return 1

        try:
            image = Image.open(image_path).convert("RGB")
        except Exception as e:
            print(f"Error opening captured image: {e}", file=sys.stderr)
            return 1

        try:
            input_tensor = preprocess_image(image)
        except Exception as e:
            print(f"Error preprocessing image: {e}", file=sys.stderr)
            return 1

        try:
            with torch.no_grad():
                output = model(input_tensor)
            probabilities = torch.nn.functional.softmax(output[0], dim=0)
            top_indices = torch.topk(probabilities, TOP_K).indices.tolist()
            print(f"\nTop {TOP_K} predictions for {image_path}:")
            for idx in top_indices:
                if 0 <= idx < len(labels):
                    print(f"  {labels[idx]:>75} ({probabilities[idx]:.4f})")
                else:
                    print(f"  (unknown index {idx}) ({probabilities[idx]:.4f})")
        except Exception as e:
            print(f"Error during inference: {e}", file=sys.stderr)
            return 1

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        traceback.print_exc()
        return 1
    finally:
        if cam is not None:
            try:
                cam.stop()
            except Exception:
                pass
            try:
                cam.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

