import io
import logging
import numpy as np

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffers an MJPEG stream and flushes frames to an output sink.

    Only frames whose H.264 frame type is not 1 (I-frames) are forwarded.
    """

    def __init__(self, c, f):
        self.c = c
        self.f = f
        self.b = io.BytesIO()

    def write(self, d):
        try:
            if d.startswith(b'\xff\xd8'):
                self.b.seek(0)
                self.b.truncate()
            self.b.write(d)
            if d.endswith(b'\xff\xd9'):
                e = self.b.getvalue()
                try:
                    n = self.c.encode(e, self.f)
                except Exception as exc:
                    logger.error('Error during encoding: %s', exc)
                try:
                    i = self.c.out1
                except Exception as exc:
                    logger.error('Error accessing out1: %s', exc)
                    i = None
                if i is not None and i[1] != 1:
                    try:
                        self.f(e)
                    except Exception as exc:
                        logger.error('Error during output flush: %s', exc)
        except Exception as exc:
            logger.error('Error in CameraStreamBuffer.write: %s', exc)


class MotionDetectionBuffer:
    """Parses an MJPEG stream, decodes JPEG frames, and calls a callback
    with consecutive frame pairs for motion-detection analysis."""

    def __init__(self, c, f):
        self.c = c
        self.f = f
        self.b = io.BytesIO()
        self.p = None

    def write(self, d):
        try:
            if d.startswith(b'\xff\xd8'):
                self.b.seek(0)
                self.b.truncate()
            self.b.write(d)
            if d.endswith(b'\xff\xd9'):
                raw = self.b.getvalue()
                try:
                    arr = np.frombuffer(raw, dtype=np.uint8)
                    img = self.c.imdecode(arr, flags=1)
                    if img is None:
                        logger.warning('imdecode returned None; skipping frame')
                        return
                    if self.p is not None:
                        self.f(self.p, img)
                    self.p = img
                except Exception as exc:
                    logger.error('Error during motion-detection processing: %s', exc)
        except Exception as exc:
            logger.error('Error in MotionDetectionBuffer.write: %s', exc)

