import os
import sys
import signal
import time
import logging
import threading

import cv2
import pygame.mixer as mix

import config
import face

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
log = logging.getLogger(__name__)

DOOR_PIN = 18
BUTTON_PIN = 17
SAMPLE_RATE = 48000
LOOP_DELAY = 0.1

shutdown_event = threading.Event()


def _signal_handler(signum, frame):
    log.info('Signal %s received – shutting down.', signum)
    shutdown_event.set()


def init_mixer():
    try:
        mix.init(frequency=SAMPLE_RATE, size=-16, channels=2, buffer=1024)
        log.info('Mixer initialised at %d Hz.', SAMPLE_RATE)
    except pygame.error as exc:
        log.error('Failed to initialise mixer: %s', exc)
        raise


def load_sound(path):
    if not os.path.isfile(path):
        log.warning('Sound file not found: %s', path)
        return None
    try:
        return mix.Sound(path)
    except pygame.error as exc:
        log.error('Failed to load %s: %s', path, exc)
        return None


def init_camera():
    cam = cv2.VideoCapture(0)
    if not cam.isOpened():
        log.error('Could not open camera index 0.')
        raise RuntimeError('Camera init failed')
    log.info('Camera initialised.')
    return cam


def init_recognizer():
    try:
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
        log.info('EigenFaceRecognizer loaded from %s', config.TRAINING_FILE)
        return model
    except cv2.error as exc:
        log.error('Failed to load training file %s: %s', config.TRAINING_FILE, exc)
        raise


def init_door():
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(DOOR_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        log.info('GPIO initialised: DOOR=%d (OUT), BUTTON=%d (IN, pull-up).',
                 DOOR_PIN, BUTTON_PIN)
        return GPIO
    except RuntimeError as exc:
        log.error('GPIO init failed: %s', exc)
        raise


def is_button_up(GPIO):
    return GPIO.input(BUTTON_PIN) == GPIO.HIGH


def unlock_door(GPIO):
    GPIO.output(DOOR_PIN, GPIO.HIGH)
    log.info('Door unlocked.')


def lock_door(GPIO):
    GPIO.output(DOOR_PIN, GPIO.LOW)
    log.info('Door locked.')


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        init_mixer()
    except Exception:
        sys.exit(1)

    welcome = load_sound(config.WELCOME_SOUND)
    wait = load_sound(config.WAIT_SOUND)
    later = load_sound(config.LATER_SOUND)

    try:
        cam = init_camera()
        recognizer = init_recognizer()
        GPIO = init_door()
    except Exception:
        mix.quit()
        sys.exit(1)

    try:
        lock_door(GPIO)
        log.info('Door locked. Waiting for button press...')

        while not shutdown_event.is_set():
            if is_button_up(GPIO):
                log.info('Button pressed – attempting face recognition.')

                ret, img = cam.read()
                if not ret or img is None:
                    log.warning('Camera read failed.')
                    if later:
                        later.play()
                    time.sleep(LOOP_DELAY)
                    continue

                gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
                face_coords = face.detect_single(gray)

                if face_coords is None:
                    log.info('No face detected.')
                    if later:
                        later.play()
                else:
                    x, y, w, h = face_coords
                    cropped = face.crop(gray, x, y, w, h)
                    resized = face.resize(cropped)
                    label, confidence = recognizer.predict(resized)
                    log.info('Predicted label=%s confidence=%.2f', label, confidence)

                    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                        log.info('Face recognised – unlocking door.')
                        unlock_door(GPIO)
                        if welcome:
                            welcome.play()
                    else:
                        log.info('Face not recognised.')
                        if wait:
                            wait.play()

            time.sleep(LOOP_DELAY)
    finally:
        try:
            lock_door(GPIO)
        except Exception:
            pass
        try:
            cam.release()
        except Exception:
            pass
        try:
            mix.quit()
        except Exception:
            pass
        try:
            import RPi.GPIO as GPIO
            GPIO.cleanup()
        except Exception:
            pass
        log.info('Shutdown complete.')


if __name__ == '__main__':
    main()

