import wave
import struct
import audioop
import board
import busio
import digitalio
import adafruit_lora
import adafruit_lora.radiocode
import speech_recognition as sr
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

SAMPLE_RATE = 44100
CHUNK_SIZE = 1024
IMAGE_PATH = '/home/raspberry/Desktop/IoT Project/captured_image.jpg'
LORA_FREQUENCY = 868.0
LORA_ADDRESS = 0
LORA_POWER = 22
LORA_AIR_SPEED = 2400

_running = True
_old_settings = None
_lora_node = None
_camera = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _restore_terminal():
    global _old_settings
    if _old_settings is not None:
        try:
            termios.tcsetattr(sys.stdin, termios.TCSADRAIN, _old_settings)
        except Exception:
            pass
        _old_settings = None


def _cleanup():
    global _lora_node, _camera
    _restore_terminal()
    if _camera is not None:
        try:
            _camera.stop()
        except Exception:
            pass
        _camera = None
    if _lora_node is not None:
        try:
            _lora_node.close()
        except Exception:
            pass
        _lora_node = None


def _init_lora():
    global _lora_node
    try:
        spi = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        cs = digitalio.DigitalInOut(board.D5)
        _lora_node = adafruit_lora.Lora(
            spi, cs, frequency=LORA_FREQUENCY, address=LORA_ADDRESS,
            power=LORA_POWER, air_speed=LORA_AIR_SPEED
        )
        logger.info('LoRa node initialized at %.1f MHz', LORA_FREQUENCY)
    except Exception as e:
        logger.error('Failed to initialize LoRa node: %s', e)
        _lora_node = None


def _send_lora_message(message):
    if _lora_node is None:
        logger.error('LoRa node not initialized; cannot send message')
        return False
    try:
        _lora_node.send_message(message)
        logger.info('LoRa message sent: %s', message)
        return True
    except Exception as e:
        logger.error('Failed to send LoRa message: %s', e)
        return False


def _adjust_for_ambient_noise(recognizer, source):
    logger.info('Adjusting for ambient noise...')
    recognizer.adjust_for_ambient_noise(source, duration=1)
    logger.info('Ambient noise adjustment complete.')


def _listen_for_command(recognizer, source):
    logger.info('Listening for command...')
    try:
        audio = recognizer.listen(source, timeout=5, phrase_time_limit=3)
        logger.info('Audio captured.')
        return audio
    except sr.WaitTimeoutError:
        logger.warning('Listening timed out; no speech detected.')
        return None
    except Exception as e:
        logger.error('Error during audio capture: %s', e)
        return None


def _recognize_command(recognizer, audio):
    try:
        text = recognizer.recognize_google(audio)
        logger.info('Recognized speech: %s', text)
        return text.lower()
    except sr.UnknownValueError:
        logger.warning('Speech was unintelligible.')
        return None
    except sr.RequestError as e:
        logger.error('Speech recognition service error: %s', e)
        return None
    except Exception as e:
        logger.error('Unexpected error during speech recognition: %s', e)
        return None


def _capture_image():
    global _camera
    try:
        if _camera is None:
            _camera = Picamera2()
            _camera.configure('still')
            _camera.start()
        os.makedirs(os.path.dirname(IMAGE_PATH), exist_ok=True)
        _camera.capture_file(IMAGE_PATH)
        logger.info('Image captured and saved to: %s', IMAGE_PATH)
        return True
    except Exception as e:
        logger.error('Failed to capture image: %s', e)
        return False


def _process_command(command):
    if command is None:
        return
    if 'capture' in command:
        if _capture_image():
            _send_lora_message('Image captured')


def main():
    global _old_settings
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        _old_settings = termios.tcgetattr(sys.stdin)
        tty.setcbreak(sys.stdin.fileno())
    except Exception:
        _old_settings = None
    _init_lora()
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone(sample_rate=SAMPLE_RATE, chunk_size=CHUNK_SIZE) as source:
            _adjust_for_ambient_noise(recognizer, source)
            while _running:
                audio = _listen_for_command(recognizer, source)
                if audio is not None:
                    command = _recognize_command(recognizer, audio)
                    _process_command(command)
                time.sleep(0.1)
    except Exception as e:
        logger.error('Fatal error in main loop: %s', e)
    finally:
        _cleanup()


if __name__ == '__main__':
    main()

