import signal
import sys
import time
import threading
import os

import psutil
import smbus2
from gpiozero import LED, OutputDevice

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
LCD_ADDR = 0x27
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0x04
LED_PINS = [17, 18, 23, 27, 22]
UPDATE_INTERVAL = 1.0
LED_ON_DURATION = 1.0

# --- Globals -----------------------------------------------------------------
running = True
i2c_lock = threading.Lock()
leds = []
lcd_backlight = None


class LCD:
    def __init__(self, bus_num, addr):
        self.addr = addr
        try:
            self.bus = smbus2.SMBus(bus_num)
        except Exception as exc:
            raise RuntimeError(f"Failed to open I2C bus {bus_num}: {exc}") from exc

    def _write_byte(self, data):
        with i2c_lock:
            self.bus.write_byte(self.addr, data)

    def _toggle_enable(self, bits):
        time.sleep(0.0005)
        self._write_byte(bits | ENABLE)
        time.sleep(0.0005)
        self._write_byte(bits & ~ENABLE)
        time.sleep(0.0005)

    def _send(self, bits, mode):
        bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT
        bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT
        self._write_byte(bits_high)
        self._toggle_enable(bits_high)
        self._write_byte(bits_low)
        self._toggle_enable(bits_low)

    def init(self):
        self._send(0x33, LCD_CMD)
        self._send(0x32, LCD_CMD)
        self._send(0x06, LCD_CMD)
        self._send(0x0C, LCD_CMD)
        self._send(0x28, LCD_CMD)
        self._send(0x01, LCD_CMD)
        time.sleep(0.002)

    def display_string(self, text, line):
        self._send(line, LCD_CMD)
        for ch in text.ljust(LCD_WIDTH)[:LCD_WIDTH]:
            self._send(ord(ch), LCD_CHR)

    def clear(self):
        self._send(0x01, LCD_CMD)
        time.sleep(0.002)

    def close(self):
        try:
            self.clear()
        except Exception:
            pass
        try:
            self._write_byte(0x00)
        except Exception:
            pass
        try:
            self.bus.close()
        except Exception:
            pass


def get_cpu_stats():
    try:
        cpu_usage = psutil.cpu_percent(interval=None)
    except Exception as exc:
        print(f"[WARN] CPU usage read failed: {exc}", file=sys.stderr)
        cpu_usage = 0.0
    try:
        temp_str = os.popen("vcgencmd measure_temp").readline()
        cpu_temp = float(temp_str.split("=")[1].split("'")[0])
    except Exception as exc:
        print(f"[WARN] CPU temp read failed: {exc}", file=sys.stderr)
        cpu_temp = 0.0
    return cpu_usage, cpu_temp


def update_lcd(lcd):
    while running:
        cpu_usage, cpu_temp = get_cpu_stats()
        try:
            lcd.display_string(f"CPU  : {cpu_usage:5.1f}%", LCD_LINE_1)
            lcd.display_string(f"Temp : {cpu_temp:5.1f}C", LCD_LINE_2)
        except Exception as exc:
            print(f"[WARN] LCD write failed: {exc}", file=sys.stderr)
        time.sleep(UPDATE_INTERVAL)


def activate_led(cls, duration=LED_ON_DURATION):
    if not 0 <= cls < len(leds):
        print(f"[WARN] Invalid LED class index: {cls}", file=sys.stderr)
        return
    try:
        leds[cls].on()
        time.sleep(duration)
        leds[cls].off()
    except Exception as exc:
        print(f"[WARN] LED {cls} control failed: {exc}", file=sys.stderr)


def cleanup(lcd):
    global running
    running = False
    for led in leds:
        try:
            led.off()
            led.close()
        except Exception:
            pass
    if lcd_backlight is not None:
        try:
            lcd_backlight.off()
            lcd_backlight.close()
        except Exception:
            pass
    try:
        lcd.close()
    except Exception:
        pass


def main():
    global running, lcd_backlight

    try:
        lcd = LCD(I2C_BUS, LCD_ADDR)
        lcd.init()
    except Exception as exc:
        print(f"[ERROR] LCD init failed: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for pin in LED_PINS:
            leds.append(LED(pin))
    except Exception as exc:
        print(f"[ERROR] GPIO init failed: {exc}", file=sys.stderr)
        cleanup(lcd)
        sys.exit(1)

    try:
        lcd_backlight = OutputDevice(25, active_high=True, initial_value=True)
    except Exception as exc:
        print(f"[WARN] Backlight init failed: {exc}", file=sys.stderr)
        lcd_backlight = None

    lcd_thread = threading.Thread(target=update_lcd, args=(lcd,), daemon=True)
    lcd_thread.start()

    try:
        while running:
            for cls in range(5):
                if not running:
                    break
                activate_led(cls)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup(lcd)


if __name__ == "__main__":
    main()

