import signal
import sys
import time
import logging

import spidev
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("mcp3008_oled")

SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 50000
I2C_PORT = 1
I2C_ADDRESS = 0x3C
ADC_VREF = 3.3
ADC_RESOLUTION = 1023.0
UPDATE_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def init_spi():
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED_HZ
        spi.mode = 0
        log.info("SPI bus %d device %d opened at %d Hz", SPI_BUS, SPI_DEVICE, SPI_SPEED_HZ)
        return spi
    except Exception as exc:
        log.error("Failed to initialize SPI: %s", exc)
        try:
            spi.close()
        except Exception:
            pass
        raise


def init_oled():
    try:
        serial = i2c(port=I2C_PORT, address=I2C_ADDRESS)
        device = ssd1306(serial)
        log.info("SSD1306 OLED initialized on I2C bus %d at address 0x%02X", I2C_PORT, I2C_ADDRESS)
        return device
    except Exception as exc:
        log.error("Failed to initialize OLED: %s", exc)
        raise


def read_adc_channel(spi, channel):
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be 0-7")
    cmd = [0x01, (0x08 | channel) << 4, 0x00]
    try:
        resp = spi.xfer2(cmd)
    except Exception as exc:
        log.error("SPI transfer failed on channel %d: %s", channel, exc)
        raise
    if len(resp) < 3:
        raise IOError("Incomplete SPI response")
    value = ((resp[1] & 0x03) << 8) | resp[2]
    return value


def voltage(value):
    return value * ADC_VREF / ADC_RESOLUTION


def display_data(device, voltages):
    try:
        with canvas(device) as draw:
            draw.text((0, 0), "MCP3008 CH0-3", fill="white")
            for i, v in enumerate(voltages):
                draw.text((0, 10 + i * 10), f"CH{i}: {v:.3f} V", fill="white")
    except Exception as exc:
        log.error("Failed to update OLED display: %s", exc)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    spi = None
    device = None
    try:
        spi = init_spi()
        device = init_oled()

        while _running:
            voltages = []
            for ch in range(4):
                try:
                    raw = read_adc_channel(spi, ch)
                    voltages.append(voltage(raw))
                except Exception as exc:
                    log.warning("Skipping channel %d: %s", ch, exc)
                    voltages.append(float("nan"))

            display_data(device, voltages)
            time.sleep(UPDATE_INTERVAL_S)

    except Exception as exc:
        log.error("Fatal error: %s", exc)
        sys.exit(1)
    finally:
        if device is not None:
            try:
                device.cleanup()
            except Exception:
                pass
        if spi is not None:
            try:
                spi.close()
            except Exception:
                pass
        log.info("Resources released. Exiting.")


if __name__ == "__main__":
    main()

