import signal
import sys
import time

import smbus2
from luma.core.interface.serial import i2c as luma_i2c
from luma.oled.device import ssd1306
from PIL import Image, ImageDraw, ImageFont

# --- Constants ---------------------------------------------------------------
I2C_BUS = 1
TSL2561_ADDR = 0x29
OLED_ADDR = 0x3C

TSL2561_REG_CONTROL = 0x80
TSL2561_REG_TIMING = 0x81
TSL2561_REG_DATA0LOW = 0xAC
TSL2561_REG_ID = 0x8A
TSL2561_REG_COMMAND_BIT = 0xA0
TSL2561_REG_WORD_BIT = 0x22

TSL2561_INTEGRATIONTIME_101MS = 0x00
TSL2561_GAIN_1X = 0x00
TSL2561_POWER_ON = 0x03
TSL2561_POWER_OFF = 0x00

# --- Globals for cleanup -----------------------------------------------------
_bus = None
_oled = None
_tsl = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _tsl2561_write(bus, reg, value):
    bus.write_byte_data(TSL2561_ADDR, reg | TSL2561_REG_COMMAND_BIT, value)


def _tsl2561_read(bus, reg):
    return bus.read_byte_data(TSL2561_ADDR, reg | TSL2561_REG_COMMAND_BIT)


def _tsl2561_init(bus):
    """Initialize the TSL2561 and verify the sensor ID if readable."""
    chip_id = _tsl2561_read(bus, TSL2561_REG_ID)
    if chip_id != 0x40 and chip_id != 0x41 and chip_id != 0x42:
        raise RuntimeError(
            f"TSL2561 not found (ID=0x{chip_id:02X}); expected 0x40/0x41/0x42"
        )

    _tsl2561_write(bus, TSL2561_REG_CONTROL, TSL2561_POWER_ON)
    _tsl2561_write(bus, TSL2561_REG_TIMING, TSL2561_INTEGRATIONTIME_101MS | TSL2561_GAIN_1X)
    time.sleep(0.01)


def _tsl2561_power_off(bus):
    try:
        _tsl2561_write(bus, TSL2561_REG_CONTROL, TSL2561_POWER_OFF)
    except OSError:
        pass


def _tsl2561_read_full_spectrum(bus):
    data0 = bus.read_word_data(TSL2561_ADDR, TSL2561_REG_DATA0LOW | TSL2561_REG_COMMAND_BIT | TSL2561_REG_WORD_BIT)
    data1 = bus.read_word_data(TSL2561_ADDR, TSL2561_REG_DATA0LOW + 2 | TSL2561_REG_COMMAND_BIT | TSL2561_REG_WORD_BIT)
    return data0, data1


def _calculate_lux(data0, data1):
    if data0 == 0 and data1 == 0:
        return 0.0
    ratio = data1 / data0 if data0 != 0 else 0.0
    if 0 <= ratio <= 0.52:
        lux = (0.0315 * data0) - (0.0593 * data0 * (ratio ** 1.4))
    elif ratio <= 0.65:
        lux = (0.0229 * data0) - (0.0291 * data1)
    elif ratio <= 0.80:
        lux = (0.0157 * data0) - (0.0180 * data1)
    elif ratio <= 1.3:
        lux = (0.00338 * data0) - (0.00260 * data1)
    else:
        lux = 0.0
    return max(0.0, lux)


def _scale_to_byte(lux):
    return int(min(max(lux, 0), 255))


def _render_text(device, text):
    image = Image.new("1", (device.width, device.height))
    draw = ImageDraw.Draw(image)
    try:
        font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 12)
    except OSError:
        font = ImageFont.load_default()
    draw.text((0, 0), text, font=font, fill=255)
    device.display(image)


def main():
    global _bus, _oled, _tsl

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- I2C bus --------------------------------------------------------------
    try:
        _bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    # --- TSL2561 --------------------------------------------------------------
    try:
        _tsl2561_init(_bus)
    except (OSError, RuntimeError) as e:
        print(f"Error: TSL2561 init failed: {e}", file=sys.stderr)
        _bus.close()
        sys.exit(1)

    # --- OLED ----------------------------------------------------------------
    try:
        serial = luma_i2c(port=I2C_BUS, address=OLED_ADDR)
        _oled = ssd1306(serial, rotate=0)
    except Exception as e:
        print(f"Error: OLED init failed: {e}", file=sys.stderr)
        _tsl2561_power_off(_bus)
        _bus.close()
        sys.exit(1)

    # --- Main loop -----------------------------------------------------------
    try:
        while _running:
            try:
                data0, data1 = _tsl2561_read_full_spectrum(_bus)
                lux = _calculate_lux(data0, data1)
                brightness = _scale_to_byte(lux)
                _render_text(_oled, f"Lux: {lux:.2f}  B: {brightness}")
            except OSError as e:
                print(f"Warning: I2C read error: {e}", file=sys.stderr)
                try:
                    _oled.clear()
                except Exception:
                    pass
            time.sleep(1)
    finally:
        _tsl2561_power_off(_bus)
        try:
            _oled.clear()
        except Exception:
            pass
        if _bus is not None:
            _bus.close()


if __name__ == "__main__":
    main()

