import os
import sys
import time
import signal
import logging
from PIL import Image, ImageSequence

try:
    from lib.st7789 import ST7789
except ImportError:
    logging.error("ST7789 library not found. Please install it.")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DEFAULT_GIF_FOLDER = "/home/pi/gifs"
DEFAULT_WIDTH = 240
DEFAULT_HEIGHT = 240
DEFAULT_ROTATION = 0
DEFAULT_OFFSET = 0
DEFAULT_IS_RED_BOARD = 0
DEFAULT_CENTER = 0
DEFAULT_SPEED = 100
FRAME_DURATION_MS = 0.1


class GifPlayer:
    def __init__(self, folder=DEFAULT_GIF_FOLDER, width=DEFAULT_WIDTH, height=DEFAULT_HEIGHT,
                 rotation=DEFAULT_ROTATION, offset=DEFAULT_OFFSET, is_red=DEFAULT_IS_RED_BOARD,
                 center=DEFAULT_CENTER, speed=DEFAULT_SPEED):
        self.folder = folder
        self.width = width
        self.height = height
        self.rotation = rotation
        self.offset = offset
        self.is_red = is_red
        self.center = center
        self.speed = speed
        self.gif_files = []
        self.display = None
        self._running = True

        try:
            self.display = ST7789(
                width=self.width, height=self.height,
                rotation=self.rotation, offset=self.offset,
                isRedBoard=self.is_red, center=self.center
            )
            logging.info("ST7789 display initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize ST7789 display: {e}")
            self.display = None

        if not os.path.isdir(self.folder):
            logging.error(f"Folder not found: {self.folder}")
            return

        try:
            self.gif_files = sorted(
                [f for f in os.listdir(self.folder) if f.lower().endswith(".gif")]
            )
            logging.info(f"Found {len(self.gif_files)} GIF files in {self.folder}")
        except OSError as e:
            logging.error(f"Error listing folder {self.folder}: {e}")

    def play(self, gif_file):
        if not self.display:
            logging.error("Display not initialized. Cannot play GIF.")
            return

        gif_path = os.path.join(self.folder, gif_file)
        try:
            with Image.open(gif_path) as image:
                for frame in ImageSequence.Iterator(image):
