    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

# Configuration file path
CONFIG_FILE = "config.json"

# Default configuration values
DEFAULT_CONFIG = {
    "gpio_button_pin": 17,
    "aqi_thresholds": {
        "green": 50,
        "yellow": 99,
        "orange": 149,
        "red": 150
    },
    "update_interval": 300,
    "log_level": "INFO",
    "database_file": "air_quality.db"
}

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        logging.info(f"Configuration loaded from {config_file}")
        return config
    except FileNotFoundError:
        logging.warning(f"Configuration file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}. Using defaults.")
        return DEFAULT_CONFIG
    except Exception as e:
        logging.error(f"Error loading configuration: {e}. Using defaults.")
        return DEFAULT_CONFIG

def setup_logging(log_level):
    """Sets up logging with the specified level."""
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f"Invalid log level: {log_level}")
    logging.basicConfig(
        filename="air_quality_monitor.log",
        level=numeric_level,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

def initialize_gpio(gpio_button_pin):
    """Initializes GPIO pins for the button with pull-up resistor."""
    if GPIO is None:
        logging.warning("RPi.GPIO not available. GPIO disabled.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_button_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info(f"GPIO initialized for button on pin {gpio_button_pin}")
        return True
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        return False

def read_simulated_sensor_data():
    """Reads simulated sensor data for AQI and PM2.5."""
    try:
        aqi = random.randint(0, 200)
        pm25 = random.uniform(5, 35)
        if random.random() < 0.2:
            raise IOError("Simulated sensor error")
        return aqi, pm25
    except IOError as e:
        logging.error(f"Simulated sensor error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected error reading simulated sensor data: {e}")
        return None, None

