        cursor = conn.cursor()
        cursor.execute(
            "CREATE TABLE IF NOT EXISTS readings (timestamp TEXT, aqi INTEGER, pm25 REAL)"
        )
        cursor.execute(
            "INSERT INTO readings (timestamp, aqi, pm25) VALUES (?, ?, ?)",
            (timestamp, aqi, pm25),
        )
        conn.commit()
        logging.info(f"Data stored in database: Timestamp={timestamp}, AQI={aqi}, PM2.5={pm25}")
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")
    finally:
        if conn:
            conn.close()

def get_aqi_category(aqi, aqi_thresholds):
    """Determines the AQI category based on thresholds."""
    if aqi < aqi_thresholds["green"]:
        return "GREEN"
    elif aqi <= aqi_thresholds["yellow"]:
        return "YELLOW"
    elif aqi <= aqi_thresholds["orange"]:
        return "ORANGE"
    else:
        return "RED"

def display_data_on_epaper_display(aqi, pm25, aqi_category):
    """Simulates displaying data on an e-paper display."""
    print(f"e-Paper Display: AQI: {aqi}, PM2.5: {pm25:.2f}, Category: {aqi_category}")
    logging.info(f"e-Paper Display: AQI: {aqi}, PM2.5: {pm25:.2f}, Category: {aqi_category}")

def explain_aqi_value(aqi, aqi_category):
    """Provides an explanation of the AQI value and its health implications."""
    explanations = {
        "GREEN": "Good air quality. No health concerns.",
        "YELLOW": "Moderate air quality. Sensitive individuals may experience minor symptoms.",
        "ORANGE": "Unhealthy for sensitive groups. Children, elderly, and individuals with respiratory issues may experience symptoms.",
        "RED": "Unhealthy air quality. Everyone may experience symptoms. Avoid strenuous outdoor activities.",
    }
    print(f"AQI Value: {aqi}, Category: {aqi_category}, Explanation: {explanations[aqi_category]}")
    logging.info(f"AQI Value: {aqi}, Category: {aqi_category}, Explanation: {explanations[aqi_category]}")

def button_callback(channel, config):
    """Callback function for button press events."""
    aqi, pm25 = read_simulated_sensor_data()
    if aqi is not None and pm25 is not None:
        timestamp = datetime.datetime.now().isoformat()
        store_data_in_database(config["database_file"], timestamp, aqi, pm25)
        aqi_category = get_aqi_category(aqi, config["aqi_thresholds"])
        display_data_on_epaper_display(aqi, pm25, aqi_category)
        explain_aqi_value(aqi, aqi_category)
    else:
        logging.warning("Failed to read sensor data. Skipping display update.")

def main():
    """Main function to run the air quality monitor."""
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    setup_logging(config["log_level"])

    gpio_initialized = False
    if config.get("gpio_button_pin") is not None:
        gpio_initialized = initialize_gpio(config["gpio_button_pin"])
    else:
        logging.warning("gpio_button_pin not specified in config. GPIO disabled.")

    last_update_time = 0

    try:
        while running:
            if gpio_initialized:
                if GPIO is not None:
                    if GPIO.input(config["gpio_button_pin"]) == GPIO.LOW:
                        current_time = time.time()
                        if current_time - last_update_time >= config["update_interval"]:
                            button_callback(config["gpio_button_pin"], config)
                            last_update_time = current_time
                        else:
                            logging.debug("Button pressed, but update interval not met.")
                else:
                    logging.warning("RPi.GPIO not available. GPIO disabled.")
                    gpio_initialized = False
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if gpio_initialized and GPIO is not None:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        logging.info("Exiting program.")

if __name__ == "__main__":
    main()

