import os
import sys
import time
import signal
import logging
from PIL import Image, ImageOps

try:
    import smbus2
except ImportError:
    smbus2 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

OLED_WIDTH = 128
OLED_HEIGHT = 64
I2C_BUS = 1
I2C_ADDR = 0x3C

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info('Signal received, shutting down...')


def _init_i2c_bus():
    if smbus2 is None:
        logger.error('smbus2 library not available')
        return None
    try:
        bus = smbus2.SMBus(I2C_BUS)
        logger.info(f'I2C bus {I2C_BUS} initialized')
        return bus
    except FileNotFoundError:
        logger.error(f'I2C bus {I2C_BUS} not found. Enable I2C with `sudo raspi-config`')
        return None
    except PermissionError:
        logger.error(f'Permission denied on I2C bus {I2C_BUS}. Run as root or add user to i2c group')
        return None
    except Exception as e:
        logger.error(f'Failed to initialize I2C bus {I2C_BUS}: {e}')
        return None


def _init_oled(bus):
    if bus is None:
        return None
    try:
        # SSD1306 init sequence
        cmds = [
            [0x00, 0xAE],  # Display OFF
            [0x00, 0xD5, 0x80],  # Set display clock divide ratio/oscillator frequency
            [0x00, 0xA8, 0x3F],  # Set multiplex ratio (64)
            [0x00, 0xD3, 0x00],  # Set display offset
            [0x00, 0x40],  # Set start line
            [0x00, 0x8D, 0x14],  # Enable charge pump
            [0x00, 0x20, 0x00],  # Set memory addressing mode to horizontal
            [0x00, 0xA1],  # Set segment re-map (column 127 mapped to SEG0)
            [0x00, 0xC8],  # Set COM output scan direction (remapped mode)
            [0x00, 0xDA, 0x12],  # Set COM pins hardware configuration
            [0x00, 0x81, 0xCF],  # Set contrast
            [0x00, 0xD9, 0xF1],  # Set pre-charge period
            [0x00, 0xDB, 0x40],  # Set VCOMH deselect level
            [0x00, 0xA4],  # Display ON resume
            [0x00, 0xA6],  # Set normal display (not inverted)
            [0x00, 0xAF],  # Display ON
        ]
        for cmd in cmds:
            bus.write_i2c_block_data(I2C_ADDR, cmd[0], cmd[1:])
        logger.info('SSD1306 OLED initialized')
        return bus
    except Exception as e:
        logger.error(f'Failed to initialize OLED: {e}')
        return None


def _display_frame(bus, image):
    if bus is None:
        return
    try:
        # Convert to 1-bit and pad to 128x64
        img = ImageOps.pad(image.convert('1'), (OLED_WIDTH, OLED_HEIGHT), method=Image.NEAREST, color=0, centering=(0.5, 0.5))
        pixels = list(img.getdata())
        # Pack 8 pixels per byte
        data = bytearray()
        for row in range(OLED_HEIGHT):
            for col in range(0, OLED_WIDTH, 8):
                byte = 0
                for bit in range(8):
                    if col + bit < OLED_WIDTH:
                        if pixels[row * OLED_WIDTH + col + bit]:
                            byte |= (1 << bit)
                data.append(byte)
        # Set column and page address range
        bus.write_i2c_block_data(I2C_ADDR, 0x00, [0x21, 0x00, 0x7F])  # Set column address range (0-127)
        bus.write_i2c_block_data(I2C_ADDR, 0x00, [0x22, 0x00, 0x07])  # Set page address range (0-7)
        # Send image data
        for i in range(0, len(data), 16):
            chunk = data[i:i+16]
            bus.write_i2c_block_data(I2C_ADDR, 0x40, list(chunk))
    except Exception as e:
        logger.error(f'Failed to display frame: {e}')


def _load_gif_frames(gif_path):
    try:
        with Image.open(gif_path) as img:
            frames = []
            for frame in range(img.n_frames):
                img.seek(frame)
                duration = img.info.get('duration', 100)
                frames.append((img.copy(), duration))
            if not frames:
                logger.warning(f'GIF {gif_path} has no frames')
                return None
            return frames
    except FileNotFoundError:
        logger.error(f'File not found: {gif_path}')
        return None
    except Exception as e:
        logger.error(f'Failed to load GIF {gif_path}: {e}')
        return None


def _play_gif(bus, gif_path, loop_count):
    frames = _load_gif_frames(gif_path)
    if frames is None:
        return False
    total_duration = 0
    for frame_img, duration in frames:
        total_duration += duration
        _display_frame(bus, frame_img)
        time.sleep(duration / 1000.0)
        if not _running:
            return False
    if loop_count > 0:
        for _ in range(1, loop_count):
            if not _running:
                break
            for frame_img, duration in frames:
                _display_frame(bus, frame_img)
                time.sleep(duration / 1000.0)
                if not _running:
                    return False
    return True


def play_gifs_in_folder(folder_path):
    global _running
    _running = True
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = _init_i2c_bus()
    oled = _init_oled(bus)
    if oled is None:
        if bus is not None:
            bus.close()
        return

    try:
        gif_files = [f for f in os.listdir(folder_path) if f.lower().endswith('.gif')]
        if not gif_files:
            logger.warning(f'No GIF files found in folder: {folder_path}')
            return
        logger.info(f'Found {len(gif_files)} GIF files')
        for gif_file in gif_files:
            if not _running:
                break
            gif_path = os.path.join(folder_path, gif_file)
            try:
                with Image.open(gif_path) as img:
                    loop_count = img.info.get('loop', 0)
                logger.info(f'Playing GIF: {gif_file} (loop={loop_count})')
                if not _play_gif(oled, gif_path, loop_count):
                    break
            except Exception as e:
                logger.error(f'Error processing GIF {gif_file}: {e}')
    finally:
        logger.info('Cleaning up...')
        try:
            if oled is not None:
                oled.write_i2c_block_data(I2C_ADDR, 0x00, [0xAE])  # Display OFF
        except Exception:
            pass
        if bus is not None:
            bus.close()
        logger.info('Done.')


if __name__ == '__main__':
    folder_path = sys.argv[1] if len(sys.argv) > 1 else '.'
    play_gifs_in_folder(folder_path)

