import smbus
import time
import signal
import sys

# PCF8574 I2C address (A0-A2 tied to GND)
PCF8574_ADDR = 0x20
# Default I2C bus on Raspberry Pi (physical pins 3 SDA, 5 SCL)
I2C_BUS = 1
POLL_INTERVAL = 0.1
ERROR_RETRY_DELAY = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_pcf8574(bus, addr):
    """Read all 8 port pins from the PCF8574; return int or None on error."""
    try:
        return bus.read_byte(addr)
    except OSError as e:
        print(f"I2C read error: {e}")
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        while _running:
            data = read_pcf8574(bus, PCF8574_ADDR)
            if data is None:
                time.sleep(ERROR_RETRY_DELAY)
                continue

            for sensor in range(8):
                # Active-low: pin reads 0 when obstacle is present
                if (data & (1 << sensor)) == 0:
                    print(f"Obstacle detected by sensor {sensor}")

            time.sleep(POLL_INTERVAL)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

