import json
import random
import signal
import sys
import time
import threading

import paho.mqtt.client as mqtt

BROKER = "test.mosquitto.org"
PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
MESSAGE_COUNT = 5
RETRY_DELAY = 2
MAX_RETRIES = 3

shutdown_event = threading.Event()


def on_connect(client, userdata, flags, reason_code, properties):
    """Callback invoked when the broker responds to our CONNECT request."""
    if reason_code == 0:
        userdata["connected"].set()
    else:
        print(f"[WARN] Connection failed with reason code: {reason_code}")


def on_publish(client, userdata, mid, reason_code, properties):
    """Callback invoked when the broker acknowledges a PUBLISH."""
    print(f"[INFO] Message {mid} published successfully.")


def generate_temperature():
    """Return a simulated temperature reading in °C rounded to two decimals."""
    return round(random.uniform(19.00, 26.00), 2)


def build_payload(index):
    """Build the JSON payload for the given reading index."""
    return json.dumps({"temperature": generate_temperature(), "index": index})


def publish_messages(client, count):
    """Publish `count` temperature messages, returning the number acknowledged."""
    acknowledged = 0
    for i in range(count):
        payload = build_payload(i)
        result = client.publish(TOPIC, payload, qos=1)
        if result.rc == mqtt.MQTT_ERR_SUCCESS:
            acknowledged += 1
        else:
            print(f"[ERROR] Publish failed for index {i} with rc={result.rc}")
        time.sleep(1)
    return acknowledged


def connect_with_retry(client, broker, port, keepalive, retries=MAX_RETRIES):
    """Attempt to connect to the broker, retrying on failure."""
    for attempt in range(1, retries + 1):
        try:
            client.connect(broker, port, keepalive)
            return True
        except Exception as e:
            print(f"[ERROR] Connection attempt {attempt}/{retries} failed: {e}")
            if attempt < retries:
                time.sleep(RETRY_DELAY)
    return False


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    print(f"\n[INFO] Signal {signum} received, shutting down...")
    shutdown_event.set()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    client = mqtt.Client(
        mqtt.CallbackAPIVersion.VERSION2,
        client_id="rpi-classroom-publisher",
    )
    client.on_connect = on_connect
    client.on_publish = on_publish

    state = {"connected": threading.Event()}
    client.user_data_set(state)

    try:
        if not connect_with_retry(client, BROKER, PORT, KEEPALIVE):
            print("[FATAL] Could not connect to broker after retries.")
            sys.exit(1)

        print("[INFO] Waiting for CONNACK...")
        if not state["connected"].wait(timeout=10):
            print("[FATAL] Timed out waiting for CONNACK.")
            sys.exit(1)

        print("[INFO] Connected. Starting publish loop.")
        acknowledged = publish_messages(client, MESSAGE_COUNT)
        print(f"[INFO] {acknowledged}/{MESSAGE_COUNT} messages acknowledged.")

        if acknowledged == MESSAGE_COUNT:
            sys.exit(0)
        else:
            sys.exit(1)

    except Exception as e:
        print(f"[FATAL] Unexpected error: {e}")
        sys.exit(1)
    finally:
        print("[INFO] Disconnecting...")
        try:
            client.disconnect()
        except Exception:
            pass
        print("[INFO] Done.")


if __name__ == "__main__":
    main()

