_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def ensure_data_dir():
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
    except OSError as exc:
        print(f"Failed to create data directory {DATA_DIR}: {exc}", file=sys.stderr)
        sys.exit(1)


def log_error(message):
    try:
        with open(ERROR_PATH, "a", encoding="utf-8") as fh:
            fh.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}, {message}\n")
    except OSError as exc:
        print(f"Failed to write error log: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ensure_data_dir()

    try:
        sensor = adafruit_dht.DHT22(D4, use_pulseio=False)
    except Exception as exc:
        log_error(f"Sensor init failed: {exc}")
        sys.exit(1)

    try:
        while _running:
            try:
                temperature = sensor.temperature
            except RuntimeError as exc:
                log_error(f"Sensor read error: {exc}")
            except Exception as exc:
                log_error(f"Unexpected sensor error: {exc}")
            else:
                if temperature is not None:
                    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    try:
                        with open(CSV_PATH, "a", newline="", encoding="utf-8") as fh:
                            writer = csv.writer(fh)
                            writer.writerow([timestamp, f"{temperature:.2f}"])
                    except OSError as exc:
                        log_error(f"CSV write error: {exc}")
                else:
                    log_error("Sensor returned None for temperature")

            time.sleep(2.0)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

