import time
import logging
import smbus2
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

DHT20_I2C_ADDR = 0x76
DHT20_STATUS_REG = 0x71
DHT20_DATA_REG = 0x71
DHT20_INIT_DELAY = 0.5
DHT20_TIMEOUT = 0.1
DHT20_MAX_RETRIES = 5
DHT20_RETRY_DELAY = 2.0
DHT20_STATUS_MASK = 0x18
DHT20_EXPECTED_STATUS = 0x18


class DHT20:
    def __init__(self, i2c_bus=1):
        self.i2c_bus_num = i2c_bus
        self.bus = None
        self._closed = False
        try:
            self.bus = smbus2.SMBus(self.i2c_bus_num)
            time.sleep(DHT20_INIT_DELAY)
            logging.info(f"DHT20 initialized on I2C bus {self.i2c_bus_num}.")
        except Exception as e:
            logging.error(f"Error initializing DHT20 on bus {self.i2c_bus_num}: {e}")
            self.bus = None

    def _read_register(self, register, length=1):
        if not self.bus:
            logging.error("I2C bus not initialized.")
            return None
        try:
            return self.bus.read_i2c_block_data(DHT20_I2C_ADDR, register, length)
        except Exception as e:
            logging.error(f"Error reading from register 0x{register:02X}: {e}")
            return None

    def _write_register(self, register, data):
        if not self.bus:
            logging.error("I2C bus not initialized.")
            return False
        try:
            self.bus.write_i2c_block_data(DHT20_I2C_ADDR, register, data)
            return True
        except Exception as e:
            logging.error(f"Error writing to register 0x{register:02X}: {e}")
            return False

    def _check_status(self):
        data = self._read_register(DHT20_STATUS_REG, 1)
        if data is None:
            return False
        status = (data[0] & DHT20_STATUS_MASK) == DHT20_EXPECTED_STATUS
        if not status:
            logging.error(f"Status check failed: 0x{data[0]:02X}")
        return status

    @staticmethod
    def _calculate_crc8(data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def read(self):
        if not self.bus:
            logging.error("I2C bus not initialized.")
            return None, None, True

        for attempt in range(DHT20_MAX_RETRIES):
