DHT20_I2C_ADDR = 0x76
DHT20_STATUS_REG = 0x71
DHT20_MEASURE_REG = 0xAC
DHT20_DATA_REG = 0x71
DHT20_TIMEOUT = 0.1
DHT20_MEASURE_DELAY = 0.01


class DHT20:
    def __init__(self, i2c_bus=1):
        self.bus = None
        self._running = True
        try:
            self.bus = smbus2.SMBus(i2c_bus)
            logging.info(f"Opened I2C bus {i2c_bus}")
            self._verify_sensor()
        except Exception as e:
            logging.error(f"Failed to initialize DHT20 on I2C bus {i2c_bus}: {e}")
            self.bus = None

    def _verify_sensor(self):
        try:
            status = self.bus.read_byte_data(DHT20_I2C_ADDR, DHT20_STATUS_REG)
            if status & 0x18 != 0x18:
                raise RuntimeError(f"Sensor not detected or not in ready state (status=0x{status:02X})")
            logging.info("DHT20 sensor verified successfully.")
        except Exception as e:
            logging.error(f"Failed to verify DHT20 sensor: {e}")
            self.close()
            raise

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def measure(self):
        if self.bus is None:
            logging.error("I2C bus not initialized.")
            return None, None, True
        try:
            self.bus.write_i2c_block_data(DHT20_I2C_ADDR, DHT20_MEASURE_REG, [0x33, 0x00])
            start_time = time.time()
            while True:
                status = self.bus.read_byte_data(DHT20_I2C_ADDR, DHT20_STATUS_REG)
                if status & 0x80:
                    break
                if time.time() - start_time > DHT20_TIMEOUT:
                    logging.error("Timeout waiting for measurement.")
                    return None, None, True
                time.sleep(DHT20_MEASURE_DELAY)
            data = self.bus.read_i2c_block_data(DHT20_I2C_ADDR, DHT20_DATA_REG, 7)
            if self._crc8(data[:6]) != data[6]:
                logging.error("CRC error in measurement data.")
                return None, None, True
            humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
            temperature = float(temperature_raw) / 0x100000 * 200.0 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0
            return temperature, humidity, False
        except Exception as e:
            logging.error(f"Error during measurement: {e}")
            return None, None, True

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None

    def stop(self, signum=None, frame=None):
        logging.info("Stopping DHT20...")
        self._running = False
        self.close()
        if signum is not None:
            sys.exit(0)


if __name__ == "__main__":
    sensor = DHT20(i2c_bus=1)
    if sensor.bus is not None:
        signal.signal(signal.SIGINT, sensor.stop)
        signal.signal(signal.SIGTERM, sensor.stop)
        try:
            temperature, humidity, crc_error = sensor.measure()
            if crc_error:
                logging.error("Measurement failed due to CRC error.")
            else:
                logging.info(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
        finally:
            sensor.close()

