import time
import signal
import sys
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to confirm it is operational
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()
        if not devices:
            print("Warning: No I2C devices detected on the bus.")
        else:
            print(f"I2C devices found: {[hex(d) for d in devices]}")
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer (default address 0x70)."""
    try:
        mux = adafruit_tca9548a.TCA9548A(i2c_bus)
        # Probe each channel to confirm the multiplexer is functioning
        present = []
        for ch in range(8):
            try:
                test = mux.scan(ch)
                if test:
                    present.append(ch)
            except Exception:
                pass
        if not present:
            print("Warning: No I2C devices detected behind the multiplexer.")
        else:
            print(f"Multiplexer channels with devices: {present}")
        return mux
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None

def initialize_sensors(multiplexer):
    """Initialize the BME280 and TSL2591 sensors via the multiplexer."""
    bme280 = None
    tsl2591 = None
    try:
        # BME280 default I2C address is 0x76 (SDO tied to GND)
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0])
        print("BME280 initialized on multiplexer channel 0.")
    except Exception as e:
        print(f"Error initializing BME280: {e}")

    try:
        # TSL2591 default I2C address is 0x29
        tsl2591 = adafruit_tsl2591.TSL2591(multiplexer[1])
        print("TSL2591 initialized on multiplexer channel 1.")
    except Exception as e:
        print(f"Error initializing TSL2591: {e}")

    return bme280, tsl2591

def read_sensor_data(bme280, tsl2591):
    """Read temperature, humidity, and light intensity from the sensors."""
    temperature = None
    humidity = None
    light_intensity = None

    if bme280 is not None:
        try:
            temperature = bme280.temperature
            humidity = bme280.humidity
        except Exception as e:
            print(f"Error reading BME280 data: {e}")

    if tsl2591 is not None:
        try:
            light_intensity = tsl2591.lux
        except Exception as e:
            print(f"Error reading TSL2591 data: {e}")

    return temperature, humidity, light_intensity

def display_sensor_data(temperature, humidity, light_intensity):
    """Print the sensor readings to the console."""
    if temperature is not None:
        print(f"Temperature: {temperature:.2f} C", end=" | ")
    else:
        print("Temperature: N/A", end=" | ")

    if humidity is not None:
        print(f"Humidity: {humidity:.2f} %", end=" | ")
    else:
        print("Humidity: N/A", end=" | ")

    if light_intensity is not None:
        print(f"Light Intensity: {light_intensity:.2f} lux")
    else:
        print("Light Intensity: N/A")

def main():
    """Main function to initialize sensors and read data in a loop."""
    global _running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("Failed to initialize I2C bus. Exiting.")
        sys.exit(1)

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        print("Failed to initialize multiplexer. Exiting.")
        sys.exit(1)

    bme280, tsl2591 = initialize_sensors(multiplexer)

    if bme280 is None and tsl2591 is None:
        print("No sensors initialized. Exiting.")
        sys.exit(1)

    print("Starting sensor readings. Press Ctrl+C to stop.")
    try:
        while _running:
            temperature, humidity, light_intensity = read_sensor_data(bme280, tsl2591)
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(2.0)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        print("\nExiting program.")

if __name__ == "__main__":
    main()

