import time
import signal
import sys

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PWM_PIN = 18
PWM_FREQ = 50
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"
SAMPLE_INTERVAL = 1.0

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_cpu_temp():
    try:
        with open(TEMP_FILE, "r") as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def compute_duty_cycle(temp):
    if temp < 40.0:
        return 0.0
    elif temp < 50.0:
        return 25.0
    elif temp < 60.0:
        return 50.0
    elif temp < 70.0:
        return 75.0
    else:
        return 100.0

def main():
    global running
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        fan = PWMOutputDevice(PWM_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Error initializing PWM on BCM pin {PWM_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            temp = read_cpu_temp()
            if temp is not None:
                duty = compute_duty_cycle(temp)
                fan.value = duty / 100.0
                print(f"CPU Temp: {temp:.1f}C, Fan Duty: {duty:.1f}%")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nFan control interrupted by user.")
    finally:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
        print("PWM stopped and resources released.")

if __name__ == "__main__":
    main()

