import json
import logging
import random
import signal
import sys
import time
from collections import deque

import urllib.request
import urllib.error

try:
    import adafruit_dht
    import board
    _DHT_AVAILABLE = True
except Exception:
    _DHT_AVAILABLE = False

_running = True
_dht_device = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _dht_device
    if _dht_device is not None:
        try:
            _dht_device.exit()
        except Exception:
            pass
        _dht_device = None


def _read_config(path="config.json"):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error("Configuration file not found: %s", path)
    except json.JSONDecodeError as e:
        logging.error("Invalid JSON in configuration file: %s", e)
    except OSError as e:
        logging.error("Error reading configuration file: %s", e)
    return None


def _validate_data(temperature, humidity):
    if not (-40 <= temperature <= 80):
        logging.warning("Temperature out of range: %.2f", temperature)
        return False
    if not (0 <= humidity <= 100):
        logging.warning("Humidity out of range: %.2f", humidity)
        return False
    return True


def _simulate_data():
    temperature = random.uniform(20, 30)
    humidity = random.uniform(60, 80)
    logging.info("Simulating data: Temperature: %.2f, Humidity: %.2f", temperature, humidity)
    return temperature, humidity


def _calculate_moving_average(data, window_size=5):
    if not data:
        return 0.0
    return sum(data) / len(data)


def _send_webhook(url, temperature, humidity, webhook_retries=3, retry_backoff=[1, 3, 9]):
    payload = json.dumps({"temperature": temperature, "humidity": humidity}).encode("utf-8")
    headers = {"Content-Type": "application/json"}
    req = urllib.request.Request(url, data=payload, headers=headers, method="POST")
    for attempt in range(1, webhook_retries + 1):
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                logging.info("Webhook sent successfully. Status code: %d", resp.status)
                return True
        except urllib.error.HTTPError as e:
            logging.error("HTTP error sending webhook (attempt %d/%d): %s", attempt, webhook_retries, e)
        except urllib.error.URLError as e:
            logging.error("URL error sending webhook (attempt %d/%d): %s", attempt, webhook_retries, e)
        except Exception as e:
            logging.error("Unexpected error sending webhook (attempt %d/%d): %s", attempt, webhook_retries, e)
        if attempt < webhook_retries:
            time.sleep(retry_backoff[attempt - 1])
    logging.error("Failed to send webhook after %d attempts.", webhook_retries)
    return False


def _read_dht22():
    global _dht_device
    if _dht_device is None:
        return None, None
    try:
        temperature = _dht_device.temperature
        humidity = _dht_device.humidity
        if temperature is None or humidity is None:
            logging.warning("DHT22 returned None values.")
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        logging.error("DHT22 read error: %s", e)
        return None, None
    except Exception as e:
        logging.error("Unexpected DHT22 error: %s", e)
        return None, None


def main():
    global _dht_device, _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

    config = _read_config()
    if not config:
        logging.error("Failed to load configuration. Exiting.")
        return

    dht_pin = config.get("dht_pin", 4)
    webhook_url = config.get("webhook_url")
    if not webhook_url:
        logging.error("Webhook URL not found in configuration. Exiting.")
        return

    if _DHT_AVAILABLE:
        try:
            _dht_device = adafruit_dht.DHT22(getattr(board, f"D{dht_pin}"))
            logging.info("DHT22 initialized on BCM pin %d.", dht_pin)
        except Exception as e:
            logging.error("Failed to initialize DHT22 on BCM pin %d: %s", dht_pin, e)
            _dht_device = None
    else:
        logging.warning("adafruit_dht not available; using simulated data.")

    temperature_readings = deque(maxlen=5)
    humidity_readings = deque(maxlen=5)
    consecutive_failures = 0
    failure_pause = 300

    try:
        while _running:
            if consecutive_failures >= 3:
                logging.warning("Too many consecutive failures. Pausing for %d seconds.", failure_pause)
                time.sleep(failure_pause)
                consecutive_failures = 0
                continue

            temperature, humidity = None, None
            if _dht_device is not None:
                temperature, humidity = _read_dht22()
            else:
                temperature, humidity = _simulate_data()

            if temperature is not None and humidity is not None:
                if _validate_data(temperature, humidity):
                    temperature_readings.append(temperature)
                    humidity_readings.append(humidity)
                    avg_temp = _calculate_moving_average(temperature_readings)
                    avg_hum = _calculate_moving_average(humidity_readings)
                    logging.info("Temperature: %.2f, Humidity: %.2f (Avg: %.2f, %.2f)", temperature, humidity, avg_temp, avg_hum)
                    if not _send_webhook(webhook_url, temperature, humidity):
                        consecutive_failures += 1
                    else:
                        consecutive_failures = 0
                else:
                    logging.warning("Invalid data. Skipping webhook.")
                    consecutive_failures += 1
            else:
                logging.warning("Failed to read DHT22 data. Skipping webhook.")
                consecutive_failures += 1

            time.sleep(60)
    finally:
        _cleanup()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

