# DHT11 data line connected to BCM GPIO4 (board.D4, physical pin 7)
DHT_PIN = board.D4

# Initialize the DHT11 sensor with error handling for missing/wrong wiring
try:
    dht_sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
except Exception as init_err:
    print(f"Failed to initialize DHT11 sensor on {DHT_PIN}: {init_err}")
    raise SystemExit(1)

def read_sensor():
    """Read temperature and humidity from the DHT11 sensor."""
    try:
        temperature = dht_sensor.temperature
        humidity = dht_sensor.humidity
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.1f} C")
            print(f"Humidity: {humidity:.1f} %")
        else:
            print("Sensor returned None for temperature or humidity.")
    except RuntimeError as error:
        # DHT11 often throws RuntimeError on missed reads; log and continue
        print(f"RuntimeError reading DHT11: {error.args[0]}")
    except Exception as error:
        # Catch-all for unexpected I/O or library errors
        print(f"Unexpected error reading DHT11: {error}")

def main():
    """Main loop: read sensor every 5 seconds until interrupted."""
    try:
        while True:
            read_sensor()
            time.sleep(5)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Release the sensor resources on every exit path
        try:
            dht_sensor.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

