except (ImportError, RuntimeError):
    GPIO = None

try:
    import adafruit_dht
    import board
except ImportError:
    adafruit_dht = None
    board = None

DHT_PIN = 17
FAN_PIN = 18
LOG_FILE = "urban_data_log.txt"
READ_COUNT = 5
READ_INTERVAL = 2
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def log_data(temperature, humidity):
    timestamp = datetime.now().isoformat(timespec="seconds")
    line = f"{timestamp} - Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%\n"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(line)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def control_fan(temperature, humidity, fan_state):
    if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
        if not fan_state:
            print("Turning fan ON")
        return True
    else:
        if fan_state:
            print("Turning fan OFF")
        return False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    if GPIO is not None:
        GPIO.setwarnings(False)
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
    else:
        print("RPi.GPIO not available; running in degraded mode.", file=sys.stderr)

    dht_device = None
    if adafruit_dht is not None and board is not None:
        try:
            dht_device = adafruit_dht.DHT11(board.D17, use_pulseio=False)
        except Exception as e:
            print(f"Failed to initialize DHT11 on BCM 17: {e}", file=sys.stderr)
            dht_device = None
    else:
        print("adafruit_dht or board not available; running in degraded mode.", file=sys.stderr)

    fan_state = False
    readings_taken = 0

    try:
        while _running and readings_taken < READ_COUNT:
            temperature = None
            humidity = None

            if dht_device is not None:
                try:
                    temperature = dht_device.temperature
                    humidity = dht_device.humidity
                except RuntimeError as e:
                    print(f"DHT11 read error: {e}", file=sys.stderr)
