                dht_device.exit()
            except Exception:
                pass
        if GPIO is not None:
            try:
                GPIO.output(FAN_PIN, GPIO.LOW)
            except Exception:
                pass
            GPIO.cleanup()
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

