import signal
import sys
import time
import logging
import paho.mqtt.client as mqtt
from gpiozero import Device
from gpiozero.pins.native import NativeFactory
from adafruit_circuitpython_dht import DHT22

try:
    import config
except ImportError:
    raise ImportError("Error: config.py not found. Please create it with the necessary configurations.")

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = '\u00B0C'
HOMIE_VERSION = "4.0"
MAX_RETRIES = 3
RETRY_DELAY = 2

running = True
dht_sensor = None
mqtt_client = None


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def publish_message(client, topic, payload, retain=False):
    full_topic = f"homie/{config.homieclientid}/{topic}"
    try:
        info = client.publish(full_topic, str(payload).encode(), retain=retain, qos=1)
        info.wait_for_publish(timeout=5)
        logger.debug(f"Published to {full_topic}: {payload}")
    except Exception as e:
        logger.error(f"Error publishing to {full_topic}: {e}")


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.info(f"Disconnected from MQTT broker, reason code: {reason_code}")


def mqtt_connect():
    global mqtt_client
    try:
        mqtt_client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            protocol=mqtt.MQTTv5
        )
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.will_set(
            f"homie/{config.homieclientid}/$state",
            "lost",
            retain=True,
            qos=1
        )
        mqtt_client.connect(config.mqttbroker, port=config.mqttport, keepalive=30)
        mqtt_client.loop_start()
        time.sleep(1)
        if not mqtt_client.is_connected():
            raise ConnectionError("Failed to establish MQTT connection")
        configure_homie_node(mqtt_client)
    except Exception as e:
        logger.error(f"MQTT connection error: {e}")
        raise


def configure_homie_node(client):
    publish_message(client, "$state", "init")
    publish_message(client, "$homie", HOMIE_VERSION)
    publish_message(client, "$name", config.homieclientname)
    publish_message(client, "$nodes", config.homienodes)

    publish_message(client, f"{config.homienodes}/$name", "DHT22 Sensor")
    publish_message(client, f"{config.homienodes}/$properties", "temperature,humidity")

    publish_message(client, f"{config.homienodes}/temperature/$name", "Temperature")
    publish_message(client, f"{config.homienodes}/temperature/$unit", DEGREE_CELSIUS)
    publish_message(client, f"{config.homienodes}/temperature/$datatype", "float")
    publish_message(client, f"{config.homienodes}/temperature/$settable", "false")

    publish_message(client, f"{config.homienodes}/humidity/$name", "Humidity")
    publish_message(client, f"{config.homienodes}/humidity/$unit", "%")
    publish_message(client, f"{config.homienodes}/humidity/$datatype", "float")
    publish_message(client, f"{config.homienodes}/humidity/$settable", "false")

    publish_message(client, "$state", "ready")


def read_dht22():
    global dht_sensor
    if dht_sensor is None:
        raise RuntimeError("DHT22 sensor not initialized")
    for attempt in range(MAX_RETRIES):
        try:
            temperature = dht_sensor.temperature
            humidity = dht_sensor.humidity
            if temperature is not None and humidity is not None:
                return round(temperature, 1), round(humidity, 1)
            raise RuntimeError("Sensor returned None")
        except RuntimeError as e:
            logger.warning(f"DHT22 read attempt {attempt + 1}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES - 1:
                time.sleep(RETRY_DELAY)
        except Exception as e:
            logger.error(f"Unexpected error reading DHT22: {e}")
            if attempt < MAX_RETRIES - 1:
                time.sleep(RETRY_DELAY)
    raise RuntimeError("Failed to read DHT22 sensor after multiple retries")


def publish_sensor_data(client):
    try:
        temperature, humidity = read_dht22()
        logger.info(f"Temperature = {temperature}{DEGREE_CELSIUS}")
        logger.info(f"Humidity = {humidity}%")
        publish_message(client, f"{config.homienodes}/temperature", temperature)
        publish_message(client, f"{config.homienodes}/humidity", humidity)
    except RuntimeError as e:
        logger.error(f"Failed to read sensor data: {e}")
    except Exception as e:
        logger.error(f"Unexpected error publishing sensor data: {e}")


def cleanup():
    global mqtt_client, dht_sensor
    logger.info("Cleaning up resources...")
    if mqtt_client is not None:
        try:
            publish_message(mqtt_client, "$state", "lost")
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception as e:
            logger.error(f"Error during MQTT cleanup: {e}")
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception as e:
            logger.error(f"Error during DHT22 cleanup: {e}")
    logger.info("Cleanup complete.")


def main():
    global dht_sensor
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        Device.pin_factory = NativeFactory()
        dht_sensor = DHT22(config.dhtgpiopin)
        logger.info(f"DHT22 sensor initialized on BCM pin {config.dhtgpiopin}")
    except Exception as e:
        logger.error(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    try:
        mqtt_connect()
        while running:
            publish_sensor_data(mqtt_client)
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

