    dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
except Exception as exc:
    log.error("DHT22 init failed on GPIO4: %s", exc)

# DS18B20 — w1thermsensor auto-discovers the 1-Wire device on the bus.
ds18b20 = None
try:
    ds18b20 = w1thermsensor.W1ThermSensor()
except w1thermsensor.errors.NoSensorFoundError as exc:
    log.error("No DS18B20 sensor found on 1-Wire bus: %s", exc)
except Exception as exc:
    log.error("DS18B20 init error: %s", exc)

# --- Main loop ---------------------------------------------------------------
def main() -> None:
    global _running
    log.info("Hydroponics monitoring started (DHT22=GPIO4, LED=GPIO17, 1-Wire=GPIO4).")
    while _running:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        # --- DHT22 ----------------------------------------------------------
        dht_temp = None
        dht_hum = None
        if dht_device is not None:
            try:
                dht_temp = dht_device.temperature
                dht_hum = dht_device.humidity
                if dht_temp is not None and dht_hum is not None:
                    log.info("DHT22  T=%.1f°C  H=%.1f%%", dht_temp, dht_hum)
            except RuntimeError as exc:
                # DHT22 checksum / timing glitches are common; log and continue.
                log.error("DHT22 read error: %s", exc)
            except Exception as exc:
                log.error("DHT22 unexpected error: %s", exc)
        else:
            log.error("DHT22 device not initialised.")

        # --- DS18B20 ---------------------------------------------------------
        if ds18b20 is not None:
            try:
                ds_temp = ds18b20.get_temperature()
                log.info("DS18B20 T=%.2f°C", ds_temp)
            except w1thermsensor.errors.SensorNotReadyError as exc:
                log.error("DS18B20 not ready: %s", exc)
            except Exception as exc:
                log.error("DS18B20 read error: %s", exc)
        else:
            log.error("DS18B20 not initialised.")

        # --- LED control ----------------------------------------------------
        if dht_temp is not None:
            if dht_temp > DHT22_HIGH_TEMP:
                set_led(True)
                log.info("LED ON  (T=%.1f°C > %.1f°C)", dht_temp, DHT22_HIGH_TEMP)
            elif dht_temp < DHT22_LOW_TEMP:
                set_led(False)
                log.info("LED OFF (T=%.1f°C < %.1f°C)", dht_temp, DHT22_LOW_TEMP)
            # else: hold previous state

        # --- Sleep, but wake promptly on signal -----------------------------
        slept = 0
        while _running and slept < SAMPLE_INTERVAL:
            time.sleep(0.5)
            slept += 0.5

    # --- Cleanup -------------------------------------------------------------
    log.info("Shutting down.")
    set_led(False)
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if _led is not None:
        try:
            _led.close()
        except Exception:
            pass
    log.info("Cleanup complete. Exiting.")

if __name__ == "__main__":
    main()

