import time
import signal
import sys
import os
from datetime import datetime

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
LOG_FILE = '/home/pi/sensor_log.txt'
ALERT_PIN = 17
TEMP_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
ALERT_DURATION = 5

_running = True
_uart = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _uart
    if _uart is not None:
        try:
            _uart.close()
        except Exception:
            pass
        _uart = None


def _log_reading(temperature, humidity):
    timestamp = datetime.now().isoformat(timespec='seconds')
    line = f"{timestamp} - Temperature: {temperature:.2f}C, Humidity: {humidity:.2f}%\n"
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(line)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def _check_thresholds(temperature, humidity):
    if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
        print("Threshold exceeded! Activating alert.")
        try:
            os.system(f"echo 1 > /sys/class/gpio/gpio{ALERT_PIN}/value")
            time.sleep(ALERT_DURATION)
            os.system(f"echo 0 > /sys/class/gpio/gpio{ALERT_PIN}/value")
        except Exception as e:
            print(f"Error controlling GPIO: {e}", file=sys.stderr)


def main():
    global _uart

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        os.system(f"echo {ALERT_PIN} > /sys/class/gpio/export")
        os.system(f"echo out > /sys/class/gpio/gpio{ALERT_PIN}/direction")
        os.system(f"echo 0 > /sys/class/gpio/gpio{ALERT_PIN}/value")
    except Exception as e:
        print(f"Error initializing GPIO{ALERT_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        _uart = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl-C to exit.")

    try:
        while _running:
            try:
                raw = _uart.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                time.sleep(1)
                continue

            if not raw:
                continue

            try:
                line = raw.decode('ascii', errors='replace').strip()
            except Exception as e:
                print(f"Decode error: {e}", file=sys.stderr)
                continue

            if not line:
                continue

            parts = line.split(',')
            if len(parts) != 2:
                print(f"Malformed data (expected 'temp,humidity'): {line!r}", file=sys.stderr)
                continue

            try:
                temperature = float(parts[0])
                humidity = float(parts[1])
            except ValueError as e:
                print(f"Parse error: {e} - {line!r}", file=sys.stderr)
                continue

            _log_reading(temperature, humidity)
            _check_thresholds(temperature, humidity)
    finally:
        _cleanup()
        try:
            os.system(f"echo {ALERT_PIN} > /sys/class/gpio/unexport")
        except Exception:
            pass
        print("Program terminated.")


if __name__ == '__main__':
    main()

