import signal
import sys
import time
import logging

import ina219
from ina219 import INA219Error

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

SUPPLY_INA219_BUS = 1
BATTERY_INA219_BUS = 1
UPS_I2C_BUS = 1

SUPPLY_SHUNT_RESISTANCE = 0.00725
BATTERY_SHUNT_RESISTANCE = 0.005

running = True


def _handle_signal(signum, frame):
    global running
    logger.info("Received signal %s, shutting down...", signum)
    running = False


def _init_supply_sensor():
    try:
        sensor = ina219.INA219(
            SUPPLY_SHUNT_RESISTANCE,
            busnum=SUPPLY_INA219_BUS,
            address=ina219.INA219_DEFAULT_ADDRESS,
        )
        sensor.configure()
        logger.info("Supply INA219 initialised on bus %d", SUPPLY_INA219_BUS)
        return sensor
    except INA219Error as exc:
        logger.error("Failed to initialise supply INA219: %s", exc)
        return None
    except OSError as exc:
        logger.error("I2C error while initialising supply INA219: %s", exc)
        return None


def _init_battery_sensor():
    try:
        sensor = ina219.INA219(
            BATTERY_SHUNT_RESISTANCE,
            busnum=BATTERY_INA219_BUS,
            address=ina219.INA219_DEFAULT_ADDRESS,
        )
        sensor.configure()
        logger.info("Battery INA219 initialised on bus %d", BATTERY_INA219_BUS)
        return sensor
    except INA219Error as exc:
        logger.error("Failed to initialise battery INA219: %s", exc)
        return None
    except OSError as exc:
        logger.error("I2C error while initialising battery INA219: %s", exc)
        return None


def _read_supply(supply_sensor):
    if supply_sensor is None:
        logger.error("Supply INA219 not initialised; skipping read.")
        return None, None
    try:
        voltage = supply_sensor.voltage()
        current = supply_sensor.current()
        return voltage, current
    except INA219Error as exc:
        logger.error("INA219Error reading supply: %s", exc)
        return None, None
    except OSError as exc:
        logger.error("I2C error reading supply: %s", exc)
        return None, None


def _read_battery(battery_sensor):
    if battery_sensor is None:
        logger.error("Battery INA219 not initialised; skipping read.")
        return None, None
    try:
        voltage = battery_sensor.voltage()
        current = battery_sensor.current()
        return voltage, current
    except INA219Error as exc:
        logger.error("INA219Error reading battery: %s", exc)
        return None, None
    except OSError as exc:
        logger.error("I2C error reading battery: %s", exc)
        return None, None


def _read_ups():
    try:
        import ups_rpi
    except ImportError:
        logger.error("ups_rpi module not available; skipping UPS read.")
        return None, None, None, None
    try:
        proc_v = ups_rpi.get_processor_voltage_mv()
        port_v = ups_rpi.get_battery_port_voltage_mv()
        temp_c = ups_rpi.get_battery_temperature_c()
        cap_pct = ups_rpi.get_battery_capacity_pct()
        return proc_v, port_v, temp_c, cap_pct
    except AttributeError as exc:
        logger.error("ups_rpi API mismatch: %s", exc)
        return None, None, None, None
    except Exception as exc:
        logger.error("Error reading UPS data: %s", exc)
        return None, None, None, None


def _print_supply(voltage, current):
    if voltage is not None and current is not None:
        print(f"Supply: {voltage:.3f} V, {current:.3f} mA")


def _print_battery(voltage, current):
    if voltage is not None and current is not None:
        print(f"Battery: {voltage:.3f} V, {current:.3f} mA")


def _print_ups(proc_v, port_v, temp_c, cap_pct):
    if proc_v is not None and port_v is not None and temp_c is not None and cap_pct is not None:
        print(f"UPS: Proc {proc_v}mV, Battery Port {port_v}mV, Temp {temp_c}C, Capacity {cap_pct}%")


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    supply_sensor = _init_supply_sensor()
    battery_sensor = _init_battery_sensor()

    logger.info("Starting monitoring loop (2 s interval).")
    while running:
        supply_v, supply_i = _read_supply(supply_sensor)
        _print_supply(supply_v, supply_i)

        battery_v, battery_i = _read_battery(battery_sensor)
        _print_battery(battery_v, battery_i)

        proc_v, port_v, temp_c, cap_pct = _read_ups()
        _print_ups(proc_v, port_v, temp_c, cap_pct)

        for _ in range(20):
            if not running:
                break
            time.sleep(0.1)

    logger.info("Exited monitoring loop cleanly.")


if __name__ == "__main__":
    main()

