import time
import signal
import sys
import logging
import urllib.request
import urllib.error
from datetime import datetime

import adafruit_dht
from board import D4

# --- Configuration -----------------------------------------------------------
DHT_PIN = D4
THING_SPEAK_CHANNEL_ID = "1234567"
THING_SPEAK_API_KEY = "YOUR_API_KEY"
TEMPERATURE_LOG_FILE = "temperature.txt"
ERROR_LOG_FILE = "error.log"
READ_INTERVAL_SECONDS = 60
READ_TIMEOUT_SECONDS = 2

# --- Globals -----------------------------------------------------------------
_running = True
_sensor = None
_temp_fh = None
_err_fh = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _log_error(message):
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    line = f"{ts}, {message}\n"
    if _err_fh:
        try:
            _err_fh.write(line)
            _err_fh.flush()
        except OSError as exc:
            print(f"Error writing to error log: {exc}", file=sys.stderr)
    print(line, end="")


def _log_temperature(temperature):
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    line = f"{ts}, Temperature: {temperature:.2f} C\n"
    if _temp_fh:
        try:
            _temp_fh.write(line)
            _temp_fh.flush()
        except OSError as exc:
            _log_error(f"Error writing to temperature log: {exc}")
    print(line, end="")


def _upload_to_thingspeak(temperature):
    url = (
        f"https://api.thingspeak.com/update"
        f"?api_key={THING_SPEAK_API_KEY}"
        f"&channel_id={THING_SPEAK_CHANNEL_ID}"
        f"&field1={temperature:.2f}"
    )
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            body = resp.read().decode("utf-8", errors="replace").strip()
            if resp.status != 200:
                _log_error(f"Thingspeak HTTP {resp.status}: {body}")
            else:
                print(f"Data sent to Thingspeak: {body}")
    except urllib.error.URLError as exc:
        _log_error(f"Network error uploading to Thingspeak: {exc}")
    except Exception as exc:
        _log_error(f"Unexpected error uploading to Thingspeak: {exc}")


def _read_sensor():
    global _sensor
    if _sensor is None:
        return None
    try:
        temperature = _sensor.temperature
        if temperature is None:
            return None
        return float(temperature)
    except RuntimeError as exc:
        _log_error(f"DHT22 read error: {exc}")
        return None
    except Exception as exc:
        _log_error(f"Unexpected sensor error: {exc}")
        return None


def _init_sensor():
    global _sensor
    try:
        _sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        print("DHT22 sensor initialized on GPIO4.")
    except Exception as exc:
        _log_error(f"Failed to initialize DHT22 sensor: {exc}")
        _sensor = None


def _open_logs():
    global _temp_fh, _err_fh
    try:
        _temp_fh = open(TEMPERATURE_LOG_FILE, "a", encoding="utf-8")
    except OSError as exc:
        print(f"Failed to open temperature log: {exc}", file=sys.stderr)
    try:
        _err_fh = open(ERROR_LOG_FILE, "a", encoding="utf-8")
    except OSError as exc:
        print(f"Failed to open error log: {exc}", file=sys.stderr)


def _close_logs():
    for fh, name in ((_temp_fh, "temperature"), (_err_fh, "error")):
        if fh:
            try:
                fh.close()
            except OSError:
                pass
    global _temp_fh, _err_fh
    _temp_fh = None
    _err_fh = None


def _cleanup():
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    _close_logs()


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _open_logs()
    _init_sensor()

    try:
        while _running:
            temperature = _read_sensor()
            if temperature is not None:
                _log_temperature(temperature)
                _upload_to_thingspeak(temperature)
            else:
                _log_error("Failed to read temperature from DHT22 sensor.")

            slept = 0
            while _running and slept < READ_INTERVAL_SECONDS:
                time.sleep(1)
                slept += 1
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

