import subprocess
import time
import signal
import sys
import logging

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PIN = 14
PWM_FREQ = 100
INTERVAL = 5
TEMP_STEPS = [40, 50, 60, 70, 80]
SPEED_STEPS = [30, 50, 70, 80, 90, 100]

_running = True


def _handle_signal(signum, frame):
    global _running
    logging.info("Received signal %s, shutting down...", signum)
    _running = False


def get_temp():
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        return float(result.stdout.split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, IndexError, ValueError) as e:
        logging.error("Error reading temperature: %s", e)
        return None


def get_speed(temp):
    if temp is None:
        return None
    for i in range(len(TEMP_STEPS) - 1):
        if TEMP_STEPS[i] <= temp < TEMP_STEPS[i + 1]:
            return SPEED_STEPS[i]
    return SPEED_STEPS[-1]


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    fan = None
    try:
        from gpiozero import PWMOutputDevice
        fan = PWMOutputDevice(PIN, frequency=PWM_FREQ, initial_value=0)
        logging.info("PWM initialized on GPIO%d at %d Hz.", PIN, PWM_FREQ)
    except Exception as e:
        logging.warning("Could not initialize PWM on GPIO%d: %s. Running in degraded mode.", PIN, e)
        fan = None

    last_speed = None

    try:
        while _running:
            temp = get_temp()
            speed = get_speed(temp)

            if speed is not None:
                if fan is not None:
                    try:
                        fan.value = speed / 100.0
                    except Exception as e:
                        logging.error("Failed to set PWM duty cycle: %s", e)
                last_speed = speed
                logging.info("Temperature: %.1f°C, Fan Speed: %d%%", temp, speed)
            else:
                logging.warning("Could not read temperature. Keeping last speed (%s%%).", last_speed)

            for _ in range(INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        if fan is not None:
            try:
                fan.value = 0
                fan.close()
                logging.info("PWM stopped and GPIO released.")
            except Exception as e:
                logging.error("Error during cleanup: %s", e)
        logging.info("Fan control stopped.")


if __name__ == "__main__":
    main()

