import time
import logging
import logging.handlers
import os
import random
import signal
import sys
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

# Constants
DHT_PIN = 4
LOG_FILE = "/var/log/wearable/wearable.log"
LOG_FILE_FALLBACK = os.path.join(os.path.expanduser("~"), ".local", "log", "wearable.log")
LOG_BACKUP_COUNT = 7
LOG_INTERVAL = 5
RETRY_COUNT = 3
RETRY_DELAY = 1

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    global _running
    _running = False


def setup_logging():
    """Configure logging with daily rotation and fallback to user directory."""
    log_dir = os.path.dirname(LOG_FILE)
    if log_dir and not os.path.isdir(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except OSError:
            pass

    handler = logging.handlers.TimedRotatingFileHandler(
        LOG_FILE, when="midnight", interval=1, backupCount=LOG_BACKUP_COUNT
    )
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    handler.setFormatter(formatter)

    logger = logging.getLogger()
    logger.setLevel(logging.INFO)
    logger.addHandler(handler)

    # Fallback to user directory if /var/log/wearable is not writable
    if not os.access(LOG_FILE, os.W_OK):
        fallback_dir = os.path.dirname(LOG_FILE_FALLBACK)
        if fallback_dir and not os.path.isdir(fallback_dir):
            try:
                os.makedirs(fallback_dir, exist_ok=True)
            except OSError:
                pass
        fallback_handler = logging.handlers.TimedRotatingFileHandler(
            LOG_FILE_FALLBACK, when="midnight", interval=1, backupCount=LOG_BACKUP_COUNT
        )
        fallback_handler.setFormatter(formatter)
        logger.addHandler(fallback_handler)
        logging.warning(f"Cannot write to {LOG_FILE}; falling back to {LOG_FILE_FALLBACK}")

    return logger


def setup_gpio():
    """Initialize GPIO if RPi.GPIO is available."""
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in simulation-only mode.")
        return None
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info(f"GPIO initialized on BCM pin {DHT_PIN}.")
        return GPIO
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return None


def read_dht22(gpio):
    """Simulate reading temperature and humidity from a DHT22 sensor.

    Returns:
        tuple: (temperature, humidity) or (None, None) on failure.
    """
    if gpio is not None:
        try:
            # Placeholder: real DHT22 reads via bit-banging on this pin
            pass
        except Exception as e:
            logging.error(f"GPIO read error on pin {DHT_PIN}: {e}")
            return None, None

    temperature = random.uniform(15, 45)
    humidity = random.uniform(40, 95)
    return temperature, humidity


def validate_data(temperature, humidity):
    """Validate temperature and humidity ranges.

    Returns:
        bool: True if valid, False otherwise.
    """
    if not isinstance(temperature, (int, float)) or not isinstance(humidity, (int, float)):
        logging.error("Invalid data type: temperature and humidity must be numeric.")
        return False
    if not (10 <= temperature <= 55):
        logging.error(f"Temperature out of range: {temperature:.2f}°C")
        return False
    if not (20 <= humidity <= 100):
        logging.error(f"Humidity out of range: {humidity:.2f}%")
        return False
    return True


def log_data(temperature, humidity):
    """Log valid temperature and humidity data."""
    logging.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")


def main():
    """Main loop: read, validate, log, retry, and handle shutdown."""
    global _running

    logger = setup_logging()
    gpio = setup_gpio()

    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    logging.info("Wearable environmental monitoring system started.")

    try:
        while _running:
            temperature, humidity = read_dht22(gpio)

            if temperature is None or humidity is None:
                logging.error("Failed to read data from DHT22 sensor.")
                for attempt in range(1, RETRY_COUNT + 1):
                    if not _running:
                        break
                    time.sleep(RETRY_DELAY)
                    temperature, humidity = read_dht22(gpio)
                    if temperature is not None and humidity is not None:
                        break
                else:
                    logging.error("Failed to read data after multiple retries.")
                    time.sleep(LOG_INTERVAL)
                    continue

            if validate_data(temperature, humidity):
                log_data(temperature, humidity)
            else:
                logging.error("Invalid data received from DHT22 sensor.")

            # Sleep in small increments to allow signal handling
            for _ in range(LOG_INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    except OSError as e:
        logging.error(f"OS error: {e}")
    except TypeError as e:
        logging.error(f"Type error: {e}")
    except ValueError as e:
        logging.error(f"Value error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Wearable environmental monitoring system stopped.")
        for handler in logger.handlers:
            handler.close()
            logger.removeHandler(handler)
        if gpio is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass


if __name__ == "__main__":
    main()

