import time
import sys
import signal

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

LED_PIN = 17
led_state = False
_running = True


def cleanup_gpio(signum=None, frame=None):
    """Drive the LED low and release GPIO resources on exit."""
    global _running
    _running = False
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        print("\nExiting program.")
        sys.exit(0)


def main():
    global led_state

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    try:
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error: Failed to initialize GPIO{LED_PIN}: {e}")
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup_gpio)
    signal.signal(signal.SIGTERM, cleanup_gpio)

    print("LED control started. Press Ctrl+C to exit.")

    try:
        while _running:
            try:
                user_input = input("Enter 'on', 'off', or 'exit': ").strip().lower()
            except EOFError:
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
                print(f"LED is now: {led_state}")
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
                print(f"LED is now: {led_state}")
            elif user_input == "exit":
                break
            else:
                print("Invalid input")

            time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

