    except Exception as exc:
        print(f"Error in main loop: {exc}", file=sys.stderr)
    finally:
        for sid, dev in sensors.items():
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


