import sys
import time
import signal
import threading
import traceback
from typing import Callable, Dict, List, Optional

try:
    import DOG
except ImportError:
    print("Error: The 'DOG' library is required. Please ensure it is installed.", file=sys.stderr)
    sys.exit(1)

# Global state
api_started = False
api_thread: Optional[threading.Thread] = None
api_stop_event = threading.Event()
log_file_name: Optional[str] = None
log_file_lock = threading.Lock()

# Thread-safe flag to prevent multiple threads from starting the API simultaneously
api_start_lock = threading.Lock()


def log_data(data: str) -> None:
    """Appends the given data to the log file with a newline, thread-safe."""
    global log_file_name
    if not log_file_name:
        print("Error: Log file not specified. Use 'start <filename>' first.", file=sys.stderr)
        return
    try:
        with log_file_lock:
            with open(log_file_name, 'a', encoding='utf-8') as f:
                f.write(data + '\n')
    except IOError as e:
        print(f"Error writing to log file '{log_file_name}': {e}", file=sys.stderr)


def receive_data() -> None:
    """Continuously receives data from DOG and logs it to the file."""
    global api_started
    try:
        while not api_stop_event.is_set():
            try:
                data = DOG.receive()
                if data:
                    log_data(str(data))
            except Exception as e:
                print(f"Error receiving data: {e}", file=sys.stderr)
                time.sleep(0.1)
                continue
            time.sleep(0.1)
    except Exception as e:
        print(f"Fatal error in receive thread: {e}", file=sys.stderr)
        traceback.print_exc()
    finally:
        api_started = False
        api_stop_event.clear()


def start_api(filename: str) -> None:
    """Starts the DOG API and the data reception thread."""
    global api_started, api_thread, log_file_name
    with api_start_lock:
        if api_started:
            print("API is already running.")
            return
        try:
            DOG.api()
            api_started = True
            log_file_name = filename
            api_stop_event.clear()
            api_thread = threading.Thread(target=receive_data, daemon=True)
            api_thread.start()
            print(f"API started and logging to '{filename}'.")
        except Exception as e:
            print(f"Error starting API: {e}", file=sys.stderr)
            api_started = False
            log_file_name = None


def stop_api() -> None:
    """Stops the DOG API and the data reception thread."""
    global api_started, api_thread, log_file_name
    if not api_started:
        print("API is not running.")
        return
    try:
        api_stop_event.set()
        if api_thread is not None and api_thread.is_alive():
            api_thread.join(timeout=2.0)
            if api_thread.is_alive():
                print("Warning: receive thread did not stop cleanly.", file=sys.stderr)
        api_started = False
        api_thread = None
        log_file_name = None
        print("API stopped.")
    except Exception as e:
        print(f"Error stopping API: {e}", file=sys.stderr)


def display_log() -> None:
    """Displays the contents of the log file."""
    global log_file_name
    if not log_file_name:
        print("Error: Log file not specified. Use 'start <filename>' first.", file=sys.stderr)
        return
    try:
        with open(log_file_name, 'r', encoding='utf-8') as f:
            print(f.read())
    except IOError as e:
        print(f"Error reading log file '{log_file_name}': {e}", file=sys.stderr)


def send_data(data: str) -> None:
    """Sends data using DOG.send()."""
    if not api_started:
        print("Error: API is not running. Start it with 'start <filename>'.", file=sys.stderr)
        return
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}", file=sys.stderr)


def write_to_log(data: str) -> None:
    """Writes data directly to the log file."""
    log_data(data)
    print(f"Wrote to log: {data}")


def cleanup(signum: Optional[int] = None, frame=None) -> None:
    """Signal handler and cleanup routine to ensure API is stopped on exit."""
    global api_started
    if api_started:
        print("\nShutting down...")
        stop_api()
    if signum is not None:
        sys.exit(0)


def help_command(command: Optional[str] = None) -> None:
    """Displays help information for commands."""
    help_messages: Dict[str, str] = {
        "help": "Displays help information. Usage: help [command]",
        "start": "Starts the API and logging. Usage: start <filename>",
        "stop": "Stops the API and logging.",
        "display": "Displays the contents of the log file.",
        "send": "Sends data using DOG.send(). Usage: send <data>",
        "write": "Writes data directly to the log file. Usage: write <data>",
        "exit": "Exits the program.",
    }
    if command:
        msg = help_messages.get(command)
        if msg:
            print(msg)
        else:
            print(f"No help found for '{command}'.")
    else:
        for cmd, msg in help_messages.items():
            print(f"{cmd}: {msg}")


def run_command(command: str, args: List[str]) -> None:
    """Executes the given command with arguments."""
    command_handlers: Dict[str, Callable[..., None]] = {
        "help": help_command,
        "start": lambda filename: start_api(filename),
        "stop": stop_api,
        "display": display_log,
        "send": lambda data: send_data(" ".join(args)),
        "write": lambda data: write_to_log(" ".join(args)),
        "exit": lambda: (stop_api(), sys.exit(0)),
    }
    handler = command_handlers.get(command)
    if handler:
        try:
            handler(*args)
        except TypeError:
            print(f"Usage error for '{command}'.", file=sys.stderr)
            help_command(command)
    else:
        print(f"Unknown command: {command}.", file=sys.stderr)
        help_command()


def main() -> None:
    """Main function to run the DOG API and command-line interface."""
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    print("Starting DOG API...")
    try:
        DOG.start()
    except Exception as e:
        print(f"Error starting DOG: {e}", file=sys.stderr)
        sys.exit(1)

    while True:
        try:
            user_input = input("JAYES@ROVER53:\t")
            parts = user_input.split()
            if not parts:
                continue
            command = parts[0].lower()
            args = parts[1:]
            run_command(command, args)
        except EOFError:
            print("\nEOF received. Exiting.")
            break
        except Exception as e:
            print(f"An unexpected error occurred: {e}", file=sys.stderr)
            traceback.print_exc()


if __name__ == "__main__":
    main()

