import asyncio
import json
import logging
import signal
import sys
import time
from typing import Optional, Dict, Any, List

import numpy as np
import sounddevice as sd
import torch
from transformers import pipeline

try:
    import gpiozero
except ImportError:
    gpiozero = None

try:
    import requests
except ImportError:
    requests = None

try:
    import tflite_runtime.interpreter as tflite
except ImportError:
    tflite = None

CONFIG_FILE = "config.json"
DEFAULT_CONFIG: Dict[str, Any] = {
    "sampling_rate": 16000,
    "sensitivity": 0.5,
    "keywords": ["happy", "sad", "angry"],
    "positive_threshold": 0.7,
    "negative_threshold": -0.7,
    "led_pin": 17,
    "heartbeat_interval": 60,
    "resource_monitor_interval": 60,
    "config_update_interval": 300,
    "cloud_endpoint": None,
    "tflite_model_path": "model.tflite",
    "sentiment_model_path": "distilbert-base-uncased-finetuned-sst-2-english",
}

logger = logging.getLogger(__name__)


class ConfigManager:
    def __init__(self, config_file: str = CONFIG_FILE):
        self.config_file = config_file
        self.config: Dict[str, Any] = {}
        self.load_config()

    def load_config(self) -> None:
        try:
            with open(self.config_file, "r") as f:
                self.config = json.load(f)
            logger.info("Configuration loaded from %s", self.config_file)
        except FileNotFoundError:
            logger.warning("Configuration file not found. Using default configuration.")
            self.config = dict(DEFAULT_CONFIG)
        except json.JSONDecodeError as e:
            logger.error("Invalid JSON in configuration file: %s. Using defaults.", e)
            self.config = dict(DEFAULT_CONFIG)

    def get(self, key: str, default: Any = None) -> Any:
        return self.config.get(key, default)

    def update_config(self, new_config: Dict[str, Any]) -> None:
        self.config.update(new_config)
        self.save_config()

    def save_config(self) -> None:
        try:
            with open(self.config_file, "w") as f:
                json.dump(self.config, f, indent=4)
            logger.info("Configuration saved to %s", self.config_file)
        except IOError as e:
            logger.error("Error saving configuration: %s", e)


class AudioProcessor:
    def __init__(self, config: ConfigManager):
        self.config = config
        self.sampling_rate = config.get("sampling_rate", DEFAULT_CONFIG["sampling_rate"])
        self.sensitivity = config.get("sensitivity", DEFAULT_CONFIG["sensitivity"])
        self.keywords = config.get("keywords", DEFAULT_CONFIG["keywords"])
        self.positive_threshold = config.get("positive_threshold", DEFAULT_CONFIG["positive_threshold"])
        self.negative_threshold = config.get("negative_threshold", DEFAULT_CONFIG["negative_threshold"])
        self.tflite_model_path = config.get("tflite_model_path", DEFAULT_CONFIG["tflite_model_path"])
        self.sentiment_model_path = config.get("sentiment_model_path", DEFAULT_CONFIG["sentiment_model_path"])

        self.interpreter: Optional[Any] = None
        self.input_details: Optional[List[Dict[str, Any]]] = None
        self.output_details: Optional[List[Dict[str, Any]]] = None
        self.sentiment_pipeline: Optional[Any] = None
        self._initialize_tflite()
        self._initialize_sentiment()

    def _initialize_tflite(self) -> None:
        if tflite is None:
            logger.warning("tflite_runtime not installed. Keyword spotting disabled.")
            return
        try:
            self.interpreter = tflite.Interpreter(model_path=self.tflite_model_path)
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            logger.info("TensorFlow Lite interpreter initialized.")
        except Exception as e:
            logger.error("Error initializing TensorFlow Lite interpreter: %s", e)
            self.interpreter = None

