import time
import sys

try:
    import RPi.GPIO as GPIO
    _GPIO_AVAILABLE = True
except ImportError:
    _GPIO_AVAILABLE = False

# --- Sentiment lexicon (VADER style, simplified) ---
vader_lexicon = {
    "excellent": 0.9, "great": 0.8, "good": 0.6, "bad": -0.6,
    "terrible": -0.8, "awful": -0.9, "love": 0.7, "hate": -0.7,
    "fun": 0.5, "boring": -0.5, "happy": 0.4, "sad": -0.4,
    "yes": 0.3, "no": -0.3, "maybe": 0.1, "i": 0.0,
    "me": 0.0, "is": 0.0, "it": 0.0, "that": 0.0,
}

# --- GPIO configuration (BCM numbering) ---
LED_GREEN_PIN = 17
LED_RED_PIN = 18

_initialized = False


def _setup_gpio():
    """Initialize GPIO pins for LEDs. Returns True on success."""
    global _initialized
    if not _GPIO_AVAILABLE:
        print("Warning: RPi.GPIO not available; running in simulation mode.", file=sys.stderr)
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_GREEN_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(LED_RED_PIN, GPIO.OUT, initial=GPIO.LOW)
        _initialized = True
        return True
    except Exception as e:
        print(f"Warning: GPIO setup failed ({e}); running in simulation mode.", file=sys.stderr)
        _initialized = False
        return False


def _cleanup_gpio():
    """Turn off LEDs and release GPIO resources."""
    global _initialized
    if _initialized:
        try:
            GPIO.output(LED_GREEN_PIN, GPIO.LOW)
            GPIO.output(LED_RED_PIN, GPIO.LOW)
            GPIO.cleanup()
        except Exception:
            pass
        _initialized = False


def analyze_sentiment(text):
    """Return sentiment score and classification for a given text."""
    tokens = text.lower().split()
    if not tokens:
        return 0.0, "Neutral"
    scores = [vader_lexicon.get(token, 0.0) for token in tokens]
    avg_score = sum(scores) / len(scores)
    if avg_score > 0.2:
        return avg_score, "Positive"
    elif avg_score < -0.2:
        return avg_score, "Negative"
    else:
        return avg_score, "Neutral"


def main():
    """Main entry point: prompt user, analyze sentiment, light LED."""
    _setup_gpio()
    try:
        user_input = input("Enter a sentence: ").strip()
        if not user_input:
            print("No input received.")
            return
        score, label = analyze_sentiment(user_input)
        print(f"Sentiment: {label} (score: {score:.2f})")
        if label == "Positive":
            pin = LED_GREEN_PIN
        elif label == "Negative":
            pin = LED_RED_PIN
        else:
            pin = None
        if pin is not None:
            try:
                GPIO.output(pin, GPIO.HIGH)
                time.sleep(2)
                GPIO.output(pin, GPIO.LOW)
            except Exception:
                pass
    finally:
        _cleanup_gpio()


if __name__ == "__main__":
    main()

