import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the two TCRT5000 infrared line sensors (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Number of readings to collect and time between readings (seconds)
NUM_READINGS = 10
READING_INTERVAL = 0.5


def setup_gpio():
    """Configure GPIO mode and sensor pins as inputs with pull-down resistors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)


def read_sensor(pin):
    """Read a single TCRT5000 sensor and return 0 (black line) or 1 (white surface)."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on GPIO {pin}: {e}", file=sys.stderr)
        return None


def determine_direction(left_val, right_val):
    """Return a steering direction string based on the two sensor readings."""
    if left_val is None or right_val is None:
        return "error"
    if left_val == 0 and right_val == 0:
        return "forward"
    if left_val == 1 and right_val == 0:
        return "turn-left"
    if left_val == 0 and right_val == 1:
        return "turn-right"
    return "search"


def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup warning: {e}", file=sys.stderr)


def main():
    setup_gpio()
    try:
        for i in range(NUM_READINGS):
            left_reading = read_sensor(LEFT_SENSOR_PIN)
            right_reading = read_sensor(RIGHT_SENSOR_PIN)

            direction = determine_direction(left_reading, right_reading)

            if left_reading is not None and right_reading is not None:
                print(f"Reading {i + 1}/{NUM_READINGS}: "
                      f"Left={left_reading} Right={right_reading} -> {direction}")
            else:
                print(f"Reading {i + 1}/{NUM_READINGS}: "
                      f"Sensor read error -> {direction}")

            time.sleep(READING_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

