import socket
import logging
import signal
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

HOST = '0.0.0.0'
PORT = 9100
BACKLOG = 1
RECV_BUF = 64
BACKLIGHT_PIN = 24

try:
    import gpiozero
    from gpiozero import OutputDevice
except ImportError:
    logging.error("gpiozero is required. Install with: pip install gpiozero")
    sys.exit(1)

server_socket = None
backlight = None
running = True


def cleanup(signum=None, frame=None):
    global server_socket, backlight, running
    running = False
    logging.info("Shutting down...")
    if server_socket is not None:
        try:
            server_socket.close()
            logging.info("Socket closed.")
        except Exception as e:
            logging.error(f"Error closing socket: {e}")
        server_socket = None
    if backlight is not None:
        try:
            backlight.close()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")
        backlight = None
    if signum is not None:
        sys.exit(0)


def handle_client(conn):
    global backlight
    with conn:
        logging.info(f"Connected by {conn.getpeername()}")
        while running:
            try:
                data = conn.recv(RECV_BUF)
                if not data:
                    logging.info("Client disconnected.")
                    break
                command = data.decode('utf-8').strip().lower()
                logging.info(f"Received command: {command}")
                if command == 'on':
                    backlight.on()
                    conn.sendall(b'backlight on\n')
                elif command == 'off':
                    backlight.off()
                    conn.sendall(b'backlight off\n')
                else:
                    conn.sendall(b'unknown command\n')
            except socket.timeout:
                continue
            except Exception as e:
                logging.error(f"Error handling client: {e}")
                break


def main():
    global server_socket, backlight
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((HOST, PORT))
        server_socket.listen(BACKLOG)
        server_socket.settimeout(5.0)
        logging.info(f"Listening on {HOST}:{PORT}")
    except Exception as e:
        logging.error(f"Failed to initialize server: {e}")
        cleanup()
        return

    try:
        backlight = OutputDevice(BACKLIGHT_PIN, active_high=True, initial_value=False)
        logging.info(f"Backlight GPIO {BACKLIGHT_PIN} initialized (OFF).")
    except Exception as e:
        logging.error(f"Failed to initialize GPIO {BACKLIGHT_PIN}: {e}")
        cleanup()
        return

    try:
        while running:
            try:
                conn, addr = server_socket.accept()
                handle_client(conn)
            except socket.timeout:
                continue
            except Exception as e:
                if running:
                    logging.error(f"Accept error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

