import sys
import signal
import RPi.GPIO as GPIO

PWM_PIN = 12
PWM_FREQ = 25000

_running = True
_pwm = None


def _cleanup():
    """Stop PWM and release GPIO resources."""
    global _pwm
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def _set_speed(speed_percent):
    """Update the PWM duty cycle to the given percentage (0-100)."""
    global _pwm
    if _pwm is None:
        return
    try:
        _pwm.ChangeDutyCycle(float(speed_percent))
    except Exception as e:
        print(f"Error setting duty cycle: {e}", file=sys.stderr)


def main():
    global _pwm, _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(PWM_PIN, GPIO.OUT)

    # Attempt hardware PWM; fall back to software PWM if unavailable.
    try:
        _pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
        _pwm.start(0)
        print(f"Hardware PWM initialized on GPIO{PWM_PIN} at {PWM_FREQ} Hz.")
    except Exception as e:
        print(f"Hardware PWM unavailable ({e}); falling back to software PWM.", file=sys.stderr)
        try:
            GPIO.setup(PWM_PIN, GPIO.OUT)
            _pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
            _pwm.start(0)
        except Exception as e2:
            print(f"Failed to initialize software PWM: {e2}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    print("Fan control ready. Enter a speed 0-100 (Ctrl+C or 'q' to quit).")

    try:
        while _running:
            try:
                raw = input("Enter fan speed (0-100): ").strip()
            except EOFError:
                break

            if raw.lower() == "q":
                break

            try:
                speed = float(raw)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100.")
                continue

            if not (0 <= speed <= 100):
                print("Speed out of range. Please enter a value between 0 and 100.")
                continue

            _set_speed(speed)
            print(f"Fan speed set to {speed:.1f}%")
    finally:
        _cleanup()
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

