import signal
import socket
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    raise

LED_PIN = 18
HOST = '0.0.0.0'
PORT = 8000

led = None
httpd = None
running = True


def cleanup(signum=None, frame=None):
    """Release resources and stop the server on exit or signal."""
    global led, httpd, running
    running = False
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
    else:
        print("Cleanup complete.")


class LEDRequestHandler(BaseHTTPRequestHandler):
    """HTTP request handler for LED control."""

    def do_GET(self):
        """Handle GET requests to /led/on and /led/off."""
        try:
            if self.path == '/led/on':
                led.on()
                self._respond(200, 'LED is ON')
            elif self.path == '/led/off':
                led.off()
                self._respond(200, 'LED is OFF')
            else:
                self._respond(404, 'Not Found')
        except Exception as e:
            print(f"Error processing request: {e}")
            self._respond(500, 'Internal Server Error')

    def _respond(self, status_code, message):
        """Send an HTTP response with the given status and message body."""
        self.send_response(status_code)
        self.send_header('Content-type', 'text/plain')
        self.end_headers()
        self.wfile.write(message.encode('utf-8'))

    def log_message(self, format, *args):
        """Suppress default stderr logging; print to stdout instead."""
        print(f"{self.client_address[0]} - {format % args}")


def main():
    global led, httpd

    # Initialize LED
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO{LED_PIN}: {e}")
        return
    except Exception as e:
        print(f"Unexpected error initializing GPIO{LED_PIN}: {e}")
        return

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Create HTTP server
    try:
        httpd = HTTPServer((HOST, PORT), LEDRequestHandler)
        print(f"Server started on {HOST}:{PORT}")
        print("Routes: GET /led/on  -> LED ON,  GET /led/off -> LED OFF")
        httpd.serve_forever()
    except OSError as e:
        print(f"Socket error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == '__main__':
    main()

