import signal
import sys
import time

import smbus2

I2C_BUS = 1
BH1750_ADDR = 0x23
READ_DELAY_S = 1.0

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def _init_bus():
    try:
        return smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        return None
    except PermissionError:
        print("Error: Permission denied opening /dev/i2c-1. Run as root or add user to the 'i2c' group.", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: Failed to open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        return None


def _read_lux(bus):
    try:
        raw = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
    except OSError as exc:
        print(f"Warning: I2C read error (sensor may be absent or bus fault): {exc}", file=sys.stderr)
        return None
    if len(raw) < 2:
        print("Warning: Short read from BH1750 — sensor not responding.", file=sys.stderr)
        return None
    return (raw[0] << 8 | raw[1]) / 1.2


def main():
    signal.signal(signal.SIGINT, _handle_sigint)

    bus = _init_bus()
    if bus is None:
        sys.exit(1)

    print(f"BH1750 light sensor monitoring on I2C bus {I2C_BUS} @ 0x{BH1750_ADDR:02X}. Press Ctrl+C to stop.")

    try:
        while _running:
            lux = _read_lux(bus)
            if lux is not None:
                print(f"Light Intensity: {lux:.2f} lux")
            time.sleep(READ_DELAY_S)
    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

