    except OSError as exc:
        print(f"Warning: I2C read error (sensor may be absent or bus fault): {exc}", file=sys.stderr)
        return None
    if len(raw) < 2:
        print("Warning: Short read from BH1750 — sensor not responding.", file=sys.stderr)
        return None
    return (raw[0] << 8 | raw[1]) / 1.2


def main():
    signal.signal(signal.SIGINT, _handle_sigint)

    bus = _init_bus()
    if bus is None:
        sys.exit(1)

    print(f"BH1750 light sensor monitoring on I2C bus {I2C_BUS} @ 0x{BH1750_ADDR:02X}. Press Ctrl+C to stop.")

    try:
        while _running:
            lux = _read_lux(bus)
            if lux is not None:
                print(f"Light Intensity: {lux:.2f} lux")
            time.sleep(READ_DELAY_S)
    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

