import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO can only be run on a Raspberry Pi.")
    sys.exit(1)

# Define the GPIO pin connected to the LED (BCM numbering)
LED_PIN = 17

# Global flag to indicate whether the program should continue running
running = True

def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    print("\nCtrl+C detected. Exiting gracefully...")
    running = False

def setup_gpio():
    """Initialize GPIO settings and set the LED pin as an output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)

def turn_led_on():
    """Turn the LED on."""
    try:
        GPIO.output(LED_PIN, GPIO.HIGH)
    except Exception as e:
        print(f"Error turning LED on: {e}")
        raise

def turn_led_off():
    """Turn the LED off."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Error turning LED off: {e}")
        raise

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")

def main():
    """Main function to control the LED blinking."""
    global running

    # Register the signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    setup_gpio()

    try:
        while running:
            turn_led_on()
            time.sleep(2)
            if not running:
                break
            turn_led_off()
            time.sleep(2)
    except Exception as e:
        print(f"An error occurred during execution: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

