#!/usr/bin/env python3
"""
LED Blink Program for Raspberry Pi 3 Model B+

Blinks an LED on GPIO17 (BCM) at 1 Hz using gpiozero.
Handles missing libraries, non-Pi platforms, permission errors,
and missing pin factories cleanly with clear status messages.
"""

import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero library not found. Install with: sudo apt install python3-gpiozero")
    sys.exit(0)

LED_PIN = 17
BLINK_INTERVAL = 1.0  # seconds


def main() -> None:
    """Blink the LED on GPIO17 at 1 Hz until interrupted."""
    led = None
    try:
        led = LED(LED_PIN)
    except BadPinFactory:
        print("Error: No usable pin factory detected. This program must run on a Raspberry Pi.")
        sys.exit(0)
    except GPIOZeroError as exc:
        print(f"Error: Failed to initialize GPIO pin {LED_PIN}: {exc}")
        sys.exit(0)
    except Exception as exc:
        print(f"Error: Unexpected failure initializing GPIO pin {LED_PIN}: {exc}")
        sys.exit(0)

    try:
        while True:
            led.on()
