import logging
import signal
import time
from datetime import datetime

import RPi.GPIO as GPIO

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class MotionCounter:
    """Count debounced PIR motion events and report per-minute totals."""

    def __init__(
        self,
        pin: int = 23,
        debounce_ms: int = 200,
        tally_interval: int = 10,
        run_duration: int = 60,
        sensor_absent_timeout: int = 30,
    ):
        self.pin = pin
        self.debounce_ms = debounce_ms
        self.tally_interval = tally_interval
        self.run_duration = run_duration
        self.sensor_absent_timeout = sensor_absent_timeout
        self.motion_count = 0
        self.last_motion_time = 0.0
        self.last_tally_time = 0.0
        self.sensor_absent = False
        self._running = True

    def setup_gpio(self) -> None:
        """Configure BCM mode and the PIR input pin with pull-down."""
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logging.info("GPIO setup complete: pin %d as input (pull-down).", self.pin)

    def _read_sensor(self) -> bool:
        """Return True if the PIR pin currently reads HIGH."""
        try:
            return bool(GPIO.input(self.pin))
        except Exception as exc:
            logging.error("GPIO read error on pin %d: %s", self.pin, exc)
            return False

    def detect_motion(self) -> bool:
        """Return True when a debounced motion event is detected."""
        if not self._running:
            return False
        if self.sensor_absent:
            return False
        if not self._read_sensor():
            return False
        now = time.time()
        if (now - self.last_motion_time) * 1000 < self.debounce_ms:
            return False
        self.last_motion_time = now
        self.motion_count += 1
        logging.debug("Motion detected (total: %d).", self.motion_count)
        return True

    def check_sensor_absence(self) -> None:
        """Flag the sensor as absent if no signal is seen for the timeout window."""
        if self._read_sensor():
            self.last_motion_time = time.time()
            self.sensor_absent = False
        elif (time.time() - self.last_motion_time) > self.sensor_absent_timeout:
            self.sensor_absent = True
            logging.warning(
                "No motion signal for %d s; sensor may be absent or disconnected.",
                self.sensor_absent_timeout,
            )

    def print_tally(self) -> None:
        """Print the current motion count and reset it for the next interval."""
        logging.info(
            "Motion tally: %d visitor(s) detected so far.",
            self.motion_count,
        )
        self.motion_count = 0

    def run(self) -> None:
        """Main monitoring loop; exits cleanly after run_duration seconds."""
        self.setup_gpio()
        self.last_tally_time = time.time()
        self.last_motion_time = time.time()
        logging.info("Monitoring started for %d seconds (Ctrl+C to stop).", self.run_duration)

        try:
            while self._running and (time.time() - self.last_tally_time) < self.run_duration:
                self.check_sensor_absence()
                if self.detect_motion():
                    logging.info("Visitor detected at %s", datetime.now().strftime("%H:%M:%S"))
                if (time.time() - self.last_tally_time) >= self.tally_interval:
                    self.print_tally()
                    self.last_tally_time = time.time()
                time.sleep(0.05)
        except Exception as exc:
            logging.error("Unexpected error in monitoring loop: %s", exc)
        finally:
            self.cleanup()

    def stop(self, signum=None, frame=None) -> None:
        """Signal handler / external stop request."""
        logging.info("Stop requested (signal %s).", signum)
        self._running = False

    def cleanup(self) -> None:
        """Release GPIO resources and report final per-minute tally."""
        try:
            if self.motion_count > 0:
                logging.info(
                    "Final tally before exit: %d visitor(s) in the last minute.",
                    self.motion_count,
                )
            else:
                logging.info("No motion detected in the last minute.")
        except Exception as exc:
            logging.error("Error during final tally: %s", exc)
        try:
            GPIO.cleanup()
            logging.info("GPIO cleanup complete.")
        except Exception as exc:
            logging.error("GPIO cleanup error: %s", exc)


def main() -> None:
    counter = MotionCounter()
    signal.signal(signal.SIGINT, counter.stop)
    signal.signal(signal.SIGTERM, counter.stop)
    counter.run()


if __name__ == "__main__":
    main()

