import time
import logging
import random
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: pip install RPi.GPIO")
    sys.exit(1)

# Configuration
SENSOR_1_PIN = 17
SENSOR_2_PIN = 18
ACTUATORS = ["activate_light", "activate_sound", "activate_motor"]
LOG_FILE = "art_installation.log"
DEBOUNCE_DELAY = 0.1
LOOP_DELAY = 0.05
CONFIRMATION_WINDOW = 0.5

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# Simulated actuator functions
def activate_light():
    print("Activating light")
    logging.info("Light activated")

def activate_sound():
    print("Activating sound")
    logging.info("Sound activated")

def activate_motor():
    print("Activating motor")
    logging.info("Motor activated")

def read_sensor(pin):
    """Reads the state of a PIR sensor. Returns True if idle, False if triggered."""
    try:
        return GPIO.input(pin) == GPIO.HIGH
    except Exception as e:
        logging.error(f"Error reading sensor on pin {pin}: {e}")
        return True  # Treat as idle on error to avoid false positives

def trigger_actuator(actuator_name):
    """Triggers a specific actuator function."""
    try:
        if actuator_name == "activate_light":
            activate_light()
        elif actuator_name == "activate_sound":
            activate_sound()
        elif actuator_name == "activate_motor":
            activate_motor()
        else:
            logging.warning(f"Unknown actuator: {actuator_name}")
    except Exception as e:
        logging.error(f"Error triggering actuator {actuator_name}: {e}")

def main():
    """Main function to run the art installation."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SENSOR_1_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(SENSOR_2_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info("GPIO initialized successfully")
    except RuntimeError as e:
        logging.error(f"GPIO initialization failed: {e}")
        sys.exit(1)
    except Exception as e:
        logging.error(f"Unexpected error during GPIO setup: {e}")
        sys.exit(1)

    try:
        while True:
            sensor1_idle = read_sensor(SENSOR_1_PIN)
            sensor2_idle = read_sensor(SENSOR_2_PIN)

            if not sensor1_idle:
                logging.info(f"Sensor 1 triggered on pin {SENSOR_1_PIN}")
                print("Intrusion Detected - Sensor 1")
                trigger_actuator(random.choice(ACTUATORS))
                time.sleep(DEBOUNCE_DELAY)
            if not sensor2_idle:
                logging.info(f"Sensor 2 triggered on pin {SENSOR_2_PIN}")
                print("Intrusion Detected - Sensor 2")
                trigger_actuator(random.choice(ACTUATORS))
                time.sleep(DEBOUNCE_DELAY)

            if not sensor1_idle and not sensor2_idle:
                logging.warning("Confirmed Intrusion")
                print("Confirmed Intrusion")
                for actuator in ACTUATORS:
                    trigger_actuator(actuator)
                time.sleep(CONFIRMATION_WINDOW)

            time.sleep(LOOP_DELAY)

    except KeyboardInterrupt:
        print("Exiting program")
        logging.info("Program terminated by user")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed")

if __name__ == "__main__":
    main()

