#!/usr/bin/python3
import time
import sys
import atexit
import signal
import logging
from contextlib import suppress

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit-circuitpython-servokit not installed. "
          "Install with: pip3 install adafruit-circuitpython-servokit", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

MIN_PULSE_US = 150
MAX_PULSE_US = 600
SERVO_MIN_ANGLE = -77
SERVO_MAX_ANGLE = 77
DEFAULT_DELAY = 0.029
SHOOT_DELAY = 0.15
PWM_FREQUENCY = 60

CHANNEL_CLAW = 0
CHANNEL_LOCK = 1
CHANNEL_WATER_GUN = 2


class Fuchikoma:
    def __init__(self, pwm_frequency=PWM_FREQUENCY, min_pulse_us=MIN_PULSE_US,
                 max_pulse_us=MAX_PULSE_US, delay=DEFAULT_DELAY):
        self.delay = delay
        self.kit = None
        try:
            self.kit = ServoKit(channels=16, i2c=None)
            self.kit.servo.frequency = pwm_frequency
            self.kit.servo_min_pulse = min_pulse_us / 1000000
            self.kit.servo_max_pulse = max_pulse_us / 1000000
            logger.info("Fuchikoma initialized: %d Hz, %d-%d us pulse",
                        pwm_frequency, min_pulse_us, max_pulse_us)
        except (ValueError, OSError, RuntimeError) as e:
            logger.error("Failed to initialize PCA9685 on I2C bus: %s", e)
            self.kit = None
            raise

    def _validate_channel(self, channel):
        if self.kit is None:
            raise RuntimeError("ServoKit not initialized")
        if not 0 <= channel < 16:
            raise ValueError(f"Invalid channel {channel}; must be 0-15")

    def _validate_angle(self, angle):
        if not SERVO_MIN_ANGLE <= angle <= SERVO_MAX_ANGLE:
            raise ValueError(
                f"Angle {angle} out of range "
                f"[{SERVO_MIN_ANGLE}, {SERVO_MAX_ANGLE}]"
            )

    def move_servo(self, channel, angle):
        self._validate_channel(channel)
        self._validate_angle(angle)
        if self.kit is None:
            raise RuntimeError("ServoKit not initialized")
        try:
            self.kit.servo[channel].angle = angle
            time.sleep(self.delay)
            self.kit.servo[channel].angle = None
        except (ValueError, OSError) as e:
            logger.error("Error moving servo on channel %d: %s", channel, e)
            raise

    def move_claw(self, angle):
        self.move_servo(CHANNEL_CLAW, angle)

    def move_lock(self, angle):
        self.move_servo(CHANNEL_LOCK, angle)

    def move_water_gun(self, angle):
        self.move_servo(CHANNEL_WATER_GUN, angle)

    def bite(self):
        self.move_claw(-75)

    def open_claw(self):
        self.move_claw(75)

    def lock(self):
        self.move_lock(75)

    def unlock(self):
        self.move_lock(-75)

    def shoot(self):
        self.move_water_gun(-75)
        time.sleep(SHOOT_DELAY)
        self.load_water()

    def load_water(self):
        self.move_water_gun(75)

    def cleanup(self):
        if self.kit is None:
            return
        logger.info("Cleaning up PCA9685 channels...")
        for ch in range(16):
            try:
                self.kit.servo[ch].angle = None
            except Exception:
                pass
        self.kit = None
        logger.info("Cleanup complete.")


def main():
    fuchikoma = None
    try:
        fuchikoma = Fuchikoma()
        atexit.register(fuchikoma.cleanup)

        signal.signal(signal.SIGINT, lambda *_: sys.exit(0))
        signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))

        logger.info("Fuchikoma ready. Example: fuchikoma.bite()")
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logger.info("KeyboardInterrupt received, exiting.")
    except Exception as e:
        logger.error("Fatal error: %s", e)
        sys.exit(1)
    finally:
        if fuchikoma is not None:
            fuchikoma.cleanup()


if __name__ == "__main__":
    main()

