#!/usr/bin/env python3
"""
MPU-6050 Gyroscope Data Logger and Anomaly Detector

Hardware: Raspberry Pi 3 Model B+ with MPU-6050 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3).
"""

import argparse
import csv
import json
import logging
import signal
import sys
import time
from collections import deque
from datetime import datetime

import smbus2
from mpu6050 import mpu6050

# Constants
I2C_RETRY_DELAY = 1.0
MAX_I2C_RETRIES = 3
ANOMALY_THRESHOLD = 50.0  # deg/s^2
DEFAULT_SAMPLE_RATE = 10
DEFAULT_WINDOW_SIZE = 5
DEFAULT_LOG_LEVEL = "INFO"

# Global state for signal handling
_running = True
_bus = None
_sensor = None


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="MPU-6050 Gyroscope Data Logger and Anomaly Detector"
    )
    parser.add_argument(
        "--sample_rate", type=int, default=DEFAULT_SAMPLE_RATE,
        help="Sampling rate in Hz (1-50)"
    )
    parser.add_argument(
        "--window_size", type=int, default=DEFAULT_WINDOW_SIZE,
        help="Moving average window size (3-15)"
    )
    parser.add_argument(
        "--log_level", type=str, default=DEFAULT_LOG_LEVEL,
        choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"],
        help="Logging level"
    )
    parser.add_argument(
        "--cloud_enabled", action="store_true",
        help="Enable cloud output (stdout JSON)"
    )
    return parser.parse_args()


def setup_logging(log_level):
    logging.basicConfig(
        level=getattr(logging, log_level.upper(), logging.INFO),
        format="%(asctime)s - %(levelname)s - %(message)s"
    )


def initialize_mpu6050():
    global _bus, _sensor
    for attempt in range(1, MAX_I2C_RETRIES + 1):
        try:
            _bus = smbus2.SMBus(1)
            _sensor = mpu6050(_bus)
            logging.info("MPU-6050 initialized successfully.")
            return True
        except IOError as e:
            logging.error(
                f"I2C error initializing MPU-6050 (attempt {attempt}/{MAX_I2C_RETRIES}): {e}"
            )
            if _bus is not None:
                try:
                    _bus.close()
                except Exception:
                    pass
                _bus = None
            if attempt < MAX_I2C_RETRIES:
                time.sleep(I2C_RETRY_DELAY)
        except Exception as e:
            logging.error(
                f"Unexpected error initializing MPU-6050 (attempt {attempt}/{MAX_I2C_RETRIES}): {e}"
            )
            if _bus is not None:
                try:
                    _bus.close()
                except Exception:
                    pass
                _bus = None
            if attempt < MAX_I2C_RETRIES:
                time.sleep(I2C_RETRY_DELAY)

    logging.critical("Failed to initialize MPU-6050 after multiple retries.")
    return False


def get_gyroscope_data():
    if _sensor is None:
        logging.error("Sensor not initialized.")
        return None, None, None
    try:
        gyro = _sensor.get_rotation()
        return gyro["x"], gyro["y"], gyro["z"]
    except IOError as e:
        logging.error(f"I2C error reading gyroscope data: {e}")
        return None, None, None
    except Exception as e:
        logging.error(f"Unexpected error reading gyroscope data: {e}")
        return None, None, None


def moving_average(data, window_size):
    if not data:
        return 0.0
    window = deque(maxlen=window_size)
    window.extend(data)
    return sum(window) / len(window)


def detect_anomaly(x, y, z, prev_x, prev_y, prev_z):
    if prev_x is None or prev_y is None or prev_z is None:
        return False
    dx = abs(x - prev_x)
    dy = abs(y - prev_y)
    dz = abs(z - prev_z)
    return max(dx, dy, dz) > ANOMALY_THRESHOLD


def log_data(timestamp, x, y, z, fx, fy, fz, anomaly, log_file):
    try:
        writer = csv.writer(log_file)
        writer.writerow([timestamp, x, y, z, fx, fy, fz, anomaly])
    except Exception as e:
        logging.error(f"Error writing to CSV file: {e}")


def output_to_cloud(timestamp, x, y, z, fx, fy, fz, anomaly):
    data = {
        "timestamp": timestamp,
        "raw_x": x, "raw_y": y, "raw_z": z,
        "filtered_x": fx, "filtered_y": fy, "filtered_z": fz,
        "anomaly": anomaly
    }
    print(json.dumps(data), flush=True)


def cleanup(signum=None, frame=None):
    global _running, _bus, _sensor
    _running = False
    logging.info("Cleaning up resources...")
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None
    _sensor = None
    if signum is not None:
        sys.exit(0)


def main():
    global _running
    args = parse_arguments()
    setup_logging(args.log_level)

    if not 1 <= args.sample_rate <= 50:
        logging.error("Invalid sample rate. Must be between 1 and 50 Hz.")
        sys.exit(1)
    if not 3 <= args.window_size <= 15:
        logging.error("Invalid window size. Must be between 3 and 15.")
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    if not initialize_mpu6050():
        sys.exit(1)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    log_filename = f"gyro_data_{timestamp}.csv"
    try:
        with open(log_filename, "w", newline="") as csvfile:
            csv_writer = csv.writer(csvfile)
            csv_writer.writerow([
                "Timestamp", "Raw_X", "Raw_Y", "Raw_Z",
                "Filtered_X", "Filtered_Y", "Filtered_Z", "Anomaly"
            ])

            x_data, y_data, z_data = [], [], []
            prev_x, prev_y, prev_z = None, None, None

            while _running:
                x, y, z = get_gyroscope_data()
                if x is None or y is None or z is None:
                    time.sleep(1.0 / args.sample_rate)
                    continue

                x_data.append(x)
                y_data.append(y)
                z_data.append(z)

                fx = moving_average(x_data, args.window_size)
                fy = moving_average(y_data, args.window_size)
                fz = moving_average(z_data, args.window_size)

                anomaly = detect_anomaly(x, y, z, prev_x, prev_y, prev_z)
                current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")

                log_data(current_time, x, y, z, fx, fy, fz, anomaly, csvfile)
                if args.cloud_enabled:
                    output_to_cloud(current_time, x, y, z, fx, fy, fz, anomaly)

                prev_x, prev_y, prev_z = x, y, z
                time.sleep(1.0 / args.sample_rate)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

