import time
import signal
import sys
import logging
from PIL import Image
import board
import busio
import adafruit_tcs34725

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_color_data(sensor):
    try:
        red, green, blue, clear = sensor.color_rgb_bytes
        return red, green, blue, clear
    except (OSError, ValueError, RuntimeError) as e:
        logging.error("Error reading color data from TCS34725: %s", e)
        return 0, 0, 0, 0

def get_dominant_color(image_path):
    try:
        with Image.open(image_path) as img:
            img = img.resize((100, 100))
            colors = img.getcolors(10000)
            if colors:
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
            return (0, 0, 0)
    except FileNotFoundError:
        logging.error("Image file not found: %s", image_path)
        return (0, 0, 0)
    except (OSError, ValueError, RuntimeError) as e:
        logging.error("Error processing image: %s", e)
        return (0, 0, 0)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = None
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except (OSError, ValueError, RuntimeError) as e:
        logging.error("Failed to initialize I2C bus: %s", e)
        sys.exit(1)

    try:
        sensor = adafruit_tcs34725.TCS34725(i2c_bus, integration_time=50, gain=4)
    except (OSError, ValueError, RuntimeError) as e:
        logging.error("TCS34725 not detected or failed to initialize: %s", e)
        sys.exit(1)

    try:
        while _running:
            red, green, blue, clear = read_color_data(sensor)
            print(f"Sensor - Clear: {clear}, Red: {red}, Green: {green}, Blue: {blue}")

            dominant = get_dominant_color("image.jpg")
            print(f"Dominant Color: {dominant}")

            time.sleep(1)
    finally:
        if i2c_bus is not None:
            try:
                i2c_bus.deinit()
            except Exception:
                pass
        logging.info("Program terminated cleanly.")

if __name__ == "__main__":
    main()

