import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_moisture_level():
    return random.randint(0, 100)

def control_water_pump(moisture, pump_pin):
    if moisture < MOISTURE_THRESHOLD:
        GPIO.output(pump_pin, GPIO.HIGH)
        print(f"Pump ON  (moisture {moisture}% < threshold {MOISTURE_THRESHOLD}%)")
    else:
        GPIO.output(pump_pin, GPIO.LOW)
        print(f"Pump OFF (moisture {moisture}% >= threshold {MOISTURE_THRESHOLD}%)")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup error: {e}")
        sys.exit(1)

    try:
        for i in range(ITERATIONS):
            if not _running:
                break
            moisture = read_moisture_level()
            print(f"Iteration {i + 1}: Moisture = {moisture}%")
            control_water_pump(moisture, PUMP_PIN)
            if i < ITERATIONS - 1 and _running:
                time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        try:
            GPIO.output(PUMP_PIN, GPIO.LOW)
        except Exception:
            pass
        GPIO.cleanup()
        print("GPIO cleanup completed. Exiting.")

if __name__ == "__main__":
    main()

