import smbus
import time
import signal
import sys

# Constants
I2C_BUS = 1
LIS3DH_ADDRESS = 0x18
WHO_AM_I_REGISTER = 0x0F
WHO_AM_I_VALUE = 0x33
CTRL_REG1 = 0x20
CTRL_REG3 = 0x22
CTRL_REG4 = 0x23
OUT_X_L = 0x28
LED_PIN = 21
BUZZER_PIN = 20
X_THRESHOLD_LOW = 0.3
X_THRESHOLD_HIGH = 0.7
SAMPLE_INTERVAL = 0.1
LOOP_INTERVAL = 1.0

# Globals for cleanup
i2c_bus = None
led = None
buzzer = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def init_gpio():
    global led, buzzer
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUZZER_PIN, GPIO.OUT, initial=GPIO.LOW)
        led = GPIO
        buzzer = GPIO
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        raise


def init_i2c():
    global i2c_bus
    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}")
        raise


def init_accelerometer():
    try:
        who_am_i = i2c_bus.read_byte_data(LIS3DH_ADDRESS, WHO_AM_I_REGISTER)
        if who_am_i != WHO_AM_I_VALUE:
            print(f"LIS3DH not found. WHO_AM_I returned 0x{who_am_i:02X}, expected 0x{WHO_AM_I_VALUE:02X}")
            return False
        i2c_bus.write_byte_data(LIS3DH_ADDRESS, CTRL_REG1, 0b01100111)  # Enable all axes, 100 Hz, normal mode
        i2c_bus.write_byte_data(LIS3DH_ADDRESS, CTRL_REG3, 0b00001000)  # LIR_INT1: latched
        i2c_bus.write_byte_data(LIS3DH_ADDRESS, CTRL_REG4, 0b00001000)  # +/- 2g, high resolution
        return True
    except Exception as e:
        print(f"Error initializing accelerometer: {e}")
        return False


def read_acceleration_x():
    try:
        low = i2c_bus.read_byte_data(LIS3DH_ADDRESS, OUT_X_L)
        high = i2c_bus.read_byte_data(LIS3DH_ADDRESS, OUT_X_L + 1)
        raw = (high << 8) | low
        if raw >= 0x8000:
            raw -= 0x10000
        return raw / 256.0
    except Exception as e:
        print(f"Error reading acceleration: {e}")
        return None


def set_led(state):
    if led is not None:
        try:
            led.output(LED_PIN, GPIO.HIGH if state else GPIO.LOW)
        except Exception:
            pass


def set_buzzer(state):
    if buzzer is not None:
        try:
            buzzer.output(BUZZER_PIN, GPIO.HIGH if state else GPIO.LOW)
        except Exception:
            pass


def cleanup():
    set_led(False)
    set_buzzer(False)
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass
    if led is not None:
        try:
            led.cleanup()
        except Exception:
            pass


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        init_gpio()
        init_i2c()
        if not init_accelerometer():
            sys.exit(1)

        last_print_time = 0.0
        while running:
            now = time.monotonic()
            if now - last_print_time >= LOOP_INTERVAL:
                last_print_time = now
                x = read_acceleration_x()
                if x is None:
                    set_led(False)
                    set_buzzer(False)
                    continue

                print(f"Acceleration X: {x:.2f} g")

                if abs(x) > X_THRESHOLD_HIGH:
                    set_buzzer(True)
                elif abs(x) <= X_THRESHOLD_LOW:
                    set_buzzer(False)

                if abs(x) > X_THRESHOLD_LOW:
                    set_led(True)
                else:
                    set_led(False)

            time.sleep(SAMPLE_INTERVAL)

    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        cleanup()
        print("Program exited cleanly.")


if __name__ == "__main__":
    main()

