import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: sudo apt install python3-rpi.gpio")
    sys.exit(1)

LED_PIN = 17
CYCLES = 5
DELAY_SECONDS = 2
LIGHT_THRESHOLD = 50

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio():
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def read_light_level():
    return random.randint(0, 100)

def control_led(light_level):
    if light_level < LIGHT_THRESHOLD:
        GPIO.output(LED_PIN, GPIO.HIGH)
        print(f"LED ON  (light level {light_level}% < {LIGHT_THRESHOLD}%)")
    else:
        GPIO.output(LED_PIN, GPIO.LOW)
        print(f"LED OFF (light level {light_level}% >= {LIGHT_THRESHOLD}%)")

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
        print("Starting ambient light simulation (5 cycles, 2 s interval)...")
        for cycle in range(1, CYCLES + 1):
            if not _running:
                print("\nInterrupted by signal.")
                break

            light_level = read_light_level()
            print(f"Cycle {cycle}/{CYCLES}: Light level = {light_level}%")
            control_led(light_level)

            if cycle < CYCLES and _running:
                time.sleep(DELAY_SECONDS)

        if _running:
            print("Simulation complete.")
        else:
            print("Simulation interrupted.")

    except Exception as e:
        print(f"Error: {e}")
    finally:
        cleanup_gpio()
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

