import signal
import sys
import atexit

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None


class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


class Motor:
    """
    Controls a DC motor via a PWM pin on a Raspberry Pi.

    Args:
        driver: A connected driver library.pi instance (e.g. gpiozero.pwm.PWMOutputDevice).
        pin: BCM pin number connected to the motor driver's PWM input.
    """

    def __init__(self, driver, pin):
        self.driver = driver
        self.pin = pin
        self._closed = False

        if GPIO is not None:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)

        try:
            if not hasattr(self.driver, 'set_frequency') or not hasattr(self.driver, 'set_duty_cycle'):
                raise MotorError(
                    "Driver must expose set_frequency and set_duty_cycle methods."
                )
        except Exception as exc:
            raise MotorError(f"Invalid or disconnected driver: {exc}") from exc

        try:
            self.driver.set_pin(self.pin)
            self.driver.set_frequency(1000)
            self.driver.set_duty_cycle(0)
        except Exception as exc:
            raise MotorError(f"Failed to initialise motor on pin {self.pin}: {exc}") from exc

        atexit.register(self.close)

    def set_frequency(self, freq):
        """
        Sets the PWM frequency in Hz.

        Args:
            freq: Frequency in Hz (must be > 0).

        Raises:
            MotorError: If the driver call fails or freq is invalid.
        """
        if freq <= 0:
            raise MotorError("Frequency must be a positive integer.")
        try:
            self.driver.set_frequency(freq)
        except Exception as exc:
            raise MotorError(f"Failed to set frequency to {freq} Hz: {exc}") from exc

    def set_duty_cycle(self, duty):
        """
        Sets the PWM duty cycle (0-255).

        Args:
            duty: Duty cycle value (0-255).

        Raises:
            MotorError: If the value is out of range or the driver call fails.
        """
        if not isinstance(duty, (int, float)):
            raise MotorError("Duty cycle must be a number.")
        if not 0 <= duty <= 255:
            raise MotorError("Duty cycle must be between 0 and 255.")
        try:
            self.driver.set_duty_cycle(int(duty))
        except Exception as exc:
            raise MotorError(f"Failed to set duty cycle to {duty}: {exc}") from exc

    def stop(self):
        """Stops the motor by setting the duty cycle to 0."""
        if self._closed:
            return
        try:
