import serial
import time
import signal
import sys
from gpiozero import PWMOutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
PWM_FREQUENCY = 50  # Hz
MIN_PULSE_MS = 1.0
MAX_PULSE_MS = 2.0
MIN_ANGLE = 0
MAX_ANGLE = 180
HOLD_SECONDS = 1.0

running = True
pwm = None
ser = None

def signal_handler(signum, frame):
    global running
    running = False

def angle_to_duty_cycle(angle):
    pulse_ms = MIN_PULSE_MS + (angle / 180.0) * (MAX_PULSE_MS - MIN_PULSE_MS)
    return pulse_ms / (1000.0 / PWM_FREQUENCY)

def cleanup():
    global pwm, ser
    if pwm is not None:
        try:
            pwm.close()
        except Exception:
            pass
    if ser is not None and ser.is_open:
        try:
            ser.close()
        except Exception:
            pass

def main():
    global pwm, ser
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)

    try:
        pwm = PWMOutputDevice(SERVO_PIN, frequency=PWM_FREQUENCY)
    except Exception as e:
        print(f"Error initializing PWM on pin {SERVO_PIN}: {e}")
        ser.close()
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                time.sleep(0.5)
                continue

            if not raw:
                continue

            try:
                angle_str = raw.decode('ascii', errors='replace').strip()
                angle = int(angle_str)
            except ValueError:
                print(f"Invalid data received (not an integer): {raw!r}")
                continue

            if not (MIN_ANGLE <= angle <= MAX_ANGLE):
                print(f"Angle {angle} out of range ({MIN_ANGLE}-{MAX_ANGLE})")
                continue

            duty = angle_to_duty_cycle(angle)
            try:
                pwm.value = duty
                time.sleep(HOLD_SECONDS)
                pwm.value = 0
            except Exception as e:
                print(f"PWM error: {e}")
                break
    finally:
        cleanup()

if __name__ == '__main__':
    main()

