import signal
import sys
import logging
from typing import Any, Dict, List, Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ModbusError(Exception):
    pass


class ModbusRTUException(ModbusError):
    pass


class ModbusRTU:
    """
    A class for interacting with Modbus RTU devices over UART on a Raspberry Pi.
    Provides robust error handling and clean resource release.
    """

    def __init__(self, port: str = '/dev/serial0', baudrate: int = 115200, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self._client = None
        self._running = True

        try:
            import minimalmodbus
            self._client = minimalmodbus.Instrument(port, 1)
            self._client.serial.baudrate = baudrate
            self._client.serial.timeout = timeout
            self._client.mode = minimalmodbus.MODE_RTU
            logger.info(f"Modbus RTU client initialized on {port} at {baudrate} baud.")
        except ImportError:
            logger.warning("minimalmodbus library not found. Running in degraded mode.")
        except Exception as e:
            logger.warning(f"Failed to initialize Modbus RTU client on {port}: {e}. Running in degraded mode.")

    def _read_register(self, register_address: int, number_of_decimals: int = 0, functioncode: int = 3) -> Optional[float]:
        if self._client is None:
            logger.warning("Modbus client not initialized. Returning None.")
            return None
        try:
            return self._client.read_register(register_address, number_of_decimals, functioncode)
        except minimalmodbus.NoResponseError as e:
            logger.error(f"No response from device at register {register_address}: {e}")
            return None
        except minimalmodbus.ModbusException as e:
            logger.error(f"Modbus error reading register {register_address}: {e}")
            return None
        except Exception as e:
            logger.error(f"Unexpected error reading register {register_address}: {e}")
            return None

    def _write_register(self, register_address: int, value: float, number_of_decimals: int = 0, functioncode: int = 16) -> bool:
        if self._client is None:
            logger.warning("Modbus client not initialized. Returning False.")
            return False
        try:
            self._client.write_register(register_address, value, number_of_decimals, functioncode)
            return True
        except minimalmodbus.NoResponseError as e:
            logger.error(f"No response from device at register {register_address}: {e}")
            return False
        except minimalmodbus.ModbusException as e:
            logger.error(f"Modbus error writing to register {register_address}: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error writing to register {register_address}: {e}")
            return False

    def get_values(self, register_map: List[Dict[str, Any]]) -> Optional[List[Optional[float]]]:
        values = []
        for register in register_map:
            if register.get('R/W') == 'R':
                address = int(register['Register'], 16)
                functioncode = register.get('functioncode', 3)
                values.append(self._read_register(address, register.get('number_of_decimals', 0), functioncode))
            else:
                values.append(None)
        return values

    def set_values(self, register_map: List[Dict[str, Any]], values: List[Any]) -> bool:
        if len(register_map) != len(values):
            logger.error("Register map and values lists must have the same length.")
            return False

        for register, value in zip(register_map, values):
            if register.get('R/W') == 'W':
                address = int(register['Register'], 16)
                functioncode = register.get('functioncode', 16)
                if not self._write_register(address, value, register.get('number_of_decimals', 0), functioncode):
                    return False
        return True

    def close(self):
        if self._client is not None:
            try:
                self._client.serial.close()
                logger.info("Modbus RTU client closed.")
            except Exception as e:
                logger.error(f"Error closing Modbus RTU client: {e}")
            finally:
                self._client = None

    def signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received. Shutting down gracefully.")
        self._running = False
        self.close()
        sys.exit(0)


class ServoMotorController:
    """
    A class for controlling a servo motor via Modbus RTU.
    """

    def __init__(self, port: str = '/dev/serial0', baudrate: int = 115200, timeout: float = 1.0):
        self.modbus = ModbusRTU(port, baudrate, timeout)
        signal.signal(signal.SIGINT, self.modbus.signal_handler)
        signal.signal(signal.SIGTERM, self.modbus.signal_handler)

        self.register_map: List[Dict[str, Any]] = [
            {'name': 'Position', 'R/W': 'R', 'Register': '0x0001', 'functioncode': 3},
            {'name': 'Velocity', 'R/W': 'R', 'Register': '0x0002', 'functioncode': 3},
            {'name': 'Torque', 'R/W': 'R', 'Register': '0x0003', 'functioncode': 3},
            {'name': 'TargetPosition', 'R/W': 'W', 'Register': '0x0004', 'functioncode': 16},
            {'name': 'TargetVelocity', 'R/W': 'W', 'Register': '0x0005', 'functioncode': 16},
            {'name': 'TargetTorque', 'R/W': 'W', 'Register': '0x0006', 'functioncode': 16},
        ]

    def get_status(self) -> Optional[List[Optional[float]]]:
        return self.modbus.get_values(self.register_map)

    def set_position(self, position: float) -> bool:
        write_map = [{'name': 'TargetPosition', 'R/W': 'W', 'Register': '0x0004', 'functioncode': 16}]
        return self.modbus.set_values(write_map, [position])

