import serial
import time
import logging
import signal
import sys
import atexit

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GSMModule:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=2, power_pin=4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self.ser = None
        self._owns_gpio = False
        self._owns_serial = False
        self._closed = False

        try:
            import RPi.GPIO as GPIO
            self.GPIO = GPIO
            self._owns_gpio = True
        except (ImportError, RuntimeError) as e:
            logging.warning(f"RPi.GPIO unavailable ({e}); power control disabled.")
            self.GPIO = None

        try:
            self.ser = serial.Serial(port, baudrate, timeout=timeout)
            self._owns_serial = True
            logging.info(f"Serial port {port} opened at {baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {port}: {e}")
            raise

        if self.GPIO:
            try:
                self.GPIO.setmode(self.GPIO.BCM)
                self.GPIO.setup(self.power_pin, self.GPIO.OUT, initial=self.GPIO.LOW)
                self._owns_gpio = True
            except Exception as e:
                logging.warning(f"Failed to initialize GPIO{power_pin}: {e}")
                self._owns_gpio = False

        self._power_on()
        self._wait_for_registration()
        self._verify_at()

    def _power_on(self):
        if not self._owns_gpio:
            logging.warning("GPIO not available; skipping power-on pulse.")
            return
        try:
            self.GPIO.output(self.power_pin, self.GPIO.HIGH)
            time.sleep(2)
            self.GPIO.output(self.power_pin, self.GPIO.LOW)
            time.sleep(1)
            logging.info("GSM module powered on.")
        except Exception as e:
            logging.error(f"Error during power-on sequence: {e}")
            raise

    def _wait_for_registration(self):
        logging.info("Waiting for network registration...")
        start = time.time()
        while time.time() - start < 3:
            try:
                self.ser.write(b'AT+CREG?\r\n')
                resp = self.read_response()
                if resp and '+CREG:0,1' in resp:
                    logging.info("Network registration successful.")
                    return
            except Exception as e:
                logging.error(f"Error during registration check: {e}")
            time.sleep(0.5)
        logging.warning("Network registration timed out.")

    def _verify_at(self):
        try:
            self.ser.write(b'AT\r\n')
            resp = self.read_response()
            if resp and 'OK' in resp:
                logging.info("GSM module is responsive.")
            else:
                raise RuntimeError(f"Unexpected AT response: {resp}")
        except Exception as e:
            logging.error(f"Failed to verify GSM module: {e}")
            raise

    def send_at_command(self, command):
        if not self.ser or not self.ser.is_open:
            raise RuntimeError("Serial port is not open.")
