import time
import signal
import sys

try:
    import board
    import busio
    from adafruit_servokit import ServoKit
except ImportError as exc:
    print(f"Missing dependency: {exc}. Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants for servo channels
BASE_SERVO = 0
DROP_SERVO = 1
SEEK_SERVO = 2
GRAB_SERVO = 4

# Constants for object drop positions
METAL_DROP_ANGLE = 135
PLASTIC_DROP_ANGLE = 180
PAPER_DROP_ANGLE = 90

# Default servo positions
DEFAULT_BASE_ANGLE = 90
DEFAULT_DROP_ANGLE = 100
DEFAULT_SEEK_ANGLE = 90
DEFAULT_GRAB_ANGLE = 120

# Servo limits
MIN_ANGLE = 0
MAX_ANGLE = 180

# Global state
kit = None
running = True


def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def initialize_servokit(channels=16):
    """Initialize the ServoKit with error handling."""
    global kit
    try:
        i2c = busio.I2C(board.SCL, board.SDA, frequency=100000)
        kit = ServoKit(channels=channels, i2c=i2c)
        return kit
    except Exception as e:
        print(f"Error initializing ServoKit: {e}")
        return None


def library_api_call(channels=16):
    """Initialize the ServoKit library."""
    return initialize_servokit(channels)


def move_servo(servo_channel, target_angle, step_size=5, delay=0.04):
    """Move a servo smoothly to a target angle with validation."""
    if kit is None:
        print("ServoKit not initialized.")
        return

    if not (MIN_ANGLE <= target_angle <= MAX_ANGLE):
        print(f"Error: target_angle {target_angle} out of range [{MIN_ANGLE}, {MAX_ANGLE}].")
        return

    if not (0 <= servo_channel < 16):
        print(f"Error: servo_channel {servo_channel} out of range [0, 15].")
        return

    try:
        current_angle = kit.servo[servo_channel].angle
        if current_angle is None:
            current_angle = MIN_ANGLE

        if target_angle > current_angle:
            angle_range = range(int(current_angle), int(target_angle) + 1, step_size)
        else:
            angle_range = range(int(current_angle), int(target_angle) - 1, -step_size)

        for angle in angle_range:
            if not running:
                break
            kit.servo[servo_channel].angle = angle
            time.sleep(delay)
    except Exception as e:
        print(f"Error moving servo {servo_channel}: {e}")


def seek(angle):
    """Move the seek servo to the specified angle."""
    move_servo(SEEK_SERVO, angle)


def deseek(angle):
    """Move the seek servo to the specified angle."""
    seek(angle)


def drop(angle):
    """Move the drop servo to the specified angle."""
    move_servo(DROP_SERVO, angle)


def pick(angle):
    """Move the drop servo to the specified angle."""
    drop(angle)


def grab(angle):
    """Move the grab servo to the specified angle."""
    move_servo(GRAB_SERVO, angle)


def release(angle):
    """Move the grab servo to the specified angle."""
    grab(angle)


def collect_object_steps(seek_angle):
    """Collect an object using a sequence of servo movements."""
    seek(seek_angle)
    grab(90)
    drop(160)
    pick(100)
    deseek(seek_angle)


def drop_object_steps(drop_angle):
    """Drop an object using a sequence of servo movements."""
    drop(drop_angle)
    release(120)
    drop(100)


def get_pos_x(x_center):
    """Calculate the base servo angle based on x-center position (0-320 pixels)."""
    if x_center <= 0:
        return 90
    elif x_center >= 320:
        return 90
    else:
        return int(90 + ((x_center - 160) / 160) * 90)


def get_pos_y(y_center):
    """Calculate the seek servo angle based on y-center position (0-240 pixels)."""
    if y_center <= 0:
        return 160
    elif y_center >= 240:
        return 80
    else:
        return int(160 - (y_center / 240) * 160)


def collect_object(x_center, y_center, drop_angle):
    """Collect and drop an object at the specified coordinates."""
    pos_x = get_pos_x(x_center)
    pos_y = get_pos_y(y_center)

    move_servo(BASE_SERVO, pos_x)
    collect_object_steps(pos_y)
    drop_object_steps(drop_angle)
    move_servo(BASE_SERVO, DEFAULT_BASE_ANGLE)


def cleanup():
    """Release resources cleanly."""
    global kit
    if kit is not None:
        try:
            for ch in range(16):
                kit.servo[ch].angle = None
        except Exception:
            pass
        kit = None


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    kit = library_api_call(16)
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        # Example usage
        collect_object(160, 120, METAL_DROP_ANGLE)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()
        print("Program finished.")

