import signal
import sys
import time

import board
import busio
import adafruit_seesaw.seesaw

PUMP_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_S = 10

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        soil_sensor = adafruit_seesaw.seesaw.Seesaw(i2c, addr=0x36)
    except Exception as exc:
        print(f"Error initializing Seesaw soil sensor at 0x36: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as exc:
        print(f"Error initializing GPIO{PUMP_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                moisture_level = soil_sensor.moisture_read()
            except Exception as exc:
                print(f"Error reading soil moisture: {exc}", file=sys.stderr)
                try:
                    GPIO.output(PUMP_PIN, GPIO.LOW)
                except Exception:
                    pass
                time.sleep(READ_INTERVAL_S)
                continue

            if moisture_level < DRY_SOIL_THRESHOLD:
                pump_status = "ON"
                try:
                    GPIO.output(PUMP_PIN, GPIO.HIGH)
                except Exception as exc:
                    print(f"Error turning pump ON: {exc}", file=sys.stderr)
                    pump_status = "UNKNOWN"
            else:
                pump_status = "OFF"
                try:
                    GPIO.output(PUMP_PIN, GPIO.LOW)
                except Exception as exc:
                    print(f"Error turning pump OFF: {exc}", file=sys.stderr)
                    pump_status = "UNKNOWN"

            print(f"Soil Moisture: {moisture_level}, Pump: {pump_status}")

            time.sleep(READ_INTERVAL_S)
    finally:
        try:
            GPIO.output(PUMP_PIN, GPIO.LOW)
        except Exception:
            pass
        GPIO.cleanup()
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

