import json
import signal
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO can only be run on a Raspberry Pi.", file=sys.stderr)
    sys.exit(1)

RELAY_PIN = 23
SERVER_ADDRESS = ('0.0.0.0', 5000)
_running = True


def _cleanup(signum=None, frame=None):
    global _running
    _running = False
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


class RelayHandler(BaseHTTPRequestHandler):
    def _send_json(self, status_code, payload):
        body = json.dumps(payload).encode('utf-8')
        self.send_response(status_code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except BrokenPipeError:
            pass

    def do_POST(self):
        if self.path != '/relay':
            self._send_json(404, {'error': 'Not found'})
            return

        content_length = int(self.headers.get('Content-Length', 0))
        if content_length <= 0:
            self._send_json(400, {'error': 'Invalid request'})
            return

        try:
            raw = self.rfile.read(content_length)
            data = json.loads(raw.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError):
            self._send_json(400, {'error': 'Invalid request'})
            return

        if not isinstance(data, dict) or 'state' not in data:
            self._send_json(400, {'error': 'Invalid request'})
            return

        state = data['state']
        if state not in ('on', 'off'):
            self._send_json(400, {'error': 'Invalid request'})
            return

        try:
            GPIO.output(RELAY_PIN, GPIO.HIGH if state == 'on' else GPIO.LOW)
        except Exception as exc:
            self._send_json(500, {'error': f'GPIO error: {exc}'})
            return

        self._send_json(200, {'status': 'Relay state changed'})

    def log_message(self, fmt, *args):
        sys.stderr.write(f"{self.address_string()} - {fmt % args}\n")


def main():
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as exc:
        print(f"Error initializing GPIO: {exc}", file=sys.stderr)
        sys.exit(1)

    httpd = HTTPServer(SERVER_ADDRESS, RelayHandler)
    print(f"Server running on {SERVER_ADDRESS[0]}:{SERVER_ADDRESS[1]}")
    try:
        while _running:
            httpd.handle_request()
    except Exception as exc:
        print(f"Server error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == '__main__':
    main()

