import signal
import sys
import logging
from typing import Optional

from driver import Pump, Light

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PUMP_PIN = 20
LIGHT_PIN = 21

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False
    logging.info("Signal %s received, shutting down...", signum)


def parse_intent(phrase: str) -> Optional[str]:
    keywords = {
        "pump on": "pump_on",
        "pump off": "pump_off",
        "light on": "light_on",
        "light off": "light_off",
        "toggle light": "light_toggle",
    }
    for kw, intent in keywords.items():
        if kw in phrase.lower():
            return intent
    return None


def apply_intent(pump: Pump, light: Light, intent: Optional[str]) -> None:
    if intent is None:
        logging.warning("Unknown intent: no recognized keywords in phrase")
        return
    try:
        if intent == "pump_on":
            pump.on()
            logging.info("Pump turned ON")
        elif intent == "pump_off":
            pump.off()
            logging.info("Pump turned OFF")
        elif intent == "light_toggle":
            light.toggle()
            logging.info("Light toggled")
        else:
            logging.warning("Unknown intent: %s", intent)
    except Exception as exc:
        logging.error("Error applying intent %s: %s", intent, exc)


def main() -> int:
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pump: Optional[Pump] = None
    light: Optional[Light] = None
    try:
        try:
            pump = Pump(PUMP_PIN)
            light = Light(LIGHT_PIN)
            logging.info("Pump on BCM %d, Light on BCM %d initialized", PUMP_PIN, LIGHT_PIN)
        except Exception as exc:
            logging.error("Failed to initialize pump or light: %s", exc)
            return 1

        phrases = [
            "turn the pump on",
            "switch the light",
            "turn pump off",
            "unknown command",
        ]

        for phrase in phrases:
            if not _running:
                break
            intent = parse_intent(phrase)
            logging.info("Phrase: %s | Intent: %s", phrase, intent)
            apply_intent(pump, light, intent)

    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
        return 1
    finally:
        for name, dev in (("pump", pump), ("light", light)):
            if dev is not None:
                try:
                    dev.close()
                    logging.info("%s closed", name)
                except Exception as exc:
                    logging.error("Error closing %s: %s", name, exc)
    return 0


if __name__ == "__main__":
    sys.exit(main())

