import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALERT_PIN = 18
RADIATION_THRESHOLD = 50.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        ser.reset_input_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_radiation_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Invalid data received (not a float): {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def control_alert_pin(pin, radiation_level, threshold):
    if radiation_level is not None:
        if radiation_level > threshold:
            GPIO.output(pin, GPIO.HIGH)
        else:
            GPIO.output(pin, GPIO.LOW)

def cleanup(serial_port):
    if serial_port is not None and serial_port.is_open:
        serial_port.close()
    GPIO.cleanup()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALERT_PIN, GPIO.OUT, initial=GPIO.LOW)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        cleanup(serial_connection)
        sys.exit(1)

    try:
        while _running:
            radiation_level = read_radiation_data(serial_connection)
            control_alert_pin(ALERT_PIN, radiation_level, RADIATION_THRESHOLD)
            if radiation_level is not None:
                print(f'Radiation Level: {radiation_level:.2f} uSv/h')
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup(serial_connection)

if __name__ == "__main__":
    main()

