import serial
import serial.tools.list_ports
import signal
import sys
import time
from typing import Optional

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_PIN = 17
FLOW_THRESHOLD = 10.0
READ_INTERVAL = 1.0

# Global flag for graceful shutdown
_running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def initialize_serial(port: str, baudrate: int, timeout: float) -> Optional[serial.Serial]:
    """Initialize the serial port with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        if not ser.is_open:
            print(f"Error: Failed to open serial port {port}.", file=sys.stderr)
            return None
        print(f"Serial port {port} opened successfully.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port {port}: {e}", file=sys.stderr)
        return None


def initialize_gpio(pin: int) -> bool:
    """Initialize the GPIO alarm pin."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        print(f"GPIO pin {pin} initialized as output (LOW).")
        return True
    except Exception as e:
        print(f"Error initializing GPIO pin {pin}: {e}", file=sys.stderr)
        return False


def read_flow_rate(ser: serial.Serial) -> Optional[float]:
    """Read a line from the serial port and parse it as a float flow rate."""
    try:
        raw = ser.readline()
        if not raw:
            return None  # Timeout, no data available
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Warning: Non-numeric data received: '{line}'", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading serial data: {e}", file=sys.stderr)
        return None


def control_alarm(pin: int, flow_rate: Optional[float], threshold: float) -> None:
    """Set the alarm pin HIGH if flow_rate exceeds threshold, otherwise LOW."""
    try:
        if flow_rate is not None and flow_rate > threshold:
            GPIO.output(pin, GPIO.HIGH)
            print(f"Flow rate: {flow_rate:.2f} L/min - ALARM ON")
        else:
            GPIO.output(pin, GPIO.LOW)
            if flow_rate is not None:
                print(f"Flow rate: {flow_rate:.2f} L/min - ALARM OFF")
            else:
                print("Flow rate: N/A - ALARM OFF")
    except Exception as e:
        print(f"Error controlling alarm pin: {e}", file=sys.stderr)


def cleanup(ser: Optional[serial.Serial], pin: int) -> None:
    """Release serial and GPIO resources."""
    if ser is not None and ser.is_open:
        try:
            ser.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}", file=sys.stderr)
    try:
        GPIO.cleanup()
        print("GPIO cleaned up.")
    except Exception as e:
        print(f"Error cleaning up GPIO: {e}", file=sys.stderr)


def main() -> None:
    """Main loop: read flow rate, control alarm, handle shutdown."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        sys.exit(1)

    if not initialize_gpio(ALARM_PIN):
        cleanup(ser, ALARM_PIN)
        sys.exit(1)

    print("Starting flow monitoring. Press Ctrl+C to exit.")

    try:
        while _running:
            flow_rate = read_flow_rate(ser)
            control_alarm(ALARM_PIN, flow_rate, FLOW_THRESHOLD)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Fatal error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup(ser, ALARM_PIN)
        print("Program terminated.")


if __name__ == "__main__":
    main()

