import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'
READ_INTERVAL = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_oximeter_data(raw_data):
    """Parse 'HR,SpO2' into (hr, spo2) or raise ValueError."""
    if not raw_data:
        raise ValueError('empty data')
    parts = raw_data.split(',')
    if len(parts) != 2:
        raise ValueError(f'expected 2 fields, got {len(parts)}')
    hr = int(parts[0].strip())
    spo2 = int(parts[1].strip())
    if not (0 <= hr <= 255):
        raise ValueError(f'heart rate {hr} out of range')
    if not (0 <= spo2 <= 100):
        raise ValueError(f'spO2 {spo2} out of range')
    return hr, spo2

def log_reading(log_path, hr, spo2):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    entry = f'{timestamp} - Heart Rate: {hr} bpm, SpO2: {spo2} %\n'
    with open(log_path, 'a', encoding='utf-8') as f:
        f.write(entry)
        f.flush()

def main():
    global _running
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')
            while _running:
                try:
                    raw = ser.readline()
                    if not raw:
                        print('No data received (timeout).')
                    else:
                        line = raw.decode('ascii', errors='replace').strip()
                        if not line:
                            print('Empty line received.')
                        else:
                            hr, spo2 = parse_oximeter_data(line)
                            print(f'Heart Rate: {hr} bpm, SpO2: {spo2} %')
                            log_reading(LOG_FILE, hr, spo2)
                except ValueError as e:
                    print(f'Parse error: {e} | raw: {line!r}')
                except serial.SerialException as e:
                    print(f'Serial I/O error: {e}')
                except OSError as e:
                    print(f'File I/O error: {e}')
                except Exception as e:
                    print(f'Unexpected error: {e}')
                if _running:
                    time.sleep(READ_INTERVAL)
    except serial.SerialException as e:
        print(f'Failed to open serial port {SERIAL_PORT}: {e}')
        sys.exit(1)
    except KeyboardInterrupt:
        print('\nInterrupted by user.')
    finally:
        print('Exiting program.')

if __name__ == '__main__':
    main()

