import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

import serial

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


@dataclass
class GPS_readings:
    """Container for a single parsed GPGGA reading."""
    latitude: float
    longitude: float
    altitude: float
    satellite_count: int


class GPSReader:
    """Reads and parses NMEA GPGGA sentences from a UART GPS module."""

    def __init__(
        self,
        port: str = "/dev/serial0",
        baudrate: int = 9600,
        timeout: float = 1.0,
    ) -> None:
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self._serial: Optional[serial.Serial] = None
        self._running = False

    # ------------------------------------------------------------------
    # Connection management
    # ------------------------------------------------------------------
    def connect(self) -> bool:
        """Open the serial port; return True on success, False on failure."""
        try:
            self._serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logging.info(
                "Connected to GPS on %s at %d baud (8N1, timeout %.1fs).",
                self.port, self.baudrate, self.timeout,
            )
            return True
        except serial.SerialException as exc:
            logging.error("Failed to open serial port %s: %s", self.port, exc)
            self._serial = None
            return False
        except OSError as exc:
            logging.error("OS error opening %s: %s", self.port, exc)
            self._serial = None
            return False

    def disconnect(self) -> None:
        """Close the serial port if open; never raises."""
        if self._serial is not None:
            try:
                if self._serial.is_open:
                    self._serial.close()
                    logging.info("Serial port %s closed.", self.port)
            except (serial.SerialException, OSError) as exc:
                logging.error("Error closing serial port %s: %s", self.port, exc)
            finally:
                self._serial = None

    # ------------------------------------------------------------------
    # NMEA parsing
    # ------------------------------------------------------------------
    @staticmethod
    def _verify_checksum(sentence: str) -> bool:
        """Validate the NMEA $...*CS format checksum."""
        if "*" not in sentence:
            return False
        body, _, csum_str = sentence.partition("*")
        if not body.startswith("$") or len(csum_str) < 2:
            return False
        try:
            expected = int(csum_str[:2], 16)
        except ValueError:
            return False
        computed = 0
        for ch in body[1:]:
            computed ^= ord(ch)
        return computed == expected

    @staticmethod
    def _nmea_to_decimal(value: str, direction: str) -> Optional[float]:
        """Convert NMEA ddmm.mmmm (or dddmm.mmmm) to signed decimal degrees."""
        if not value or not direction:
            return None
        try:
            raw = float(value)
        except ValueError:
            return None
        if direction in ("N", "S"):
            deg = int(raw / 100)
            minutes = raw - (deg * 100)
            decimal = deg + minutes / 60.0
            if direction == "S":
                decimal = -decimal
        elif direction in ("E", "W"):
            deg = int(raw / 100)
            minutes = raw - (deg * 100)
            decimal = deg + minutes / 60.0
            if direction == "W":
                decimal = -decimal
        else:
            return None
        return round(decimal, 6)

    def parse_gpgga(self, sentence: str) -> Optional[GPS_readings]:
        """Parse a single GPGGA sentence; return None on failure."""
        if not sentence or not sentence.startswith("$GPGGA"):
            return None
        if not self._verify_checksum(sentence):
            logging.warning("Checksum mismatch on GPGGA sentence: %s", sentence)
            return None
        fields = sentence.split(",")
        if len(fields) < 15:
            logging.warning("GPGGA field count %d < 15: %s", len(fields), sentence)
            return None
        try:
            fix_quality = int(fields[6])
        except ValueError:
            fix_quality = -1
        if fix_quality < 1:
            logging.debug("No GPS fix (quality=%s): %s", fields[6], sentence)
            return None
        lat = self._nmea_to_decimal(fields[2], fields[3])
        lon = self._nmea_to_decimal(fields[4], fields[5])
        if lat is None or lon is None:
            logging.warning("Invalid latitude/longitude in: %s", sentence)
            return None
        try:
            altitude = float(fields[9])
        except ValueError:
            logging.warning("Invalid altitude in: %s", sentence)
            return None
        try:
            sats = int(fields[7])
        except ValueError:
            logging.warning("Invalid satellite count in: %s", sentence)
            return None
        return GPS_readings(
            latitude=lat,
            longitude=lon,
            altitude=altitude,
            satellite_count=sats,
        )

    # ------------------------------------------------------------------
    # Main read loop
    # ------------------------------------------------------------------
    def read_gps_data(self) -> None:
        """Continuously read and parse GPGGA sentences until interrupted."""
        if not self._serial or not self._serial.is_open:
            logging.error("Serial port not open; call connect() first.")
            return
        self._running = True
        try:
            while self._running:
                try:
                    raw = self._serial.readline()
                except serial.SerialException as exc:
                    logging.error("Serial read error: %s", exc)
                    break
                except OSError as exc:
                    logging.error("OS read error: %s", exc)
                    break
                if not raw:
                    continue
                try:
                    line = raw.decode("ascii", errors="replace").strip()
                except Exception as exc:
                    logging.error("Decode error: %s", exc)
                    continue
                if not line:
                    continue
                readings = self.parse_gpgga(line)
                if readings is not None:
                    logging.info(
                        "Fix: lat=%.6f lon=%.6f alt=%.2f sats=%d",
                        readings.latitude, readings.longitude,
                        readings.altitude, readings.satellite_count,
                    )
        finally:
            self._running = False

    def stop(self) -> None:
        """Signal the read loop to stop."""
        self._running = False


# ----------------------------------------------------------------------
# Signal handling
# ----------------------------------------------------------------------
_reader: Optional[GPSReader] = None


def _signal_handler(signum, frame):
    logging.info("Signal %d received, shutting down.", signum)
    if _reader is not None:
        _reader.stop()


def main() -> int:
    global _reader
    _reader = GPSReader(port="/dev/serial0", baudrate=9600, timeout=1.0)
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    if not _reader.connect():
        return 1
    try:
        _reader.read_gps_data()
    finally:
        _reader.disconnect()
    return 0


if __name__ == "__main__":
    sys.exit(main())

