#!/usr/bin/env python3
"""Raspberry Pi web service exposing a UART-backed SCPI instrument query and a thread-safe in-memory data store."""

import signal
import sys
import threading
import time
from typing import Dict, List, Optional

from flask import Flask, Response, jsonify, request
import serial

app = Flask(__name__)

# Thread-safe UART resource
_uart_lock = threading.Lock()
_uart: Optional[serial.Serial] = None


def _open_uart() -> Optional[serial.Serial]:
    """Open the UART port if it is not already open. Returns the port or None on failure."""
    global _uart
    with _uart_lock:
        if _uart is not None and _uart.is_open:
            return _uart
        try:
            _uart = serial.Serial(
                port="/dev/ttyUSB0",
                baudrate=9600,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            return _uart
        except serial.SerialException as exc:
            print(f"[UART] Failed to open /dev/ttyUSB0: {exc}", file=sys.stderr)
            _uart = None
            return None


def _close_uart() -> None:
    """Close the UART port if open."""
    global _uart
    with _uart_lock:
        if _uart is not None and _uart.is_open:
            try:
                _uart.close()
            except serial.SerialException as exc:
                print(f"[UART] Error closing port: {exc}", file=sys.stderr)
        _uart = None


# In-memory data store
_data_store: List[Dict[str, object]] = [
    {"id": 1, "name": "item1", "done": False},
    {"id": 2, "name": "item2", "done": False},
]
_data_lock = threading.Lock()
_next_id = 3


def _get_item_by_id(item_id: int) -> Optional[Dict[str, object]]:
    """Return the item dict whose 'id' matches item_id, or None."""
    with _data_lock:
        return next((item for item in _data_store if item["id"] == item_id), None)


@app.route("/version", methods=["GET"])
def get_version() -> Response:
    """Query the connected SCPI instrument for its identity and return it as text/plain."""
    port = _open_uart()
    if port is None:
        return Response("Could not open UART port", status=500, mimetype="text/plain")

    try:
        port.reset_input_buffer()
        port.reset_output_buffer()
        port.write(b"*IDN?\n")
        port.flush()

        raw = port.readline()
        if not raw:
            return Response("No response from instrument (timeout)", status=504, mimetype="text/plain")

        response = raw.decode("ascii", errors="replace").strip()
        return Response(response, mimetype="text/plain")
    except serial.SerialException as exc:
        print(f"[UART] Serial error: {exc}", file=sys.stderr)
        return Response("Serial communication error", status=502, mimetype="text/plain")
    except Exception as exc:
        print(f"[UART] Unexpected error: {exc}", file=sys.stderr)
        return Response("Unexpected error", status=502, mimetype="text/plain")
    finally:
        _close_uart()


@app.route("/data", methods=["GET"])
def get_data() -> Response:
    """Return a JSON array of all items."""
    with _data_lock:
        return jsonify(_data_store)


@app.route("/data/<int:item_id>", methods=["GET"])
def get_item(item_id: int) -> Response:
    """Return a single item by id, or 404 if not found."""
    item = _get_item_by_id(item_id)
    if item is None:
        return Response("Item not found", status=404, mimetype="text/plain")
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_item() -> Response:
    """Create a new item from posted JSON: name (str), done (bool)."""
    global _next_id
    req = request.get_json(silent=True)
    if not isinstance(req, dict):
        return Response("Invalid request body", status=400, mimetype="text/plain")

    name = req.get("name")
    done = req.get("done", False)

    if not isinstance(name, str) or not name.strip():
        return Response("'name' must be a non-empty string", status=400, mimetype="text/plain")
    if not isinstance(done, bool):
        return Response("'done' must be a boolean", status=400, mimetype="text/plain")

    with _data_lock:
        new_item = {"id": _next_id, "name": name.strip(), "done": done}
        _data_store.append(new_item)
        _next_id += 1

    return jsonify(new_item), 201


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM by closing the UART port and exiting."""
    print(f"\n[main] Received signal {signum}, shutting down...")
    _close_uart()
    sys.exit(0)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        _close_uart()


if __name__ == "__main__":
    main()

