import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
READ_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_oximeter_data(data_string):
    if not data_string:
        return None, None
    parts = data_string.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 comma-separated fields, got {len(parts)}: '{data_string}'")
    try:
        heart_rate = int(parts[0].strip())
        spo2 = int(parts[1].strip())
    except ValueError as e:
        raise ValueError(f"Non-integer value in data: '{data_string}'") from e
    if not (0 <= heart_rate <= 255):
        raise ValueError(f"Heart rate out of range [0,255]: {heart_rate}")
    if not (0 <= spo2 <= 100):
        raise ValueError(f"SpO2 out of range [0,100]: {spo2}")
    return heart_rate, spo2

def display_data(heart_rate, spo2):
    print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    serial_connection = None
    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud.")
        while _running:
            try:
                raw_data = serial_connection.readline()
                if not raw_data:
                    continue
                decoded_data = raw_data.decode('ascii', errors='replace').strip()
                if not decoded_data:
                    continue
                try:
                    heart_rate, spo2 = parse_oximeter_data(decoded_data)
                    display_data(heart_rate, spo2)
                except ValueError as e:
                    print(f"Warning: invalid data format ({e}): '{decoded_data}'")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
            time.sleep(READ_INTERVAL)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")
        print("Exiting program.")

if __name__ == "__main__":
    main()

