import serial
import sys
import signal

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_meter_data(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        raise ValueError(f"Invalid data received from meter: {line!r}")
    except serial.SerialException as e:
        raise OSError(f"Serial communication error: {e}")

def log_power_consumption(power, log_file):
    timestamp = __import__('datetime').datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp} – Power: {power} W\n"
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
        while _running:
            try:
                power = read_meter_data(ser)
            except ValueError as e:
