    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        raise ValueError(f"Invalid data received from meter: {line!r}")
