import json
import time
import signal
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer
from socketserver import ThreadingMixIn
from typing import Any, Dict, List, Optional

try:
    import serial
except ImportError:
    serial = None

PORT = 8000
SERIAL_PORT = "/dev/ttyUSB0"
BAUDRATE = 9600
SERIAL_TIMEOUT = 1.0
READ_DELAY = 0.1

data_store: List[Dict[str, Any]] = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True},
]

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


class ThreadedHTTPServer(ThreadingMixIn, HTTPServer):
    allow_reuse_address = True
    daemon_threads = True


class RequestHandler(BaseHTTPRequestHandler):
    def _send_json(self, status: int, payload: Any) -> None:
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def _send_html(self, status: int, content: str) -> None:
        body = content.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def _send_text(self, status: int, content: str) -> None:
        body = content.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def _read_serial_response(self, ser: Any) -> Optional[str]:
        time.sleep(READ_DELAY)
        try:
            if ser.in_waiting > 0:
                raw = ser.read(ser.in_waiting)
                return raw.decode("utf-8", errors="replace").strip()
            return None
        except (serial.SerialException, OSError) as exc:
            print(f"[serial read error] {exc}", file=sys.stderr)
            return None

    def do_GET(self) -> None:
        if self.path == "/version":
            if serial is None:
                self._send_text(503, "Serial library not available")
                return
            try:
                ser = serial.Serial(
                    SERIAL_PORT, BAUDRATE, timeout=SERIAL_TIMEOUT
                )
            except (serial.SerialException, OSError) as exc:
                self._send_text(503, f"Serial port error: {exc}")
                return
            try:
                ser.write(b"*IDN?\n")
                ser.flush()
                response = self._read_serial_response(ser)
                if response is None:
                    self._send_text(503, "No response from instrument")
                else:
                    html = response.replace("\n", "<br>")
                    self._send_html(200, html)
            finally:
                try:
                    ser.close()
                except Exception:
                    pass
        elif self.path == "/getdata":
            self._send_json(200, data_store)
        elif self.path.startswith("/getset/"):
            try:
                item_id = int(self.path.split("/")[2])
            except (IndexError, ValueError):
                self._send_json(400, {"error": "Invalid item ID"})
                return
            item = next((i for i in data_store if i["id"] == item_id), None)
            if item is not None:
                self._send_json(200, item)
            else:
                self._send_json(404, {"error": "Item not found"})
        elif self.path.startswith("/getpost/"):
            try:
                item_id = int(self.path.split("/")[2])
                name = self.path.split("/")[3]
            except (IndexError, ValueError):
                self._send_json(400, {"error": "Invalid path format"})
                return
            new_item = {"id": item_id, "name": name, "done": False}
            data_store.append(new_item)
            self._send_json(201, data_store)
        else:
            self._send_text(404, "Not Found")

    def do_POST(self) -> None:
        if self.path == "/postjson":
            ctype = self.headers.get("Content-Type", "")
            if "application/json" in ctype:
                length = int(self.headers.get("Content-Length", 0))
                raw = self.rfile.read(length) if length > 0 else b""
                try:
                    payload = json.loads(raw.decode("utf-8")) if raw else {}
                except json.JSONDecodeError:
                    self._send_json(400, {"error": "Invalid JSON"})
                    return
            else:
                length = int(self.headers.get("Content-Length", 0))
                raw = self.rfile.read(length) if length > 0 else b""
                qs = raw.decode("utf-8", errors="replace") if raw else ""
                from urllib.parse import parse_qs
                payload = {k: v[0] if v else "" for k, v in parse_qs(qs).items()}

            if not isinstance(payload, dict):
                self._send_json(400, {"error": "Payload must be a JSON object"})
                return

            name = payload.get("name", "")
            done = str(payload.get("done", "false")).lower() == "true"

            new_id = (data_store[-1]["id"] + 1) if data_store else 1
            new_item = {"id": new_id, "name": name, "done": done}
            data_store.append(new_item)
            self._send_json(201, data_store)
        elif self.path == "/":
            self._send_json(200, data_store)
        else:
            self._send_text(404, "Not Found")

    def log_message(self, fmt: str, *args: Any) -> None:
        print(f"{self.address_string()} - {fmt % args}", file=sys.stderr)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        server = ThreadedHTTPServer(("0.0.0.0", PORT), RequestHandler)
    except OSError as exc:
        print(f"Failed to bind port {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Listening on 0.0.0.0:{PORT}")
    try:
        while _running:
            server.handle_request()
    except Exception as exc:
        print(f"Server error: {exc}", file=sys.stderr)
    finally:
        server.server_close()
        print("Server stopped.")


if __name__ == "__main__":
    main()

