import sys
import time
import signal

try:
    import bluetooth
except ImportError as exc:
    sys.stderr.write("Error: the 'bluetooth' module is not available.\n")
    sys.stderr.write("Install with: sudo apt install bluetooth bluez python3-bluez\n")
    raise exc

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400
COMMAND_PREFIX = "X"
DELAY_AFTER_SEND = 0.1


def send_command(sock, command):
    """Send a command prefixed with 'X' and terminated with a newline."""
    try:
        payload = (COMMAND_PREFIX + command + "\n").encode("utf-8")
        sock.send(payload)
        time.sleep(DELAY_AFTER_SEND)
    except OSError as exc:
        raise RuntimeError(f"Bluetooth send failed: {exc}") from exc


def main():
    sock = None
    try:
        sock = bluetooth.BluetoothSocket(bluetooth.RFCOMM)
        sock.connect((BLUETOOTH_DEVICE, BLUETOOTH_BAUDRATE))
        print(f"Connected to {BLUETOOTH_DEVICE} @ {BLUETOOTH_BAUDRATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command == "exit":
                break

            send_command(sock, user_command)
            print(f"Sent: {COMMAND_PREFIX}{user_command}")

    except RuntimeError as exc:
        sys.stderr.write(f"Runtime error: {exc}\n")
    except KeyboardInterrupt:
        print("\nInterrupted by user, exiting.")
    finally:
        if sock is not None:
            try:
                sock.close()
                print("Bluetooth connection closed.")
            except OSError:
                pass


if __name__ == "__main__":
    main()

